    ["Weapon swing timer for your melee auto-attacks (any melee class). Shows a main-hand bar and, while dual-wielding, an off-hand bar."] = "Таймер атаки для авто-атак в ближнем бою (для любого класса ближнего боя). Показывает полосу правой руки и, при бое двумя оружиями, полосу левой руки.",
    ["|cffaaaaaaShows when your next melee auto-attack lands (any melee class). The off-hand bar only appears while dual-wielding. The bar fills up toward the swing; the number is the time left.|r"] = "|cffaaaaaaПоказывает, когда произойдет следующая авто-атака в ближнем бою (для любого класса ближнего боя). Полоса левой руки появляется только при бое двумя оружиями. Полоса заполняется до момента удара; число — это оставшееся время.|r",
    ["Enable swing timer"] = "Включить таймер атаки",
    ["Foreground texture"] = "Текстура переднего плана",
    ["Foreground transparency"] = "Прозрачность переднего плана",
    ["Background texture"] = "Текстура фона",
    ["Background transparency"] = "Прозрачность фона",
    ["|cffffffffSWING TIMER|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffТАЙМЕР АТАКИ|r\\n|cffaaaaaaПеретаскивайте или стрелки|r",
    ["|cffffffffLOADOUTS SIDEBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffБОКОВАЯ ПАНЕЛЬ НАБОРОВ|r\\n|cffaaaaaaПеретаскивайте или стрелки|r",
    ["Swing Timer position: x=%.0f, y=%.0f"] = "Положение таймера атаки: x=%.0f, y=%.0f",
    ["Swing Timer mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Перемещение таймера атаки включено. |cff9b6cffПеретаскивайте фиолетовый блок|r или используйте |cff9b6cffстрелки|r (SHIFT = 5 пикс.). Нажмите «Разблокировать / Проверить» еще раз, чтобы закончить.",
    ["Swing Timer mover disabled."] = "Перемещение таймера атаки выключено.",
    ["Show off-hand bar (while dual-wielding)"] = "Показывать полосу левой руки (при бое двумя оружиями)",
    ["Show time remaining"] = "Показывать оставшееся время",
    ["Only show while attacking"] = "Показывать только во время атаки",
    ["Hides the bars unless you're auto-attacking. Turn off to always show them."] = "Скрывает полосы, если вы не ведете авто-атаку. Отключите, чтобы они отображались всегда.",
    ["Bar color"] = "Цвет полосы",
    ["Gap between bars"] = "Расстояние между полосами",
    ["Blue"] = "Синий",
    ["Green"] = "Зеленый",
    ["Gold"] = "Золотой",
    ["Red"] = "Красный",
    ["Fishing"] = "Рыбная ловля",
    ["Loadouts"] = "Наборы экипировки",
    ["Save and quickly equip gear sets for different specs, content, or roles."] = "Сохраняйте и быстро надевайте наборы экипировки для разных специализаций, контента или ролей.",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "Сохраняйте текущую экипировку как именованные наборы и быстро переключайтесь между ними. Надевать можно только вне боя — предметы из сумок надеваются автоматически через использование.",
    ["Save current equipment as a new loadout. Enter name:"] = "Сохранить текущую экипировку как новый набор. Введите название:",
    ["Confirm before deleting a loadout"] = "Подтверждать удаление набора",
    ["Saved Loadouts"] = "Сохраненные наборы",
    ["Equip"] = "Надеть",
    ["Overwrite"] = "Перезаписать",
    ["Delete"] = "Удалить",
    ["Save"] = "Сохранить",
