    ["items"] = "предметов",
    ["Please provide a name for the loadout."] = "Укажите название набора.",
    ["Loadout '%s' saved (%d items)."] = "Набор «%s» сохранен (предметов: %d).",
    ["Loadout '%s' updated with current gear."] = "Набор «%s» обновлен текущей экипировкой.",
    ["Loadout '%s' deleted."] = "Набор «%s» удален.",
