    ["Save trinkets only..."] = "Сохранить только аксессуары...",
    ["Save weapons only..."] = "Сохранить только оружие...",
    ["Settings..."] = "Настройки...",
    ["Minimap Button"] = "Кнопка на миникарте",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "Левая кнопка — меню быстрого переключения наборов, правая — настройки, перетаскивание — смена положения.",
    ["Left-click: switch set"] = "Левая кнопка: сменить набор",
    ["Right-click: settings"] = "Правая кнопка: настройки",
    ["Drag: reposition"] = "Перетаскивание: сменить положение",
    ["Auto-Switch on Stance/Form"] = "Автосмена при стойке/облике",
    ["Enable auto-switching"] = "Включить автосмену",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Автоматически надевает набор при смене стойки или облика (стойки воина, облики друида). Только вне боя — если стойка меняется в бою, смена откладывается до конца боя.",
    ["Auto-equip on form"] = "Автонадевание при облике",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Автоматически надевать этот набор при переходе в выбранную стойку или облик.",
    ["Auto-Switch on Dual Spec"] = "Автосмена при двойной специализации",
    ["Enable spec auto-switching"] = "Включить автосмену по специализации",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Автоматически надевает набор при переключении между специализациями 1 и 2 (двойная специализация). Привяжите наборы к специализациям ниже. Требуется активная двойная специализация.",
    ["Auto-equip on spec"] = "Автонадевание при специализации",
    ["Equip this loadout automatically when you switch to this spec."] = "Автоматически надевать этот набор при переходе на эту специализацию.",
    ["None"] = "Нет",
    ["No Form"] = "Без облика",
    ["Form %d"] = "Облик %d",
    ["Character Frame Sidebar"] = "Боковая панель рамки персонажа",
    ["Show sidebar on character frame"] = "Показывать боковую панель у рамки персонажа",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "Добавляет боковую панель быстрого доступа справа от окна персонажа. Нажатие — выбор набора, двойное нажатие или кнопка — надеть, правая кнопка — контекстное меню.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaСовет: при открытом окне персонажа включите режим правки (Разблокировать), чтобы перетащить боковую панель; щелчок правой кнопкой по фиолетовому блоку сбрасывает ее положение.|r",
    ["New Set"] = "Новый набор",
    ["Left-click: select"] = "Левая кнопка: выбрать",
    ["Double-click / Right-click menu: equip"] = "Двойное нажатие / меню правой кнопки: надеть",
    ["Change icon..."] = "Сменить значок...",
    ["Icon for: %s"] = "Значок для: %s",
    ["Bind to %s"] = "Привязать к %s",
