    ["not found"] = "не найдено",
    ["missing"] = "отсутствует",
    ["Part of set: %s"] = "Входит в набор: %s",
    ["Add a slot"] = "Добавить слот",
    ["Re-adds an ignored slot to this set."] = "Возвращает пропущенный слот в этот набор.",
    ["Right-click: remove this slot from the set."] = "Правая кнопка: убрать этот слот из набора.",
    ["Left-click to pick an item from your bags"] = "Левая кнопка — выбрать предмет из сумок",
    ["(equipped)"] = "(надето)",
    ["Slot Picker"] = "Выбор предмета для слота",
    ["Enable slot picker"] = "Включить выбор предмета для слота",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaaЩелкните правой кнопкой по слоту экипировки в окне персонажа, чтобы увидеть все подходящие предметы из сумок, и нажмите на предмет, чтобы надеть его.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "Наведите курсор на слот экипировки в рамке персонажа, чтобы получить компактную выпадающую полоску подходящих предметов из сумок, или щелкните с модификатором для большого закрепляемого окна выбора. Нажмите на предмет, чтобы надеть его (вне боя).",
    ["Flyout on hover"] = "Выпадающая полоска при наведении",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "При наведении на слот экипировки появляется компактная полоска предметов для замены — как выпадающие меню в окне персонажа. Отключите, чтобы использовать только выбор по щелчку с модификатором.",
    ["Activation modifier"] = "Клавиша-модификатор",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "Выберите сочетание клавиш, открывающее выбор предмета при щелчке по слоту экипировки.",
    ["Shift + Right-click"] = "Shift + правая кнопка",
    ["Alt + Right-click"] = "Alt + правая кнопка",
    ["Ctrl + Right-click"] = "Ctrl + правая кнопка",
