    ["Items for: %s"] = "Предметы для: %s",
    ["Close automatically on mouse-out"] = "Закрывать автоматически при уходе курсора",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "Окно выбора закрывается вскоре после того, как курсор его покидает. Перетащите его один раз, чтобы закрепить до ручного закрытия.",
