    ["Error."] = "Ошибка.",
    ["Share Profile"] = "Поделиться профилем",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaЭкспортируйте текущий профиль в виде текстовой строки — для резервной копии или чтобы поделиться им. Импорт всегда создает НОВЫЙ профиль и никогда ничего не перезаписывает.|r",
    ["Export as string"] = "Экспорт в строку",
    ["Import from string"] = "Импорт из строки",
    ["This is not a VuloClassicUI profile string."] = "Это не строка профиля VuloClassicUI.",
    ["The profile string is damaged."] = "Строка профиля повреждена.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "Профиль «%s» импортирован. Активируйте его через «Сменить профиль».",
    ["Manage Profiles"] = "Управление профилями",
