    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555Не удалось загрузить профиль «%s»:|r %s",
    ["Rename to"] = "Переименовать в",
    ["Rename"] = "Переименовать",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555Профиль по умолчанию нельзя удалить.|r",
    ["Apply to Active Class"] = "Применить к текущему классу",
    ["Sets the current profile as the default for %s."] = "Устанавливает текущий профиль как профиль по умолчанию для класса %s.",
    ["'%s' is now the default profile for %s."] = "«%s» теперь профиль по умолчанию для класса %s.",
    ["Per-class profile (quick setup)"] = "Профиль для каждого класса (быстрая настройка)",
