    ["Show Minimap Button"] = "Показывать кнопку миникарты",
    ["Toggle the VuloClassicUI button on the minimap."] = "Включает или отключает кнопку VuloClassicUI на миникарте.",
    ["Show CPU Usage in Header"] = "Показывать загрузку ЦП в заголовке",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "Показывает суммарную загрузку ЦП всеми активными аддонами (и долю самого VuloClassicUI) вверху заголовка настроек.\\n\\n|cffaaaaaaПосле переключения требуется /reload.\\n\\nПримечание: включает CVar scriptProfile, что стоит ~3-5% производительности — это плата за сбор этих данных самой игрой.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "Профилирование скриптов изменено. Для обновления отображения ЦП требуется /reload.",
    ["Reload now"] = "Перезагрузить сейчас",
    ["Later"] = "Позже",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "Показывает на миникарте кнопку для быстрого открытия VuloClassicUI. Shift+перетаскивание перемещает кнопку.",
    ["UI is not loaded yet."] = "Интерфейс еще не загружен.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffffЛевый клик:|r открыть настройки",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffffПравый клик:|r быстрый выбор модуля",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+перетаскивание:|r переместить кнопку",
    ["Open Options"] = "Открыть настройки",
    ["Show button on minimap"] = "Показывать кнопку на миникарте",
    ["If off, the button is completely hidden."] = "Если выключено, кнопка полностью скрыта.",
    ["Distance from center"] = "Расстояние от центра",
    ["Angle (degrees)"] = "Угол (градусы)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "Совет: кнопку можно перемещать и прямо на миникарте — удерживайте Shift и перетащите ее в нужное положение.",
    ["Font Bars"] = "Шрифты полос",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "Уменьшенные размеры шрифта для полос здоровья и маны игрока, цели и питомца, дополнительно скрытие TargetFrameBackground.",
    ["Health Bar Text"] = "Текст полосы здоровья",
    ["Font size on health bars (Player/Target/Pet)."] = "Размер шрифта на полосах здоровья (игрок, цель, питомец).",
    ["Power Bar Text"] = "Текст полосы ресурса",
    ["Font size on mana/power bars."] = "Размер шрифта на полосах маны и ресурсов.",
    ["Pet Combat Feedback Text"] = "Текст боевых сообщений питомца",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "Размер шрифта для «Урон», «Уклонение», «Промах» у питомца.",
    ["Only affect Player/Target/Pet bars"] = "Только полосы игрока, цели и питомца",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "Если выключено: все TextStatusBars в интерфейсе получат указанные выше размеры (может конфликтовать с другими аддонами).",
    ["Numeric threat %"] = "Числовая угроза в процентах",
    ["Threat glow"] = "Свечение угрозы",
    ["Class icon on player targets"] = "Значок класса на игроках-целях",
    ["Health"] = "Здоровье",
    ["Show real NPC health"] = "Показывать реальное здоровье NPC",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "Показывает истинное значение здоровья у NPC вместо скрытых процентов (у вражеских игроков остаются проценты).",
    ["Player Castbar"] = "Полоса заклинания игрока",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "Полоса заклинания игрока с двумя режимами: оригинальная (расширенная полоса Blizzard) или своя полоса заклинания (стиль VUI).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffПОЛОСА ЗАКЛИНАНИЯ|r\\n|cffaaaaaaПеретаскивание или стрелки|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "Положение полосы заклинания: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cffТерзание разума|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Перемещение полосы заклинания включено. |cff9b6cffПеретащите фиолетовый блок|r или используйте |cff9b6cffстрелки|r (SHIFT = 5 пикс.). Нажмите «Разблокировать / Тест» еще раз, чтобы закончить.",
    ["Castbar mover disabled."] = "Перемещение полосы заклинания отключено.",
    ["Castbar Variant"] = "Вариант полосы заклинания",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "Переключение между оригинальной (расширенная полоса Blizzard) и своей полосой заклинания (стиль VUI со значком и названием заклинания под полосой).",
    ["Original (Blizzard bar extended)"] = "Оригинальная (расширенная полоса Blizzard)",
    ["Custom Castbar (VUI style)"] = "Своя полоса заклинания (стиль VUI)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "Режим полосы заклинания переключен на |cff9b6cffоригинальный|r. Рекомендуется |cffffff00/reload|r, чтобы стандартная полоса снова работала нормально.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "Режим полосы заклинания переключен на |cff9b6cffстиль VUI|r.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaaСмена режима: после переключения может потребоваться /reload, чтобы стандартная полоса снова работала нормально.|r",
    ["Show spell name"] = "Показывать название заклинания",
    ["Show cast timer"] = "Показывать таймер произнесения",
    ["Show channel ticks"] = "Показывать отметки тиков",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "Показывает вертикальные линии в точках тиков («Терзание разума», «Вытягивание души», «Адское пламя» и т. д.)",
    ["Show clip window"] = "Показывать окно обрыва",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "Затеняет вашу задержку в конце полосы: у поддерживаемых заклинаний — момент перезапуска без потери последнего тика, у обычных — окно очереди заклинаний, когда уже можно нажать следующее.",
    ["Timer format"] = "Формат таймера",
    ["Remaining / total (1.5 / 2.0)"] = "Осталось / всего (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "Только оставшееся (1.5)",
    ["Whole seconds (2)"] = "Целые секунды (2)",
    ["Show pushback"] = "Показывать потерю времени от урона",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "Кратко показывает красным над полосой время, потерянное из-за сбива произнесения уроном.",
    ["Merge crafting casts"] = "Объединять серийное создание предметов",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "При создании нескольких предметов подряд полоса показывает счетчик вида 3/20 вместо отдельных произнесений.",
    ["Fill color"] = "Цвет заполнения",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "Текстуры полосы — классическая желто-зеленая графика. Акцентный цвет или цвет класса вместо этого окрашивают нейтральную полосу.",
    ["Bar textures (yellow/green)"] = "Текстуры полосы (желтая/зеленая)",
    ["Accent color"] = "Акцентный цвет",
    ["VUI Style: Position & Size"] = "Стиль VUI: положение и размер",
    ["Unlock / Test"] = "Разблокировать / Тест",
    ["Center Position"] = "Положение центра",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaaСовет: удерживайте |cffffffffSHIFT|r и перетащите полосу заклинания левой кнопкой мыши во время произнесения, чтобы переместить ее. Или используйте «Разблокировать / Тест» для постоянной тестовой полосы при настройке положения.|r",
    ["Show icon"] = "Показывать значок",
    ["Icon Size"] = "Размер значка",
    ["Icon X Offset"] = "Смещение значка по X",
    ["Icon Y Offset"] = "Смещение значка по Y",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "Двигает значок по горизонтали. Отрицательное — влево, положительное — вправо.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "Двигает значок по вертикали. Положительное — вверх, отрицательное — вниз.",
    ["Test only available in 'Custom Castbar' mode."] = "Тест доступен только в режиме «Своя полоса заклинания».",
    ["Cooldown Pulse"] = "Пульс восстановления",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center."] = "Показывает значок завершенного восстановления в виде короткой пульсирующей анимации в центре экрана.",
    ["Test Spell"] = "Тестовое заклинание",
    ["Cooldown Pulse position reset."] = "Положение пульса восстановления сброшено.",
