    ["Animation Scale"] = "Масштаб анимации",
    ["Fade-In Time (s)"] = "Время появления (с)",
    ["Hold Time (s)"] = "Время удержания (с)",
    ["Fade-Out Time (s)"] = "Время исчезновения (с)",
    ["Show Before Available (s)"] = "Показывать до готовности (с)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "Запускает анимацию за X секунд ДО окончания восстановления. 0 — точно в момент окончания.",
