    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "Названия заклинаний точно как в игре, через запятую. ID заклинаний тоже работают.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555Ошибка подмодуля ArenaFrames:|r %s",
