    ["Auto-repair"] = "Автопочинка",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Чинит все снаряжение у торговца, если золота хватает.",
    ["Stack-split popup: MAX button"] = "Окно деления стопки: кнопка МАКС",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Добавляет кнопку «МАКС» в окно количества. Клик — купить полную стопку (у торговца) или разделить полностью (для предметов в сумке).",
    ["Stack-split popup: VuloUI look"] = "Окно деления стопки: стиль VuloUI",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Меняет стиль окна количества (покупка и деление стопок) под вид аддона: темная панель, аккуратные кнопки и стрелки. Отключение требует /reload.",
    ["Hide UI error messages"] = "Скрыть сообщения об ошибках интерфейса",
    ["Hides the red error messages in the screen center."] = "Скрывает красные сообщения об ошибках в центре экрана.",
    ["Hide zone text"] = "Скрыть название зоны",
    ["Hides the large zone name when entering new areas."] = "Скрывает крупное название зоны при входе в новую местность.",
    ["Hide level numbers on portrait"] = "Скрыть уровень на портрете",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Скрывает отображение уровня на портрете игрока, цели и питомца.",
    ["Hide keybind text on action buttons"] = "Скрыть подписи горячих клавиш на кнопках команд",
