    ["Hide macro/spell names on action buttons"] = "Скрыть названия макросов и заклинаний на кнопках команд",
    ["Hides the text labels under the action buttons."] = "Скрывает текстовые подписи под кнопками команд.",
    ["Hide stack/charge numbers on action buttons"] = "Скрыть числа стопок и зарядов на кнопках команд",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Скрывает мелкие рамки с числами в правом верхнем углу (стопки предметов, заряды, секунды длинных восстановлений).",
    ["Hide raid group labels"] = "Скрыть подписи групп рейда",
    ["Mail Text Size"] = "Размер текста почты",
