    ["Queue Timer"] = "Таймер очереди",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Показывает обратный отсчет в окне готовности очереди PvP и PvE. Дополнительно звуковое предупреждение за 5 секунд.",
