    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaСобственные кнопки для каждой панели команд (1-5): настоящий показ/скрытие в бою и при наведении, масштаб и сетка, правильное переключение страниц основной панели (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. Каждая перемещается в Режиме редактирования (/vedit). После отключения введите /reload, чтобы полностью вернуть панели Blizzard.|r",
