    ["Game Menu"] = "Игровое меню",
    ["Game menu: VuloUI look"] = "Игровое меню: стиль VuloUI",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Меняет оформление меню Escape под стиль аддона: темная панель, плоские кнопки, акцентный заголовок. Изменение требует /reload.",
    ["Game menu: VuloClassicUI button"] = "Игровое меню: кнопка VuloClassicUI",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Добавляет в меню Escape кнопку VuloClassicUI, открывающую окно настроек. Отключение требует /reload.",
    ["Hide the FPS / latency bar"] = "Скрыть панель FPS / задержки",
