    ["Value + percent"] = "Значение + процент",
    ["Tint background with bar colour"] = "Окрашивать фон цветом полосы",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "Пустая часть полосы окрашивается затемненным оттенком цвета полосы вместо простого темно-серого.",
    ["Rounded bar corners"] = "Скругленные углы полосы",
    ["Overall plate scale (%)"] = "Общий масштаб индикаторов (%)",
    ["Scales every plate at once, on top of each individual size."] = "Масштабирует все индикаторы сразу, поверх индивидуальных размеров.",
    ["Vertical offset"] = "Смещение по вертикали",
    ["Moves every plate up or down relative to its unit."] = "Смещает все индикаторы вверх или вниз относительно их существ.",
    ["Font outline"] = "Контур шрифта",
    ["Thick outline"] = "Толстый контур",
    ["Show level"] = "Показывать уровень",
    ["0 = uses the name size."] = "0 = использует размер имени.",
    ["Your Own Debuffs"] = "Ваши отрицательные эффекты",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaaОтдельный ряд для вредоносных эффектов, наложенных вами, — ваши таймеры периодического урона, отделенные от всего остального на цели.|r",
    ["Show your own debuffs (separate row)"] = "Показывать ваши отрицательные эффекты (отдельный ряд)",
    ["Max icons"] = "Макс. значков",
    ["Icons per line"] = "Значков в строке",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = одна строка. Иначе ряд переносится после этого количества значков.",
    ["Reminders"] = "Напоминания",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaaПоказывает короткий ряд значков с тем, чего вам сейчас не хватает. Вне боя щелчок применяет нужное действие, а наведение поясняет, чего не хватает. В бою ряд остается неподвижным.|r",
    ["Also warn about empty equipment slots"] = "Предупреждать и о пустых ячейках экипировки",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "По умолчанию выключено: кольцо, аксессуар или плащ во время прокачки часто пусты вполне обоснованно.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "Показывает, чего вам не хватает: классовых эффектов, чар на оружии, еды, стойки, питомца, боеприпасов, прочности, пустых ячеек экипировки и нераспределенных очков талантов.",
    ["What to watch"] = "Что отслеживать",
    ["Class buffs"] = "Классовые эффекты",
    ["Weapon enchants"] = "Чары на оружии",
    ["Stance and aura"] = "Стойка и аура",
    ["Food and flask"] = "Еда и настой",
    ["Ammo, durability, gear, talents"] = "Боеприпасы, прочность, экипировка, таланты",
    ["Most icons at once"] = "Макс. значков одновременно",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "Все сверх этого объединяется в один счетчик вместо добавления новых значков.",
    ["Show labels"] = "Показывать подписи",
    ["Settle time (seconds)"] = "Задержка появления (секунды)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "Сколько времени чего-то должно не хватать, прежде чем появится значок. Не дает значкам мигать между заклинаниями.",
    ["Warn when under (seconds)"] = "Предупреждать при остатке (секунды)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "Также предупреждать, когда эффект или чары на оружии скоро закончатся. 0 = предупреждать, только когда их нет.",
    ["Durability below (%)"] = "Прочность ниже (%)",
    ["Ammo below"] = "Боеприпасов меньше",
