    ["Unspent talent points: %d"] = "Нераспределенных очков талантов: %d",
    ["Racials"] = "Расовые способности",
    ["Racial Cooldowns"] = "Восстановление расовых способностей",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Показывает расовую способность противника и ее восстановление, как только он ее применит. Это восстановления текущего дополнения, и ни одна расовая способность пока не делит восстановление с PvP-аксессуаром.",
    ["Show racial cooldown"] = "Показывать восстановление расовой способности",
    ["Shadow Sight"] = "Темное зрение",
    ["Shadow Sight up"] = "Темное зрение активно",
    ["Shadow Sight up - next in %d s"] = "Темное зрение активно — следующее через %d с",
    ["Shadow Sight in %d s"] = "Темное зрение через %d с",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Отсчитывает время до сфер на арене: первая пара появляется через 95 секунд после открытия ворот, и каждая возвращается через 122 секунды после того, как ее взяли.",
    ["Show Shadow Sight timer"] = "Показывать таймер Темного зрения",
    ["Aura on the class icon"] = "Эффект на значке класса",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Помещает на значок класса противника один самый важный эффект: неуязвимость важнее контроля, контроль важнее защитной способности, а та важнее атакующей.",
    ["Show aura on the class icon"] = "Показывать эффект на значке класса",
    ["Crowd control only"] = "Только контроль",
    ["Dispels"] = "Рассеивание",
    ["Dispel Cooldowns"] = "Восстановление рассеивания",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaУ большинства способов рассеивания в этом дополнении нет восстановления, поэтому здесь могут появиться только «Массовое рассеивание» и «Пожирание магии» ищейки Скверны.|r",
    ["Show dispel cooldown"] = "Показывать восстановление рассеивания",
    ["Range"] = "Дальность",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Приглушает рамку, пока противник вне досягаемости; расстояние определяется по заклинанию вашего класса, а не по фиксированной дистанции.",
    ["Fade out-of-range opponents"] = "Приглушать противников вне досягаемости",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Отменить изменения и вернуть все окна к последнему сохранению или к состоянию на момент открытия Режима редактирования.",
    ["Discard all changes made since the last save?"] = "Отменить все изменения, сделанные после последнего сохранения?",
    ["Grey out when you walk out of range"] = "Обесцвечивать при выходе из радиуса",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Убирает цвет, пока вы находитесь вне радиуса тотема, и возвращает его, когда вы возвращаетесь. Определяется по эффекту, который тотем накладывает на вас, поэтому тотемы без эффекта (испепеления, магмы, дрожи земли, ...) всегда остаются яркими.",
    ["Limit to"] = "Ограничить",
    ["Everything"] = "Все",
    ["Only mine"] = "Только мои",
    ["Only removable"] = "Только снимаемые",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Сужает этот ряд до эффектов, наложенных вами, или до тех, которые можно снять.",
    ["Show who interrupted"] = "Показывать, кто прервал",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "Вспышка прерывания показывает имя того, кто его выполнил.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "Вкл.: 9,9, 3,4 … Выкл.: целые секунды (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "«Современный» помещает настоящие кнопки сумок на плоскую темную полосу в стиле VuloUI — открытие, замена и подсказки не меняются.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "«Современный» заменяет кнопки Blizzard плоской темной полосой значков в стиле VuloUI. Щелчки и подсказки не меняются.",
    ["Classic (Blizzard buttons)"] = "Классический (кнопки Blizzard)",
    ["Modern (flat icon strip)"] = "Современный (плоская полоса значков)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Скрывает ряд кнопок меню (персонаж, книга заклинаний, …).",
    ["Hide the bag bar"] = "Скрыть панель сумок",
    ["Hides the backpack and bag slots."] = "Скрывает рюкзак и ячейки сумок.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cffМикроменю, панель сумок, панель FPS/задержки и панель опыта ниже перемещаются в Режиме редактирования (/vedit), как и панели команд.|r",
