    ["Plate view distance"] = "Дальность видимости индикаторов",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaaПока клавиша удерживается (или совпадает ваша цель), основная панель показывает способности выбранной панели. Полностью безопасно — работает в бою.|r",
    ["Shift held"] = "Удержание Shift",
    ["Ctrl held"] = "Удержание Ctrl",
    ["Alt held"] = "Удержание Alt",
    ["Friendly target"] = "Дружественная цель",
    ["Hostile target"] = "Враждебная цель",
    ["Group visibility"] = "Видимость в группе",
    ["Always"] = "Всегда",
    ["Only in a group"] = "Только в рейде или группе",
    ["Only in a party"] = "Только в группе",
    ["Only solo"] = "Только в одиночку",
    ["Hide when mounted"] = "Скрывать верхом",
    ["Hide without target"] = "Скрывать без цели",
    ["Hide without enemy target"] = "Скрывать без враждебной цели",
    ["Quick keybind mode (/vkb)"] = "Режим быстрого назначения клавиш (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Наведите курсор на кнопку и нажмите клавишу, чтобы назначить ее. Скрытые панели показываются на время назначения.",
    ["Swipe colour"] = "Цвет затемнения восстановления",
    ["Icon opacity on cooldown"] = "Непрозрачность значка при восстановлении",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Приглушает весь значок, пока способность на восстановлении (100 = выкл.).",
    ["Show cooldown numbers"] = "Показывать числа восстановления",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Собственные числа обратного отсчета игры на восстановлениях (настройка игры, применяется сразу).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaПрименяется ко всем панелям команд.|r",
    ["Cooldown swipe opacity"] = "Непрозрачность затемнения восстановления",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Насколько темным будет наложение отсчета восстановления (0 = невидимо).",
    ["Desaturate icons on cooldown"] = "Обесцвечивать значки при восстановлении",
    ["Out-of-range colouring"] = "Окраска вне досягаемости",
    ["Tints the whole icon while your target is out of range."] = "Окрашивает весь значок, пока ваша цель вне досягаемости.",
    ["Tooltips"] = "Подсказки",
    ["Hide in combat"] = "Скрывать в бою",
    ["Hide always"] = "Скрывать всегда",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Перемещаемая полоса опыта с изменяемым размером и зоной отдохнувшего опыта. Скрыта на максимальном уровне. Пока включена, заменяет полосу Blizzard.",
    ["Hide Blizzard's XP / reputation bar"] = "Скрыть полосу опыта / репутации Blizzard",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Убирает оставшуюся синюю полосу опыта / репутации под панелью команд.",
    ["Stance bar"] = "Панель стоек",
    ["Pet bar"] = "Панель питомца",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Берет все панели команд под свое управление собственными перемещаемыми рамками: настоящий показ/скрытие в бою и при наведении, масштаб и сетка для каждой панели, правильное переключение страниц основной панели (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. ЭКСПЕРИМЕНТАЛЬНО — проверьте нажатие способностей и смену страниц в бою; после отключения введите /reload.",
    ["Standard action bars are back. Reload the interface to restore every last piece of the default layout."] = "Стандартные панели команд вернулись. Перезагрузка интерфейса восстановит порядок по умолчанию до последней детали.",
    ["Buttons per row"] = "Кнопок в ряду",
    ["Button spacing"] = "Расстояние между кнопками",
    ["World"] = "Мир",
    ["Crisp portrait hit numbers"] = "Четкие числа урона на портрете",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Отображает числа урона/исцеления на портрете персонажа или питомца четким шрифтом фиксированного размера вместо размытой растущей анимации Blizzard.",
    ["Hit number size"] = "Размер чисел урона",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Размер шрифта чисел на портрете (при включенной опции «Четкие»).",
    ["Auto-select single gossip option"] = "Автовыбор единственного варианта диалога",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Пропускает окна диалога с NPC, в которых есть лишь один вариант ответа. Удерживайте SHIFT, чтобы временно отключить.",
    ["Faster auto-loot"] = "Быстрый автосбор добычи",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "Собирает все предметы разом при автосборе добычи, а не по одному.",
    ["Max camera zoom"] = "Максимальное отдаление камеры",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "Увеличивает максимальное расстояние отдаления камеры далеко за пределы стандартного.",
    ["Player & Target Frame"] = "Рамка игрока и цели",
    ["Target & Focus Frame"] = "Рамка цели и фокуса",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaaДобавляет золотого элитного дракона (или редкие варианты) вокруг портрета вашего персонажа — так выглядят элитные существа в рамке цели.|r",
    ["Frame style"] = "Стиль рамки",
    ["Elite (golden dragon)"] = "Элитный (золотой дракон)",
    ["Rare-Elite (silver dragon)"] = "Редкий элитный (серебряный дракон)",
    ["Rare (silver)"] = "Редкий (серебряный)",
    ["Off (default frame)"] = "Выкл. (обычная рамка)",
    ["Cooldown Manager"] = "Менеджер восстановления",
    ["Cooldowns"] = "Восстановления",
    ["Delete group"] = "Удалить группу",
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888В этой группе пока пусто.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Группа восстановления «%s» разблокирована. Перетаскивайте на нее заклинания и предметы; |cff9b6cffперетащите|r, чтобы переместить.",
    ["Cooldown group '%s' locked."] = "Группа восстановления «%s» заблокирована.",
    ["Group type"] = "Тип группы",
    ["Buffs & Procs (only show while active)"] = "Эффекты и срабатывания (показывать только активные)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaЗначки появляются, только пока на вас действует эффект или срабатывание; в остальное время панель пуста. Добавляйте ЭФФЕКТ (например, «Ясновидение») по названию или ID.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaЗначки показывают восстановление каждого заклинания или аксессуара.|r",
    ["Size & offsets"] = "Размер и смещения",
    ["Extra settings"] = "Дополнительные настройки",
    ["Friends List"] = "Список друзей",
    ["Dialog Popups"] = "Диалоговые окна",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Оформляет стандартные диалоги подтверждения Blizzard (отсчет выхода из игры, удаление предмета, воскрешение, приглашение в группу) в темном стиле.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaОформляет стандартные диалоги подтверждения Blizzard — отсчет выхода из игры, удаление предмета, воскрешение, приглашение в группу — в темном стиле.|r",
    ["Accent strip"] = "Акцентная полоса",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Рисует тонкий акцентный градиент вдоль верхнего края каждого диалога.",
    ["Addon Skins"] = "Оформление аддонов",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Оформляет окна поддерживаемых сторонних аддонов в темном стиле: список ошибок, отслеживание заданий, обзор добычи, профилировщик и другое.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaОформляет окна поддерживаемых аддонов в темном стиле. Оформление применяется при загрузке аддона; для отключения нужен /reload (отслеживание заданий восстанавливается сразу).|r",
    ["not loaded"] = "не загружен",
    ["Dark window skin"] = "Темное оформление окна",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Оформляет все окно друзей в темных тонах с фиолетовыми акцентами. Для отключения нужен /reload, чтобы вернуть стандартную рамку Blizzard.",
    ["Class color names"] = "Имена в цветах класса",
    ["Colors each online friend's name by their class."] = "Окрашивает имя каждого друга в сети в цвет его класса.",
    ["Show class icons"] = "Показывать значки классов",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Показывает значок класса рядом с друзьями в WoW, находящимися в сети (в игре и в Battle.net).",
    ["Class icon style"] = "Стиль значков классов",
    ["Blizzard crests"] = "Гербы Blizzard",
    ["Circles"] = "Круги",
    ["Squares"] = "Квадраты",
    ["Show status dot"] = "Показывать точку статуса",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Цветная точка после имени: зеленая — в сети, желтая — отошел, красная — занят, серая — не в сети.",
    ["Show friend notes"] = "Показывать заметки о друзьях",
    ["Shows your saved note for the friend in grey under their name."] = "Показывает сохраненную заметку о друге серым цветом под его именем.",
    ["Faction"] = "Фракция",
    ["Faction accent on realm line"] = "Акцент фракции в строке игрового мира",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Окрашивает строку игрового мира и зоны в красный (Орда) или синий (Альянс) цвет.",
    ["Faction row tint"] = "Подсветка строки по фракции",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Добавляет легкую красную или синюю подсветку фона в строке каждого друга в сети.",
    ["Invites"] = "Приглашения",
    ["Auto-accept Battle.net friend invites"] = "Автоприем заявок в друзья Battle.net",
    ["Automatically accepts incoming Battle.net friend requests."] = "Автоматически принимает входящие заявки в друзья Battle.net.",
    ["Auto-accept group invites from friends"] = "Автоприем приглашений в группу от друзей",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Автоматически принимает вступление в группу, если приглашение пришло от игрока из вашего списка друзей.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Имена в цветах класса, значки классов, точки статуса, встроенные заметки, подсветка фракции и необязательный автоприем.",
    ["Highlight"] = "Подсветка",
