    ["White"] = "Белый",
    ["Cooldown Manager: '%s' is not a known spell or item."] = "Менеджер восстановления: «%s» — неизвестное заклинание или предмет.",
    ["Cooldown Manager: already tracking that."] = "Менеджер восстановления: это уже отслеживается.",
