    ["Protection"] = "Защита",
    ["Block group invites from strangers"] = "Блокировать приглашения в группу от незнакомцев",
    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "Автоматически отклоняет приглашения в группу или рейд от игроков, которых нет в вашей гильдии или списке друзей.",
    ["Block trades from strangers"] = "Блокировать обмен с незнакомцами",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "Автоматически закрывает окна обмена, открытые игроками, которых нет в вашей гильдии или списке друзей. Обмены, начатые вами, не затрагиваются.",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[QoL]|r Заблокировано приглашение в группу от %s (не гильдия/друг).",
    ["|cffffd200[QoL]|r Blocked trade from %s (not guild/friend)."] = "|cffffd200[QoL]|r Заблокирован обмен от %s (не гильдия/друг).",
    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "Добавляет в книгу заклинаний вкладку со способностями, которым вы еще можете обучиться у классового учителя, сгруппированными по уровням. Откройте значок книги под школами заклинаний.",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaaДобавляет в книгу заклинаний вкладку (значок книги сбоку, под школами заклинаний) со всеми способностями, которым вы еще можете обучиться у классового учителя — сгруппированы по состоянию и окрашены по уровню. Посещать учителя не нужно.|r",
    ["Available now"] = "Доступно сейчас",
    ["Available but Missing Requirements"] = "Доступно, но не хватает требований",
    ["Upcoming"] = "Скоро",
    ["Not Yet Available"] = "Пока недоступно",
    ["Missing Required Talents"] = "Не хватает нужных талантов",
    ["Already Known"] = "Уже изучено",
    ["Level %d"] = "Уровень %d",
    ["Cost: %s"] = "Стоимость: %s",
    ["What can I train?"] = "Чему я могу обучиться?",
    ["No results found"] = "Ничего не найдено",
    ["Anchor to window..."] = "Привязать к окну...",
    ["WIDTH LIKE"] = "ШИРИНА КАК У",
    ["HEIGHT LIKE"] = "ВЫСОТА КАК У",
    ["Takes its width from another window and keeps it."] = "Берет ширину у другого окна и сохраняет ее.",
    ["Takes its height from another window and keeps it."] = "Берет высоту у другого окна и сохраняет ее.",
    ["This window sets its own size - the match will not stick."] = "Это окно задает свой размер само — совпадение не сохранится.",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "Перетащите блок или наведите на него курсор и жмите стрелки (Shift = 5px). Удерживайте Shift при перетаскивании, чтобы зафиксировать одну ось. Shift+ПКМ скрывает мешающий блок.",
    ["Then click any window to anchor this one to it."] = "Затем нажмите на любое окно, чтобы привязать это окно к нему.",
    ["Click a window to anchor it (right-click to cancel)."] = "Нажмите на окно, чтобы привязаться к нему (ПКМ — отмена).",
    ["ANCHOR SIDE"] = "СТОРОНА ПРИВЯЗКИ",
    ["Centered"] = "По центру",
    ["Top of"] = "Сверху от",
    ["Bottom of"] = "Снизу от",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "Оставить это окно разблокированным, чтобы его можно было перетаскивать после закрытия Режима редактирования. Разблокировка сохраняется после /reload.",
    ["SAVED"] = "СОХРАНЕНО",
    ["Save current as..."] = "Сохранить текущую как...",
    ["Import"] = "Импорт",
    ["Export"] = "Экспорт",
    ["Imported"] = "Импортировано",
    ["Import failed (%s)."] = "Не удалось импортировать (%s).",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "Скопируйте эту строку (Ctrl+A, Ctrl+C):",
    ["Move it in the unified Edit Mode (/vedit)."] = "Перемещается в едином Режиме редактирования (/vedit).",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "Перетащите блок боевого текста в едином Режиме редактирования (/vedit).",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44Режим редактирования ВКЛЮЧЕН.|r Закройте это окно, чтобы добраться до блоков.",
    ["Dark Mode"] = "Темный режим",
    ["Desaturate (greyscale)"] = "Обесцветить (оттенки серого)",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "Убирает цвет из оформления перед окрашиванием, для настоящих оттенков серого. Выкл. — сохраняется намек на исходный оттенок.",
    ["Tint colour"] = "Цвет оттенка",
    ["Action bar artwork"] = "Оформление панели команд",
    ["The gryphons and the metal action-bar background."] = "Грифоны и металлический фон панели команд.",
    ["Bag slots"] = "Ячейки сумок",
    ["Chat"] = "Чат",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "Улучшает чат Blizzard: темная панель с боковой панелью значков, метки времени, имена в цвете класса, кликабельные ссылки, темные вкладки, затухание при бездействии и история, переживающая /reload. Каждая часть необязательна.",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaaУлучшает собственный чат Blizzard — ничего не заменяется, поэтому все остается легким и совместимым. Каждая опция ниже независима.|r",
    ["Timestamps"] = "Метки времени",
    ["Show timestamps"] = "Показывать метки времени",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "Добавляет время в начало каждой строки, используя настройку меток времени самой игры.",
    ["Time format"] = "Формат времени",
    ["Names & links"] = "Имена и ссылки",
    ["Class-coloured names"] = "Имена в цвете класса",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "Окрашивает имена игроков по их классу в чате, группе, рейде, гильдии, шепоте и каналах.",
    ["Clickable links"] = "Кликабельные ссылки",
    ["Turns web links into clickable links that open a copy box."] = "Превращает веб-ссылки в кликабельные — по нажатию открывается окно для копирования.",
    ["Style chat tabs"] = "Оформлять вкладки чата",
    ["Flat dark tab background with an accent underline on the active tab."] = "Плоский темный фон вкладки с акцентной чертой под активной вкладкой.",
    ["Tab label size"] = "Размер надписей вкладок",
    ["One uniform font size for every chat tab label."] = "Единый размер шрифта для надписи каждой вкладки чата.",
    ["Chat font size (0 = Blizzard)"] = "Размер шрифта чата (0 = Blizzard)",
    ["Scrollback (lines per window)"] = "Буфер прокрутки (строк на окно)",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "Сколько строк каждое окно чата хранит для прокрутки (по умолчанию у Blizzard: 128). Больше строк — чуть больше памяти; изменение этого параметра один раз очищает показанные сейчас строки.",
    ["Item levels in chat links"] = "Уровень предмета в ссылках чата",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "Добавляет уровень предмета к ссылкам на снаряжение: [Меч] становится [Меч (45)].",
    ["Panel opacity (%)"] = "Непрозрачность панели (%)",
    ["Transparency of the dark background panel behind the chat."] = "Прозрачность темной фоновой панели за чатом.",
    ["Indent wrapped lines"] = "Отступ у перенесенных строк",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "Переносит длинные сообщения так, что продолжение идет с отступом под началом сообщения — колонка выглядит аккуратнее.",
    ["Idle fade"] = "Затухание при бездействии",
    ["Fade chat when idle"] = "Затухание чата при бездействии",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "Приглушает чат после некоторого времени без активности. Новое сообщение, наведение курсора или ввод текста возвращают его.",
    ["Idle delay (seconds)"] = "Задержка бездействия (секунды)",
    ["Faded opacity (%)"] = "Непрозрачность при затухании (%)",
    ["History"] = "История",
    ["Keep chat history"] = "Хранить историю чата",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "Запоминает недавний чат для каждого персонажа и показывает его снова после /reload.",
    ["Lines to keep"] = "Сколько строк хранить",
    ["Clear history"] = "Очистить историю",
    ["Chat history cleared."] = "История чата очищена.",
    ["--- chat history ---"] = "--- история чата ---",
    ["Copy"] = "Копировать",
    ["Copy chat"] = "Копировать чат",
    ["Link"] = "Ссылка",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A — выделить все, Ctrl+C — копировать.",
    ["Scroll to bottom"] = "Прокрутить вниз",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaaПанель, поле ввода и боковая панель меняют положение чата Blizzard. Отключение здесь скрывает их сразу; |cffffffff/reload|r в точности восстанавливает исходные позиции.|r",
    ["Dark background panel"] = "Темная фоновая панель",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "Темная панель за чатом и полем ввода, с полосой вкладок сверху — все единым целым.",
    ["Top fade"] = "Затухание сверху",
    ["Fades old lines into the panel at the top edge of the chat."] = "Растворяет старые строки в панели у верхнего края чата.",
    ["Icon sidebar"] = "Боковая панель значков",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "Узкая полоса слева от чата со значками копирования, настроек, нового окна и прокрутки вниз.",
    ["Show online friends"] = "Показывать друзей в сети",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "Показывает вверху боковой панели, сколько друзей в сети; нажмите значок, чтобы открыть список друзей.",
    ["Friends online"] = "Друзей в сети",
    ["New chat window"] = "Новое окно чата",
    ["Create new chat window"] = "Создать новое окно чата",
    ["This client can't create extra chat windows."] = "Этот клиент не может создавать дополнительные окна чата.",
    ["Use VuloUI font"] = "Использовать шрифт VuloUI",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "Применяет шрифт VuloUI к тексту чата, вкладкам и полю ввода.",
    ["Copy button (standalone)"] = "Кнопка копирования (отдельная)",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "Небольшая кнопка копирования над чатом. По умолчанию выключена, так как на боковой панели уже есть значок копирования; отключите боковую панель, чтобы использовать эту кнопку.",
    ["Bags"] = "Сумки",
    ["Inventory"] = "Инвентарь",
    ["Items"] = "Предметы",
    ["Hide"] = "Скрыть",
    ["Show"] = "Показать",
    ["Color item levels by quality"] = "Цвет уровня предмета по качеству",
    ["Tints the item level number in the item's quality color instead of plain white."] = "Окрашивает число уровня предмета в цвет качества предмета вместо простого белого.",
    ["%d free"] = "%d свободно",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaaОдно окно для всех ваших сумок. Нажмите свою клавишу сумки (по умолчанию B), чтобы открыть его. Введите текст в поле поиска, чтобы найти предметы; нажмите кнопку сортировки, чтобы навести порядок. У банкира ваш банк открывается в таком же окне.|r",
    ["Item count text size"] = "Размер текста количества предметов",
    ["Reset bag position"] = "Сбросить позицию сумок",
    ["Search & sorting"] = "Поиск и сортировка",
    ["Show search box"] = "Показывать поле поиска",
    ["A search field in the window header. Dims items that don't match."] = "Поле поиска в заголовке окна. Приглушает предметы, которые не подходят.",
    ["Show sort button"] = "Показывать кнопку сортировки",
    ["A sort button in the window header. Right-click it to reverse the order."] = "Кнопка сортировки в заголовке окна. ПКМ по ней меняет порядок на обратный.",
    ["Reverse sort order"] = "Обратный порядок сортировки",
    ["Sort bags"] = "Сортировать сумки",
    ["Bank contents"] = "Содержимое банка",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "Показывает, что лежит в вашем банке — по данным последнего визита, доступно где угодно.",
    ["As of: %s"] = "По состоянию на: %s",
    ["%d free slots"] = "Свободных ячеек: %d",
    ["No bank visit recorded on this character yet."] = "На этом персонаже банк еще ни разу не посещали.",
    ["Right-click to toggle sort order."] = "ПКМ — сменить порядок сортировки.",
    ["Can't sort bags in combat."] = "Нельзя сортировать сумки в бою.",
    ["Sort order: reversed"] = "Порядок сортировки: обратный",
    ["Sort order: normal"] = "Порядок сортировки: обычный",
    ["Sort order"] = "Порядок сортировки",
    ["How the sort button arranges items. 'Blizzard' groups by category like the default UI; the others are a flat order."] = "Как кнопка сортировки расставляет предметы. «Blizzard» группирует по категориям, как стандартный интерфейс; остальные варианты — простой единый список.",
    ["Blizzard (category)"] = "Blizzard (по категориям)",
    ["Quality"] = "Качество",
    ["Item type"] = "Тип предмета",
    ["Sort in the opposite direction."] = "Сортировать в обратном направлении.",
    ["Item level"] = "Уровень предмета",
    ["Off"] = "Выкл.",
    ["Sort categories by"] = "Сортировать категории по",
    ["Display-only ordering of the items inside each category section. Never moves anything in your bags."] = "Порядок только для отображения предметов внутри каждого раздела категории. Ничего не перемещает в ваших сумках.",
    ["Show free slots (OneBag)"] = "Показывать свободные ячейки (OneBag)",
    ["OneBag view: show the empty bag slots after the items, so you can drop things onto them directly."] = "Режим OneBag: показывать пустые ячейки сумок после предметов, чтобы можно было сразу класть в них вещи.",
    ["Fixed slot order (OneBag)"] = "Фиксированный порядок ячеек (OneBag)",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "Показывает все ячейки в естественном порядке сумок вместе с пустыми — предметы визуально остаются там, куда вы их положили, как в одной большой настоящей сумке. Нужна опция свободных ячеек выше.",
    ["Junk marker (C)"] = "Метка хлама (C)",
    ["Marks vendor trash with a purple C in the icon corner - grey items a merchant pays gold for."] = "Помечает хлам фиолетовой буквой C в углу значка — серые предметы, за которые торговец платит золото.",
    ["BoE/BoU markers"] = "Метки BoE/BoU",
    ["Tags equipment that is still tradeable (binds on equip or use, not yet soulbound) - handy for banking and the auction house."] = "Отмечает снаряжение, которое еще можно передать (становится персональным при надевании или использовании) — удобно для банка и аукциона.",
    ["Categories"] = "Категории",
    ["Group items into categories"] = "Группировать предметы по категориям",
    ["Show items in labelled sections (Quest, Consumables, Armor...). Off = one flat grid."] = "Показывать предметы в разделах с подписями (Задания, Расходуемые, Доспехи...). Выкл. — одна общая сетка.",
    ["Hide empty categories"] = "Скрывать пустые категории",
    ["Don't show a section header for a category that has no items."] = "Не показывать заголовок раздела для категории, в которой нет предметов.",
    ["Consumables"] = "Расходуемые",
    ["Weapons"] = "Оружие",
    ["Armor"] = "Доспехи",
    ["Trade Goods"] = "Хозяйственные товары",
    ["Ammo"] = "Боеприпасы",
    ["Quivers"] = "Колчаны",
    ["Keys"] = "Ключи",
    ["Junk"] = "Хлам",
    ["Miscellaneous"] = "Разное",
