    ["A separate, prominent row for crowd-control effects (Polymorph, Fear, Sap, …) on the unit, from anyone."] = "Отдельный, заметный ряд для эффектов контроля (Превращение, Устрашение, Ошеломление, ...) на существе, наложенных кем угодно.",
    ["CC icon size"] = "Размер значков контроля",
    ["Max CC"] = "Макс. эффектов контроля",
    ["Focus highlight colour"] = "Цвет подсветки фокуса",
