    ["Glows enemy buffs you can remove (Spellsteal / Purge / Dispel Magic). Only for classes that can."] = "Подсвечивает эффекты врагов, которые вы можете снять (Кража заклинаний / Очищение / Рассеивание магии). Только для классов, которые это умеют.",
    ["Dispel glow colour"] = "Цвет подсветки рассеивания",
    ["Show absorb shield"] = "Показывать щит поглощения",
    ["Absorb colour"] = "Цвет поглощения",
    ["Absorb opacity"] = "Непрозрачность поглощения",
    ["Colour by threat"] = "Цвет по угрозе",
    ["Colour the health bar by your threat on the unit — coloured for your role. Useful in dungeons."] = "Окрашивает полосу здоровья по вашей угрозе на существе — цвета подобраны под вашу роль. Полезно в подземельях.",
    ["Your role"] = "Ваша роль",
    ["DPS / Healer"] = "Урон / Лекарь",
    ["Tank"] = "Танк",
    ["Secure (tank has aggro)"] = "Безопасно (аггро на танке)",
    ["Warning (gaining / losing)"] = "Внимание (набор / потеря)",
    ["Danger (pulled / lost)"] = "Опасность (стянули / потеряли)",
    ["Show NPC title"] = "Показывать титул NPC",
    ["Item name (exactly as in-game)"] = "Название предмета (точно как в игре)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555Введите название предмета.|r",
    ["Item '%s' added at vendor '%s'."] = "Предмет «%s» добавлен для торговца «%s».",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaaНазвания предметов должны точно совпадать с игровыми (включая регистр и особые символы).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaaПредметы не настроены. Добавьте выше предметы, которые нужно автоматически покупать у этого торговца.|r",
    ["Remove"] = "Удалить",
    ["Item '%s' removed."] = "Предмет «%s» удален.",
    ["Inspect Fix"] = "Исправление осмотра",
    ["Inspect state manually reset. Try again now."] = "Состояние осмотра сброшено вручную. Попробуйте еще раз.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r Состояние осмотра сброшено.",
    ["Auto-reset on timeout"] = "Автосброс по тайм-ауту",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "Если ответ от сервера не приходит за указанное число секунд, ожидающее состояние осмотра сбрасывается автоматически — и следующая попытка осмотра снова срабатывает.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "Сколько ждать INSPECT_READY до срабатывания автосброса. 5 секунд — новое значение по умолчанию для Anniversary: достаточно быстро для скорого восстановления.",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaaКоманды: /inspectreset (принудительный сброс), /inspectstate (отладочные данные в чат)|r",
    ["Timeout (seconds)"] = "Тайм-аут (секунды)",
    ["Manual Reset"] = "Ручной сброс",
    ["Reset inspect state now"] = "Сбросить состояние осмотра сейчас",
    ["Inspect state manually reset."] = "Состояние осмотра сброшено вручную.",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "Хук NotifyInspect: %s\\nХук InspectFrame: %s",
    ["|cff66ff66active|r"] = "|cff66ff66активен|r",
    ["|cffff8800waiting|r"] = "|cffff8800ожидание|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800ожидание Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaaЧто делает исправление: отслеживает активные осмотры по метке времени, перерисовывает поздно пришедшие данные о предметах, один раз повторяет запрос при полностью пустом осмотре и вызывает ClearInspectPlayer() при закрытии и по тайм-ауту. Не дает зависшему состоянию блокировать все последующие осмотры.|r",
    ["Auto-retry empty inspects"] = "Автоповтор пустых осмотров",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "После ответа сервера ячейки предметов вскоре перерисовываются заново (данные часто приходят с задержкой). Если окно все еще совершенно пустое, осмотр запрашивается автоматически еще раз.",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaaСостояние: %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66Хук активен|r",
    ["LFG Browse Nil Fix"] = "Исправление nil в списке поиска групп",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Перехватывает ошибки Lua в поиске группы Anniversary (LFGBrowseSearchEntry_Update с устаревшими resultID). Предотвращает спам в чате и поломку списка групп.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Перехвачена ошибка списка групп Blizzard (устаревшая запись пропущена).",
    ["Chat message on first error"] = "Сообщение в чат при первой ошибке",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "Один раз за сеанс выводит в чат краткое сообщение о перехваченной ошибке списка групп.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "Это исправление оборачивает функцию Blizzard |cffffffffLFGBrowseSearchEntry_Update|r в защищенный вызов (xpcall). Когда запись падает из-за устаревшего resultID («searchResultInfo nil»), ошибка подавляется — следующее обновление Blizzard автоматически очищает запись списка.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "ожидание Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "Исправление nil в новостях гильдии",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "Перехватывает ошибки Lua в записях новостей гильдии (обычно «formatString» или «GuildUtil») и заменяет сломанные записи запасным текстом, вместо того чтобы ломать всю панель.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080Неверная запись новостей гильдии|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Перехвачена ошибка новостей гильдии Blizzard (применен запасной текст).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "Один раз за сеанс выводит в чат краткое сообщение о перехваченной ошибке новостей гильдии.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "Это исправление оборачивает функцию Blizzard |cffffffffGuildNewsButton_SetNews|r в защищенный вызов (xpcall). Когда запись выдает известную ошибку («formatString» или «GuildUtil»), она заменяется запасным текстом «Неверная запись новостей гильдии» — панель остается рабочей.",
    ["waiting for Blizzard_Communities"] = "ожидание Blizzard_Communities",
    ["Auction Price Fix"] = "Исправление цен на аукционе",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "Устраняет ошибку nil в немецком интерфейсе аукциона (PriceDropdown не определен).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "Это исправление устраняет известную ошибку немецкой локализации WoW: интерфейс аукциона обращается к элементу «PriceDropdown», который так и не был определен, из-за чего при открытии аукциона возникают ошибки Lua.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaaТекущая локализация: %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaaИсправление применяется только на немецких клиентах (deDE). На других языках модуль неактивен.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66применено|r",
    ["skipped (deDE-only)"] = "пропущено (только для deDE)",
    ["not applied"] = "не применено",
    ["Combat Text"] = "Боевой текст",
    ["Expressway (Default)"] = "Expressway (по умолчанию)",
    ["Friz Quadrata (Blizzard)"] = "Friz Quadrata (Blizzard)",
    ["Arial Narrow"] = "Arial Narrow",
    ["Morpheus"] = "Morpheus",
    ["Skurri"] = "Skurri",
    ["LOW DURABILITY"] = "НИЗКАЯ ПРОЧНОСТЬ",
