    -- Talent overrides
    ["active"] = "активно",
    ["Talent Overrides"] = "Настройки по набору талантов",
    ["Talent group %d"] = "Набор талантов %d",
    ["%d settings overridden"] = "Переопределено настроек: %d",
    ["Forget all overrides for this talent group"] = "Забыть все настройки этого набора",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Настройки применяются сами при смене набора талантов. В этом клиенте нет специализаций, поэтому ось — двойная система талантов.",
    -- Override groups
    ["Talent group %d (%s)"] = "Набор талантов %d (%s)",
    ["Name for the new group"] = "Название новой группы",
    ["Editing as"] = "Редактируется как",
    ["Yourself"] = "Вы сами",
    ["Manage groups..."] = "Управление группами...",
    ["Owns the current talent group"] = "Действует для текущего набора талантов",
    ["Delete this group"] = "Удалить эту группу",
    ["No groups yet."] = "Групп пока нет.",
    -- Anchor points
    ["Centre"] = "По центру",
    ["Thin outline"] = "Тонкий контур",
    ["Bar Setups"] = "Наборы панелей",
    -- Patch notes 1.40.0
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s пока не имеет обработчика — это ошибка, пожалуйста, сообщите о ней.",
    ["%s belongs to %s, which is switched off."] = "%s относится к %s, а этот модуль выключен.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffКоманды|r — всего %d. Серые относятся к выключенному модулю.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s также занята другим аддоном (%s) — сработает только одна из двух.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555Модуль наборов панелей не загружен.|r",
    ["Bar setup '%s' deleted."] = "Набор панелей '%s' удалён.",
    ["Not in combat — bars can't be changed while fighting."] = "Вне боя — панели нельзя менять во время боя.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Набор панелей '%s' загружен: %d ячеек заполнено, %d очищено, |cffff8800%d пропущено|r (неизвестное заклинание / отсутствует предмет или макрос).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Набор панелей '%s' загружен: %d ячеек заполнено, %d очищено.",
    ["on"] = "вкл",
    ["Overridden settings: %s"] = "Переопределённые настройки: %s",
    ["Situation"] = "Ситуация",
    ["Everywhere"] = "Везде",
    ["Raid instance"] = "Рейдовое подземелье",
    ["5-player instance"] = "Подземелье на 5 игроков",
    ["Battleground"] = "Поле боя",
    ["In a group"] = "В группе",
    ["Alone"] = "В одиночку",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Действует только в этой ситуации. Вместе с набором талантов должны выполняться оба условия — и такая группа тогда важнее той, что указывает только набор талантов.",
    ["Icon"] = "Значок",
    ["No icon"] = "Без значка",
    ["Shown in front of the group name in the menu and on the header button."] = "Показывается перед названием группы в меню и на кнопке заголовка.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Выключение убирает только это переопределение. Настройка снова следует профилю.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "Наборы панелей теперь хранятся один раз на всю учётную запись: %d сохранено, %d дубликатов объединено.",
    ["Trinket window settings now live in this addon's own database."] = "Настройки окна аксессуаров теперь хранятся в собственной базе данных этого аддона.",
    ["Auto queue: top slot"] = "Автоочередь: верхняя ячейка",
    ["Auto queue: bottom slot"] = "Автоочередь: нижняя ячейка",
    ["Auto queue for this slot"] = "Автоочередь для этой ячейки",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "Тот же переключатель, что и alt-щелчок по ячейке. Когда включено, очередь меняет этот аксессуар в бою по порядку ниже.",
    ["Order"] = "Порядок",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "Очередь идёт по этому списку сверху вниз. Выбери запись, чтобы переместить её или изменить её настройки.",
    ["- empty -"] = "- пусто -",
    ["— queue stops here —"] = "— дальше замены нет —",
    ["Add from bags"] = "Добавить из сумок",
    ["Adds a trinket you are carrying to the end of this list."] = "Добавляет в конец этого списка аксессуар, который у тебя с собой.",
    ["Swap delay"] = "Задержка замены",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Сколько секунд этот аксессуар остаётся надетым, прежде чем очередь снова его сменит. 0 = без ожидания.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Этот аксессуар надевается раньше тех, что выше, как только будет готов.",
    ["Pause while equipped"] = "Пауза, пока надет",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Пока этот аксессуар надет, очередь стоит — для аксессуара, эффект которого не стоит обрывать.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaПодсказка: щелчок левой кнопкой по ячейке использует аксессуар, правой — открывает список. Alt-щелчок включает автоочередь для этой ячейки.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d снимок(ов) имели одинаковое имя при разном содержимом и сохранены под новым именем.",
    ["GAP"] = "ОТСТУП",
    ["Distance from that edge, in pixels. 0 is flush."] = "Расстояние до этого края, в пикселях. 0 — вплотную.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Пристыковывает это окно к выбранной стороне целевого окна и центрирует его там. 'По центру' не двигает окно — оно только следует за целью. Отступ выдерживается от края до края, поэтому переживает изменение размера любого из окон.",
    ["waiting for a swing"] = "ожидание удара",
    ["  -  lag %.0fms"] = "  -  задержка %.0fмс",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Нет печати, с которой можно менять. Только Печать повеления и Печать праведности всё ещё срабатывают на ударе после замены, поэтому нужна одна из двух.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Изучена всего одна печать. Для смены нужна вторая.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800С удерживаемой печати менять нельзя. Только Печать повеления и Печать праведности всё ещё срабатывают на ударе, который их заменяет.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Здесь подходят только Печать повеления и Печать праведности: лишь их действие ещё срабатывает на ударе, который их заменяет.",
    -- Namensplaketten-Vorlage
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Основные позиции",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaПо одному на место. То, что ты кладёшь на место, забирается у того, где оно было.|r",
    ["Debuffs"] = "Отрицательные эффекты",
    ["Buffs"] = "Положительные эффекты",
    ["Crowd control"] = "Контроль",
    ["Your own debuffs"] = "Твои отрицательные эффекты",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow in the aura's own school colour"] = "Светиться цветом школы эффекта",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Магия синим, проклятие фиолетовым, болезнь оранжевым, яд зелёным — вместо одного цвета на всё.",
    -- Absorptionsstil
    ["Absorb style"] = "Вид поглощения",
    ["Flat colour"] = "Сплошной цвет",
    -- Zauberziel
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "Текущая цель того, кто читает заклинание, рядом с полосой заклинания. Твоё имя выделяется цветом.",
    ["Cast target size"] = "Размер имени цели заклинания",
    -- Zielpfeile
    ["Two arrows pointing in at the target's bar, one on each side."] = "Две стрелки, указывающие на полосу цели с обеих сторон.",
    ["Arrow size"] = "Размер стрелок",
    ["Arrow distance"] = "Отступ стрелок",
    ["Arrow colour"] = "Цвет стрелок",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "Метка на индикаторе фокуса",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "Короткий текст на индикаторе твоей цели фокуса. Кольцо говорит, что она особая; метка говорит, какая именно.",
    ["Mark text"] = "Текст метки",
    ["Mark position"] = "Положение метки",
    ["Mark size"] = "Размер метки",
    -- Kleine Plaketten
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaДержите Печать повеления и накладывайте вторую печать в последнюю долю секунды перед автоатакой: этот удар получит обе. До 64-го уровня вторая печать -- Печать праведности; дальше её сменяют Печать крови и Печать мученика.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaaПолоса отсчитывает время до удара по зонам: |cff5c8aebсиняя|r свободна для заполнителя, |cffd93636красная|r -- отрезок, на котором заклинание к открытию окна ещё будет на общем восстановлении, а |cff33ff66зелёная|r -- окно смены. Последняя метка в зелёной зоне -- поздняя смена, перед которой ещё помещается правосудие.|r",
    ["Late twist window (seconds)"] = "Окно поздней смены (секунды)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "Хвост окна смены, отмеченный отдельно. Такая поздняя смена оставляет место для правосудия перед печатью. Сделайте его равным окну смены, чтобы метка исчезла.",
    ["Second cue for the late window"] = "Второй сигнал для позднего окна",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "Другой звук на метке поздней смены, чтобы различать два конца окна, не глядя на полосу.",
    ["Shade the zones"] = "Подкрашивать зоны",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "Окрашивает оставшуюся часть удара в цвет зоны, в которую она попадает.",
    ["Show the marks"] = "Показывать метки",
    ["The three boundary lines: danger zone, twist window, late twist."] = "Три пограничные линии: опасная зона, окно смены, поздняя смена.",
    ["Show seal indicators"] = "Показывать печати",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "Печати, которые сейчас на вас, и их остаток, справа от полосы. Во время смены видны обе -- это наложение и есть выигрыш.",
    ["Seal icon size"] = "Размер значков печатей",
    ["Head start for the prompt (ms)"] = "Опережение подсказки (мс)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "Показывает подсказку смены и проигрывает её звук на столько раньше, чем окно откроется на самом деле, чтобы успеть увидеть и нажать. Цвета на полосе остаются точными.",
    ["auto"] = "Авто",
    ["Twist only"] = "Только смена",
    ["Rotation"] = "Ротация",
    ["Show the rotation helper"] = "Показывать помощник ротации",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "Ряд шагов над полосой: какая последовательность подходит вашему оружию и скорости, и где в ней вы сейчас. Он двигается от того, что вы действительно накладываете, и от ваших ударов.",
    ["Sequence"] = "Последовательность",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "Автоматически следует за скоростью атаки и скоростью заклинаний — именно они решают, сколько смен помещается между двумя ударами. Выберите вручную, чтобы отработать одну последовательность.",
    ["Rotation icon size"] = "Размер значков",
    ["Sound when the twist lands"] = "Звук, когда смена удалась",
    ["Hit sound"] = "Звук попадания",
    ["Listen"] = "Прослушать",
    ["Chime"] = "Колокольчик",
    ["Raid warning"] = "Предупреждение рейда",
    ["Ready check"] = "Проверка готовности",
    ["Click"] = "Щелчок",
    -- Patch notes 1.41.0
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "Затемнять врагов вне боя",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "Приглушает врагов, которые ни с кем не сражаются, чтобы сражающиеся выделялись. Твоя цель — никогда.",
    ["Darken to (%)"] = "Затемнять до (%)",
    ["Highlight strength"] = "Сила подсветки",
    ["Hitbox width (%)"] = "Ширина области нажатия (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "Область нажатия индикатора. 100 оставляет размер игры нетронутым. Хранится в профиле.",
    ["Hitbox height (%)"] = "Высота области нажатия (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "Винтовочный выстрел",
    -- Aktionszeile
    ["Action text size"] = "Размер строки действия",
    ["The line that names what to press. 0 follows the general text size."] = "Строка, которая говорит, что нажать. 0 — как общий размер текста.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "Размер таймера печати",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "Отсчёт на значках печатей. 0 — по размеру значка.",
    -- Warnzeile
    ["Warning text size"] = "Размер текста предупреждений",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "Красные и жёлтые предупреждения на полосе. 0 — как размер строки действия.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "Ограничивает этот значок числом стаков или последними секундами перед окончанием.",
    ["Only from stacks"] = "Только от стаков",
    ["0 = any number of stacks."] = "0 = любое число стаков.",
    ["Only in the last seconds"] = "Только в последние секунды",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = в любое время. Иначе значок появляется лишь так близко к окончанию.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "Наблюдать за этой целью",
    ["Whose auras this group reads. The default is what the group type has always used."] = "Чьи эффекты читает эта группа. По умолчанию — то, что тип группы использовал всегда.",
    ["You"] = "Ты",
    ["Target"] = "Цель",
    ["Focus"] = "Фокус",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "Только то, что наложил я сам",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "Выключено — эффект считается независимо от того, кто его наложил: для рейдового ослабления, которое может наложить любой.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "Фиксированный сохраняет порядок добавления. Два других перестраивают на лету по оставшемуся времени.",
    ["As added"] = "Как добавлено",
    ["Least time left first"] = "Сначала с наименьшим остатком",
    ["Most time left first"] = "Сначала с наибольшим остатком",
    ["Practice"] = "Тренировка",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaaЧасы удара, которые идут сами по себе: без цели и без затрат. Нажимай назначенные клавиши по ним, и каждый удар получает оценку: twist удался, было слишком рано или попытки не было. Модель печатей настоящая -- заменённая печать продолжает срабатывать ещё 0.4 секунды -- поэтому тайминг, который ты выучишь здесь, работает и в бою.|r",
    ["Start / stop practice"] = "Начать / остановить тренировку",
    ["Stop practice"] = "Остановить тренировку",
    ["Simulated weapon speed"] = "Смоделированная скорость оружия",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "При значении 0 используется надетое оружие. Любое другое значение тренирует скорость, которой у тебя ещё нет: так ты заранее узнаёшь, что оружию, на которое ты копишь, нужна другая последовательность.",
    ["Spell queue window (ms)"] = "Окно очереди заклинаний (мс)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "Клавиша, нажатая за это время до конца глобального восстановления, запоминается и срабатывает ровно в момент его окончания, точно так же, как это делает игра. Тренировка без этого учит ритму, которого игра никогда не требует.",
    ["Result text size"] = "Размер текста результата",
    ["Result text duration (seconds)"] = "Длительность текста результата (сек.)",
    ["Landed colour"] = "Цвет успеха",
    ["Missed colour"] = "Цвет промаха",
    ["Show the fight timeline"] = "Показывать ленту боя",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "Каждый удар и каждое применение на одной полосе с линейкой. Линейка здесь и есть смысл: без неё видно, что два удара прошли близко, но не насколько близко, а именно это число и есть вся тренировка.",
    ["Timeline width"] = "Ширина ленты",
    ["Timeline pixels per second"] = "Пикселей в секунду на ленте",
    ["TWIST"] = "TWIST",
    ["MISS"] = "МИМО",
    ["TOO EARLY"] = "РАНО",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "скор. %.2fс  -  ГКД %.2fс  -  %d из %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffffТРЕНИРОВКА|r",
    ["|cffffffffRESULT|r"] = "|cffffffffРЕЗУЛЬТАТ|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffffЛЕНТА|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33Тренировка twist|r",
    ["Practice needs two seals: pick them under Seals first."] = "Для тренировки нужны две печати: сначала выбери их в разделе «Печати».",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "Режим тренировки включён. Нажимай назначенные клавиши, удар идёт сам.",
    ["Practice mode off. %d of %d swings carried the twist."] = "Режим тренировки выключен. Twist прошёл в %d ударах из %d.",
    ["Bloodlust"] = "Жажда крови",
    ["Haste potion"] = "Зелье ускорения",
    ["Abacus"] = "Счёты",
    ["Time warp"] = "Искажение времени",
    ["Crusader Strike"] = "Удар крестоносца",
    ["Judgement"] = "Правосудие",
    ["Cast the held seal"] = "Применить удерживаемую печать",
    ["Cast the twist seal"] = "Применить печать twist",
    ["Filler"] = "Заполнитель",
    ["Start / stop attack"] = "Начать / остановить атаку",
    ["wait"] = "ждать",
    ["Next action"] = "Следующее действие",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffffСЛЕД. ДЕЙСТВИЕ|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Перемещение следующего действия включено. |cff9b6cffПеретащи фиолетовую рамку|r или используй |cff9b6cffстрелки|r (SHIFT = 5 пикс.). Нажми «Разблокировать / Тест» ещё раз, чтобы закончить.",
    ["Next action mover disabled."] = "Перемещение следующего действия выключено.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaaЗначок того единственного, что нужно нажать, в любом удобном месте. Он отвечает на тот же вопрос, что и строка под полосой -- три переключателя ниже питают и то, и другое, поэтому слово и картинка никогда не разойдутся.|r",
    ["Show the next action guide"] = "Показывать подсказку следующего действия",
    ["When to show it"] = "Когда показывать",
    ["Show a hold instead of nothing"] = "Показывать паузу вместо пустоты",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "Пока правильный ход -- намеренно ничего не нажимать, потому что twist уже на подходе и любое другое действие его сорвёт -- подсказка продолжает показывать печать, обесцвеченную и обведённую. Пустая рамка говорит то же самое, но гораздо менее внятно.",
    ["Suggest Judgement"] = "Предлагать Правосудие",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "Правосудие расходует печать, поэтому оно предлагается только тогда, когда после него остаётся время снова наложить печать. По умолчанию выключено: правосудие не вовремя обходится дороже, чем полное отсутствие подсказки.",
    ["Suggest a filler"] = "Предлагать заполнитель",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "Освящение или Изгнание зла там, где цель к нему уязвима, на том отрезке удара, который для этого свободен. Пригодность Изгнания зла проверяется у самой игры: можно ли навести заклинание на твою цель, и это верно на любом языке.",
    ["Consecration mana floor (%)"] = "Нижний порог маны для Освящения (%)",
    ["Below this share of your mana the filler is not worth it."] = "Ниже этой доли твоей маны заполнитель уже не окупается.",
    ["Exorcism mana floor (%)"] = "Нижний порог маны для Изгнания зла (%)",
    ["Longest Crusader Strike delay (ms)"] = "Наибольшая задержка Удара крестоносца (мс)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "Как только дальнейшее откладывание удара дольше этого срока сделает его потерянным, он перестаёт быть подсказкой и становится единственным ответом. Отсчёт идёт от самого раннего момента, когда его действительно можно применить, а не от текущей секунды.",
    ["Twist!"] = "Twist!",
    ["|cffffffffTWIST TEXT|r"] = "|cffffffffТЕКСТ TWIST|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Перемещение текста twist включено. |cff9b6cffПеретащи фиолетовую рамку|r или используй |cff9b6cffстрелки|r (SHIFT = 5 пикс.). Нажми «Разблокировать / Тест» ещё раз, чтобы закончить.",
    ["Twist text mover disabled."] = "Перемещение текста twist выключено.",
    ["Twist landed"] = "Twist удался",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaaВсе три сигнала ниже ждут ДОКАЗАТЕЛЬСТВА, а не предсказания. Удар должен пройти при двух активных печатях, и следом в боевом журнале должен появиться урон от удерживаемой печати. Без этой второй строки не срабатывает ничего -- подтверждение, которое право в большинстве случаев, не годится для тренировки.|r",
    ["Sound channel"] = "Звуковой канал",
    ["Master"] = "Общий",
    ["Sound effects"] = "Звуковые эффекты",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "Общий канал не зависит от ползунка звуковых эффектов, а подтверждению именно это и нужно: оно рассказывает о бое, а не является его частью.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "Щелчки снайпера и винтовки входят в комплект, остальные звуки берутся из самой игры. Ниже перечислены звуки, которые другие дополнения зарегистрировали как общие ресурсы.",
    ["Sniper"] = "Снайпер",
    ["Level up"] = "Новый уровень",
    ["Quest complete"] = "Задание выполнено",
    ["Bonus objective"] = "Дополнительная задача",
    ["Map ping"] = "Метка на карте",
    ["Glow on the bar when the twist lands"] = "Свечение полосы, когда twist удался",
    ["Glow style"] = "Стиль свечения",
    ["Pixel border"] = "Пиксельная рамка",
    ["Autocast ring"] = "Кольцо автоприменения",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "Пиксельная рамка повторяет контур самой полосы при любой ширине. Кольцо автоприменения крепит игровое кольцо к четырём углам, поэтому оно остаётся кольцом, как бы широка ни была полоса.",
    ["Glow colour"] = "Цвет свечения",
    ["Glow duration (seconds)"] = "Длительность свечения (сек.)",
    ["Text when the twist lands"] = "Текст, когда twist удался",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "Строка где угодно на экране, со своим собственным положением. Пригодится, когда полоса стоит с краю поля зрения, а подтверждение должно быть в его середине.",
    ["Text font"] = "Шрифт текста",
    ["Text outline"] = "Контур текста",
    ["Text colour"] = "Цвет текста",
    ["Text duration (seconds)"] = "Длительность текста (сек.)",
    ["|cffffffffSEALS|r"] = "|cffffffffПЕЧАТИ|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Перемещение индикатора печатей включено. |cff9b6cffПеретащи фиолетовую рамку|r или используй |cff9b6cffстрелки|r (SHIFT = 5 пикс.). Нажми «Разблокировать / Тест» ещё раз, чтобы закончить.",
    ["Seal indicator mover disabled."] = "Перемещение индикатора печатей выключено.",
    ["Match the bar height"] = "Подгонять под высоту полосы",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "Размер значков берётся от полосы, а не из собственной настройки, поэтому пара продолжает совпадать с ней при изменении высоты полосы.",
    ["Ignored while the icons match the bar height."] = "Не учитывается, пока значки подгоняются под высоту полосы.",
    ["Seal icon spacing"] = "Расстояние между значками печатей",
    ["Centre the icons"] = "Выравнивать значки по центру",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "Середина пары остаётся на месте, когда вторая печать появляется или спадает. При выравнивании по левому краю на месте остаётся первый значок, а именно это и нужно паре, прикреплённой к полосе -- этот край и есть полоса.",
    ["Show the cooldown sweep"] = "Показывать развёртку восстановления",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "Собственная развёртка игры поверх значка. Она говорит то же, что и число под ней, но её не нужно читать.",
    ["Seal timer colour"] = "Цвет таймера печати",
    ["Detach from the bar"] = "Открепить от полосы",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "Даёт паре собственное положение в любом месте экрана. Во всём остальном она остаётся привязанной к полосе: когда скрыта полоса, скрыта и пара.",
    ["Twist lost"] = "Twist потерян",
    ["Swing ready -- restart your attack"] = "Удар готов -- начни атаку заново",
    ["(none available)"] = "(нет доступных)",
    ["Solid"] = "Однотонная",
    ["Attack speed"] = "Скорость атаки",
    ["Swing timer"] = "Таймер удара",
    ["Latency (ms)"] = "Задержка (мс)",
    ["Global cooldown left"] = "Остаток ГКД",
    ["Nothing"] = "Ничего",
    ["Left readout"] = "Левое значение",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "Что показывает левый край полосы. Скорость атаки окрашивается в предупреждающий цвет, если на удар приходится меньше двух глобальных восстановлений -- ниже этого порога twist и возврат печати уже не помещаются вместе, поэтому перед twist дождись окончания восстановления.",
    ["Right readout"] = "Правое значение",
    ["Readout text size"] = "Размер текста значений",
    ["The two numbers inside the bar. 0 follows the general text size."] = "Два числа внутри полосы. При 0 берётся общий размер текста.",
    ["Global cooldown bar texture"] = "Текстура полосы глобального восстановления",
    ["Border"] = "Рамка",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "Однотонная рисует четыре ровных края цветом, выбранным ниже. Текстура берёт файл края из общих ресурсов, и именно так выглядит рамка из другого набора интерфейса.",
    ["Only used while the border is set to texture."] = "Используется, только когда для рамки выбрана текстура.",
    ["Border width"] = "Ширина рамки",
    ["Marker texture"] = "Текстура метки",
    ["Marker width"] = "Ширина метки",
    ["Font colour"] = "Цвет шрифта",
    ["Frame strata"] = "Слой интерфейса",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "В каком слое интерфейса находится помощник. Подними его, чтобы полоса оказалась поверх другого дополнения, которое рисует в том же месте.",
    ["Draw level"] = "Уровень отрисовки",
    ["The order inside the chosen layer. Higher draws on top."] = "Порядок внутри выбранного слоя. Чем выше значение, тем ближе к переднему плану.",
    ["Colour the bar by"] = "Окрашивать полосу по",
    ["The zone the swing is in"] = "Отрезку удара",
    ["The seal you are carrying"] = "Активной печати",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "Отрезки окрашивают заливку по той части удара, в которой ты находишься, и вокруг этого построен весь помощник. Печать окрашивает её по тому, что ты сейчас несёшь, и это читается быстрее, когда тайминг уже в пальцах. В любом случае особые цвета ниже важнее этого выбора.",
    ["Seal of Command"] = "Печать повеления",
    ["Seal of Righteousness"] = "Печать праведности",
    ["Seal of Blood / the Martyr"] = "Печать крови / мученика",
    ["Seal of Vengeance"] = "Печать возмездия",
    ["Seal of the Crusader"] = "Печать крестоносца",
    ["Seal of Justice"] = "Печать справедливости",
    ["Seal of Light"] = "Печать света",
    ["Seal of Wisdom"] = "Печать мудрости",
    ["No twist possible"] = "Twist невозможен",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "Заливка, пока twist этого удара уже упущен, и хвост удара, до которого применение уже не дотягивается.",
    ["Warning"] = "Предупреждение",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "Предупреждения на полосе и скорость атаки, когда оружие слишком быстрое для twist.",
    ["Twisting"] = "Twist активен",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "Заливка, пока активны обе печати: twist сделан, и этот удар его несёт.",
    ["Default"] = "По умолчанию",
    ["The fill with no seal up and between swings."] = "Заливка без активной печати и между ударами.",
    ["Global cooldown"] = "Глобальное восстановление",
    ["Deadzone"] = "Мёртвая зона",
    ["Twist window padding"] = "Запас окна twist",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "Сдвигает окно twist раньше, чтобы применение всё же успело дойти до сервера внутри него. Динамический запас следует за твоей вычисленной задержкой, фиксированный задаётся числом вручную.",
    ["Fixed twist padding (ms)"] = "Фиксированный запас twist (мс)",
    ["Only used while the padding mode is set to fixed."] = "Используется, только когда выбран фиксированный режим запаса.",
    ["Dynamic (follows latency)"] = "Динамический (по задержке)",
    ["Fixed"] = "Фиксированный",
    ["Latency"] = "Задержка",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaaЗадержка туда и обратно, о которой сообщает игра, не равна той задержке, которую должен обогнать twist: клиент добавляет и свою долю, поэтому всё ниже считается от значения (задержка мира x множитель) + смещение. Подними множитель, если продолжаешь терять twist, которые выглядели вовремя.|r",
    ["Latency multiplier"] = "Множитель задержки",
    ["Latency offset (ms)"] = "Смещение задержки (мс)",
    ["Shade the deadzone"] = "Затенять мёртвую зону",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "Хвост удара, который применение уже не пересечёт, затенён в конце полосы. Его размер зависит от сырой задержки мира, а не от вычисленного значения, потому что здесь речь о самом канале связи, а не о предсказании. Этот переключатель только рисует её -- сам расчёт времени учитывает её всегда, поэтому поставь масштаб на 0, если компенсация не нужна совсем.",
    ["Deadzone scale"] = "Масштаб мёртвой зоны",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "Умножает твою задержку мира. Подними его, если twist не выходит сразу за затенённым отрезком, и опусти, если он всё ещё выходит внутри него. 0 полностью отключает компенсацию.",
    ["Deadzone texture"] = "Текстура мёртвой зоны",
    ["Deadzone transparency"] = "Прозрачность мёртвой зоны",
    ["Global cooldown padding"] = "Запас глобального восстановления",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "Сдвигает границу глобального восстановления раньше на часть твоей задержки, чтобы применение, начатое прямо на отметке, всё же уложилось в восстановление.",
    ["Fixed global cooldown padding (ms)"] = "Фиксированный запас глобального восстановления (мс)",
    ["Show the judgement mark"] = "Показывать метку Правосудия",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "Четвёртая линия там, где Правосудие выходит из восстановления в течение этого удара, чтобы поставить его перед twist, а не поверх него. Рисуется, только пока активна печать.",
    ["Show the global cooldown bar"] = "Показывать полосу глобального восстановления",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "Полоска вдоль нижнего края полосы, доходящая до момента, когда глобальное восстановление освободится: так видно, какая часть этого удара уже занята.",
    ["Global cooldown bar height"] = "Высота полосы глобального восстановления",
    ["When to show the bar"] = "Когда показывать полосу",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "«Всегда» держит её на экране, и так проще отрабатывать тайминг на манекене. «При активной печати» показывает её всё время, пока ты несёшь печать, в бою и вне боя.",
    ["Seal active"] = "При активной печати",
    ["In combat or seal active"] = "В бою или при активной печати",
    ["Only with Two-Handed Weapon Specialization"] = "Только со специализацией по двуручному оружию",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "Скрывает помощник, пока в этом таланте нет очка. Twist работает и без него, но окупается вся эта привычка именно из-за медленного удара, вокруг которого она построена.",
    ["Neck"] = "Шея",
    ["Shoulder"] = "Плечи",
    ["Waist"] = "Пояс",
    ["Legs"] = "Ноги",
    ["Wrist"] = "Запястья",
    ["Hands"] = "Кисти рук",
    ["Finger 2"] = "Палец 2",
    ["Trinket 2"] = "Аксессуар 2",
    ["Off Hand"] = "Левая рука",
    ["Ranged"] = "Дальнобойное оружие",
    -- Patch notes 1.42.0
    -- Patch notes 1.42.0
    -- Patch notes 1.42.0
    -- Patch notes 1.42.0
    -- Patch notes 1.43.0
    ["Icon Strip"] = "Полоса значков",
    ["Distance from frame"] = "Расстояние от рамки",
    ["Spacing between icons"] = "Расстояние между значками",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "Расовая способность, аксессуар PvP и ряд DR располагаются у одного края рамки и выставляются друг за другом в этом порядке наружу.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "Расположение задаётся один раз для всех трёх отслеживаний в разделе «Макет», «Полоса значков».",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "Отступ под каждой рамкой. Полоса питомца противника выступает снизу за пределы рамки, поэтому при малом отступе она заходит на следующую.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "Арена: расовая способность, аксессуар PvP и ряд DR теперь используют общую полосу значков; выбранная вами сторона сохранена.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555Не удалось разместить рамки арены:|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555Ошибка полосы значков арены:|r %s",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "На этой панели пока ничего нет. Добавьте заклинание или аксессуар ниже либо перетащите его на панель.",
    ["+  New cooldown bar"] = "+  Новая панель восстановления",
    ["+  New buff / proc bar"] = "+  Новая панель усилений и срабатываний",
    ["+  New target debuff bar"] = "+  Новая панель ослаблений на цели",
    ["+  New missing-buff reminder"] = "+  Новое напоминание об отсутствующих усилениях",
    ["Buffs & Procs"] = "Усиления и срабатывания",
    ["Target debuffs"] = "Ослабления на цели",
    ["Missing buffs"] = "Отсутствующие усиления",
    ["New name for this bar"] = "Новое название для этой панели",
    ["Delete this bar and everything on it?"] = "Удалить эту панель и всё на ней?",
    ["That is the last bar — there has to be one."] = "Это последняя панель — одна должна остаться.",
    ["Drag to reorder bars"] = "Перетащите, чтобы изменить порядок панелей",
    ["Rename this bar"] = "Переименовать эту панель",
    ["Delete this bar"] = "Удалить эту панель",
    ["Duplicate bar"] = "Дублировать панель",
    ["Copies the selected bar with all entries and layout settings."] = "Копирует выбранную панель со всеми записями и настройками расположения.",
    ["Bar layout"] = "Расположение панели",
    ["Icon appearance"] = "Вид значков",
    ["Icon display"] = "Отображение значков",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "Перемещаемые панели восстановления, сгруппированные как вам удобно — срабатывания, защитные, атакующие, каждая со своим видом и положением.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "Какие ID показывать в подсказках? Некоторые типы отсутствуют в этой версии игры и игнорируются (например, TraitNodeID, SourceID).",
    ["CDM Bars"] = "Панели CDM",
    ["Bug Fixes"] = "Исправления ошибок",
    ["Bar Glows"] = "Свечение панелей",
    ["Click to edit this icon's glow."] = "Щёлкните, чтобы изменить свечение этого значка.",
    ["Click an icon to edit its glow."] = "Щёлкните значок, чтобы изменить его свечение.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "На этой панели пока ничего нет. Сначала добавьте заклинание или аксессуар на вкладке «Панели CDM».",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaaКаждый значок может светиться, пока ваше усиление активно — или отсутствует. Щёлкните значок в предпросмотре выше и добавьте одного или нескольких наблюдателей; первый, чьё условие выполнено, окрашивает значок.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888Значок ещё не выбран.|r",
    ["Glows: %s"] = "Свечения: %s",
    ["Glow when"] = "Светиться, когда",
    ["Buff is active"] = "Усиление активно",
    ["Buff is missing"] = "Усиление отсутствует",
    ["Action button glow"] = "Свечение кнопки действия",
    ["Pulsing fill"] = "Пульсирующая заливка",
    ["Gold (default)"] = "Золото (по умолчанию)",
    ["Pick color..."] = "Выбрать цвет...",
    ["Remove this glow"] = "Убрать это свечение",
    ["Watches: %s"] = "Наблюдает за: %s",
    ["Add watcher (buff name / ID)"] = "Добавить наблюдателя (название заклинания / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaaНаблюдателя пока нет. Большинство заклинаний при применении накладывают на вас одноимённое усиление — один щелчок ниже заставит этот значок светиться, пока это усиление на вас. Либо впишите в поле любое другое усиление.|r",
    ["Glow while '%s' is on me"] = "Светиться, пока на мне «%s»",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "Полоса значков – Расовая способность, аксессуар и ряд DR делят один край рамки в фиксированном порядке, с одним набором настроек — они больше не могут накладываться друг на друга",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "Расположение рамок арены — порядок, расстояние, направление роста — никогда не применялось: его перехватчики устанавливались до загрузки интерфейса арены. Теперь рамки сами сообщают о своих перемещениях, и расположение следует за ними; в бою они защищены, и сдвиг посреди раунда исправляется по его окончании.",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "Расстояние между рамками по умолчанию оставляет место полосе питомца противника, а рамка перетаскивания в режиме редактирования покрывает весь столбец, а не фиксированную область.",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "Свечение панелей – Любой значок может светиться, пока ваше усиление активно или отсутствует: три стиля, золото, цвет класса или свой цвет, и один щелчок ставит под наблюдение собственное усиление заклинания",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "Страница построена вокруг предпросмотра, который стоит на месте при прокрутке: сверху выбор панели с переименованием, удалением и перетаскиванием для сортировки, под ним каждый значок панели в настоящем размере и форме с настоящей разверткой восстановления. Перетаскивание сортирует, правый щелчок удаляет.",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "Страница разделена на вкладки, и панель ресурсов переехала внутрь как одна из них. Добавленные заклинания принадлежат классу, который их добавил, и больше не появляются у ваших других персонажей.",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "Третья ячейка дополнительных предметов больше не растягивается на всю страницу с полем, отброшенным к краю.",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "Интерфейс больше нигде не сравнивает себя с другой версией игры; проверка навсегда не пускает такие формулировки.",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "Модули с несколькими страницами показывают их рядом вкладок вдоль верхнего края; когда вкладки не помещаются, две стрелки листают ряд вместо переноса на вторую строку.",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "Боковая панель стала короче: рамки игрока и цели, шрифтовые полосы, полоса чтения и пульс восстановления теперь одна строка, а новая строка «Общее» под «Напоминаниями» собирает прежние строки «Мелочи», «Персонаж» и «Исправления ошибок» — исправления одной-единственной вкладкой.",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "Ввод в поле добавления и щелчок по кнопке рядом молча ничего не делали; набранный текст засчитывался только после Enter. Теперь кнопки забирают текст поля с собой.",
    ["Developer"] = "Разработчик",
    ["Suppress Lua Errors"] = "Скрывать ошибки Lua",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "Скрывает игровое окно ошибок Lua (CVar scriptErrors). Ошибки по-прежнему происходят, и собирающие их аддоны их видят - они просто больше вас не прерывают.",
    ["Show IDs in Tooltips"] = "Показывать ID в подсказках",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "Показывает ID заклинаний, предметов, НИП и другие в подсказках. Какие типы ID отображаются, настраивается на странице ID в подсказках в группе Разное.",
    ["Reset All Settings"] = "Сбросить все настройки",
    ["Optimize My FPS and Graphics"] = "Оптимизировать мои FPS и графику",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "Применяет проверенный набор настроек графики, заметно повышающий FPS без потери вида игры - тени, жидкости, фоновое затенение и дальность обзора снижаются, текстуры и эффекты заклинаний остаются чёткими. Текущие значения сначала сохраняются, кнопка восстановления вернёт их. Меняются только настройки, известные этому клиенту.",
    ["Restore My Graphics Settings"] = "Восстановить мои настройки графики",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "Возвращает каждой настройке графики, изменённой кнопкой оптимизации, прежнее значение и удаляет резервную копию.",
    ["Graphics optimized: %d settings applied."] = "Графика оптимизирована: применено настроек: %d.",
    ["Graphics settings restored."] = "Настройки графики восстановлены.",
    ["Global Font"] = "Общий шрифт",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Шрифт всего интерфейса VuloClassicUI. Здесь появляются и шрифты, которыми делятся другие аддоны.\n\n|cffaaaaaaНужен /reload, чтобы он применился везде.|r",
    ["Outline Mode"] = "Режим обводки",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Обводка по умолчанию для текстов VuloClassicUI. Элементы с собственной настройкой обводки сохраняют её.\n\n|cffaaaaaaНужен /reload, чтобы применилось везде.|r",
    ["Apply to All Game Texts"] = "Применить ко всем игровым текстам",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "Заменяет шрифт собственных текстов игры (чат, подсказки, журнал заданий и другое) на общий шрифт.\n\n|cffaaaaaaПри отключении нужен /reload, чтобы вернуть исходные шрифты.|r",
    ["Class Colors"] = "Цвета классов",
    ["Resource Colors"] = "Цвета ресурсов",
    ["Font changed. /reload required to apply it everywhere."] = "Шрифт изменён. Нужен /reload, чтобы применить его везде.",
    ["Reset to default"] = "Сбросить к значению по умолчанию",
    ["Rename..."] = "Переименовать...",
    ["Rename loadout '%s'. Enter new name:"] = "Переименовать набор «%s». Новое имя:",
    ["A loadout named '%s' already exists."] = "Набор с именем «%s» уже существует.",
    ["Loadout '%s' renamed to '%s'."] = "Набор «%s» переименован в «%s».",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "Уровень предмета в ссылках на экипировку теперь стоит после ссылки, а не внутри её скобок. Некоторые клиенты заново сверяют текст ссылок со своими данными, и изменённый текст превращал ссылку в название задания с этим номером.",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "Заклинание больше не появляется у другого класса лишь потому, что у того есть другое заклинание с тем же названием. Записи на полосах учитывают свою классовую метку, а старые записи привязываются по идентификатору заклинания, а не по имени.",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "Встроенная библиотека медиа молча отбрасывала регистрации шрифтов, если никакой другой аддон не приносил более новую копию; шрифт аддона теперь регистрируется при любой установке.",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "Переименовать... – В контекстном меню набора и на странице наборов; значок, содержимое и привязка к талантам переезжают вместе с именем",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "Оптимизировать мои FPS и графику – Проверенный набор настроек графики с одноразовой резервной копией; кнопка восстановления рядом вернёт прежние значения",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "Шрифты и цвета – Новая вкладка: общий шрифт с режимом обводки, по желанию для всех игровых текстов, плюс цвета классов и ресурсов со сбросом в каждой строке",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "Разработчик – Скрывать ошибки Lua, включать ID в подсказках и сбрасывать все настройки — в новом разделе вкладки Общее",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "Вкладка Общее организована в разделы на сетке из двух столбцов, как и остальное окно. Новая вкладка приносит файл текстуры: перезапустите клиент один раз после обновления, один /reload стрелки сброса не покажет.",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "Увеличение остаётся выключенным на клиентах на основе Wrath (Titan Reforged): их журнал заданий уже является широким окном с двумя панелями, и увеличение сдвигало панель деталей на ряд кнопок.",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "Длинные выпадающие списки открываются вверх, когда снизу нет места. Раньше они уходили за нижний край экрана, где последние записи никогда нельзя было прокрутить в поле зрения.",
    ["On"] = "Вкл.",
    ["Select all"] = "Выбрать все",
    ["Deselect all"] = "Снять выбор",
    ["Interface layout (window positions and links)"] = "Компоновка интерфейса (позиции и связи окон)",
    ["Fonts & colors (account-wide)"] = "Шрифты и цвета (на весь аккаунт)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "Также несёт ваши общеаккаунтные настройки шрифта и цветов; они применяются сразу при импорте строки.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaaЭкспорт включит модулей: %d из %d.|r",
    ["Nothing selected to export."] = "Для экспорта ничего не выбрано.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaaСнимите отметку с модулей, чтобы поделиться только частью - частичная строка сливается с активным профилем импортирующего.|r",
    ["Standard Action Bars"] = "Стандартные панели команд",
    ["Modern"] = "Современный",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaaСобственные панели команд игры остаются на месте. Стиль рамки и Тёмный режим ниже приходят из модуля Dark Skin и оформляют кнопки Blizzard напрямую.|r",
    ["Apply layout to all bars"] = "Применить компоновку ко всем панелям",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "Копирует компоновку этой панели - масштаб, размер значков, кнопки в ряду, отступ, направление - на все остальные.",
    ["Layout applied to all bars."] = "Компоновка применена ко всем панелям.",
    ["Text sizes"] = "Размеры текста",
    ["Bar Display"] = "Отображение панелей",
    ["Menu, Bags & XP Bar"] = "Меню, сумки и полоса опыта",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaaРаботает только в современном режиме (вкладка Отображение панелей).|r",
    ["Click: layout settings. Right-click: text sizes."] = "Клик: настройки компоновки. Правый клик: размеры текста.",
    ["Bar Animations"] = "Анимации панелей",
    ["Tint the pressed state"] = "Окрашивать нажатие",
    ["Colours the flash a button shows while it is pressed down."] = "Красит вспышку, которую кнопка показывает, пока она нажата.",
    ["Tint the hover highlight"] = "Окрашивать подсветку при наведении",
    ["Colours the glow a button shows under the mouse."] = "Красит свечение, которое кнопка показывает под курсором.",
    ["Use class colour"] = "Использовать цвет класса",
    ["Enable bar background"] = "Включить фон панели",
    ["A flat colour panel behind the bar, sized with it."] = "Однотонная подложка позади панели, меняющая размер вместе с ней.",
    ["Padding"] = "Отступ",
    ["Flat (default)"] = "Однотонный (по умолчанию)",
    ["Core"] = "Основное",
    ["Opacity"] = "Непрозрачность",
    ["Durability"] = "Прочность",
    ["Talent points"] = "Очки талантов",
    ["Pulse"] = "Пульсация",
    ["Steady"] = "Постоянное",
    ["Background"] = "Фон",
    ["Low"] = "Низкий",
    ["Medium"] = "Средний",
    ["High"] = "Высокий",
    ["Dialog"] = "Диалог",
    ["Click an icon to jump to its settings."] = "Щёлкните по значку, чтобы перейти к его настройке.",
    ["Middle-click: hide until the next loading screen."] = "Средняя кнопка мыши: скрыть до следующего экрана загрузки.",
    ["Nothing to preview: every reminder is switched off."] = "Нечего показать: все напоминания отключены.",
    ["Show effects missing on others"] = "Показывать эффекты, отсутствующие у других",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "Проверяет группу или рейд на классовые бафы, которые вы могли бы наложить, и напоминает, когда у кого-то их нет.",
    ["Missing on %s: %s"] = "Отсутствует у %s: %s",
    ["In raids (minutes)"] = "В рейде (минуты)",
    ["In dungeons (minutes)"] = "В подземельях (минуты)",
    ["0 uses the global warn threshold."] = "0 — используется общий порог предупреждения.",
    ["Preferred food"] = "Предпочитаемая еда",
    ["Preferred flask or elixir"] = "Предпочитаемое зелье или эликсир",
    ["Preferred weapon enhancement"] = "Предпочитаемое улучшение оружия",
    ["Automatic (best in bags)"] = "Автоматически (лучшее в сумках)",
    ["Click to use."] = "Щёлкните, чтобы использовать.",
    ["Attach reminders to the cursor"] = "Закрепить напоминания у курсора",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "Показывает маленькие копии текущих напоминаний рядом с курсором мыши.",
    ["Helpers"] = "Помощники",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "Обратный отсчёт очереди, помощник мини-игры с усилениями и книга наставника в одном месте.",
    ["Open group board"] = "Открыть доску групп",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "Сканирует чат в поисках игроков, собирающих группы, и показывает их в окне по подземельям Classic/TBC (/vlfg или кнопка ниже).",
    ["Show minimap button"] = "Показывать кнопку на миникарте",
    ["PvP Settings"] = "Настройки PvP",
    ["Fullscreen"] = "Полный экран",
    ["Fullscreen dialog"] = "Полноэкранный диалог",
    ["Tooltip"] = "Подсказка",
    ["Orientation"] = "Ориентация",
    ["Horizontal"] = "Горизонтально",
    ["Vertical (up)"] = "Вертикально (вверх)",
    ["Vertical (down)"] = "Вертикально (вниз)",
    ["Fill opacity"] = "Непрозрачность заполнения",
    ["Below 100 the world shows through the filled part of the bar."] = "Ниже 100 через заполненную часть полосы просвечивает игровой мир.",
    ["The fill fades into a second colour towards its end."] = "Заполнение плавно переходит во второй цвет к своему краю.",
    ["Show plates for enemy pets"] = "Показывать плашки питомцев врагов",
    ["Spell name"] = "Название заклинания",
    ["Colour the last tick"] = "Окрашивать последний тик",
    ["Show latency text"] = "Показывать текст задержки",
    ["Vertical"] = "Вертикально",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "«Автоматически» складывает боковую позицию в столбец, а верхнюю или нижнюю — в строку.",
    ["Show older versions"] = "Показать предыдущие версии",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "%d повреждённых числовых значений удалено из настроек — теперь их снова можно сохранять.",
    ["Widen window"] = "Расширить окно",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "Дополнительная ширина окна друзей, чтобы длинные имена, заметки и зоны помещались в одну строку. 0 сохраняет ширину Blizzard.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ сохраняет компоновку Blizzard с дополнениями. Modern добавляет тёмное оформление и переносит все характеристики в панель справа от окна персонажа.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "Переопределяет групповой переключатель только для этой записи — например, чтобы отслеживать положительный эффект, наложенный на вас кем-то другим.",
    ["Group default"] = "Как у группы",
    ["Anyone's"] = "Любого",
    ["Use conditions"] = "Использовать условия",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "Снятая галочка откладывает запись: настройки сохраняются, но она не отображается. За шестерёнкой — перемещение, удаление и отдельные настройки записи.",
    ["Talent Window"] = "Окно талантов",
    ["Shows all three talent trees side by side in one window."] = "Показывает все три дерева талантов рядом в одном окне.",
    ["Points left: %d"] = "Осталось очков: %d",
    ["TALENTS"] = "ТАЛАНТЫ",
    ["Open Blizzard's talent window"] = "Открыть окно талантов Blizzard",
    ["For glyphs and everything this window does not cover."] = "Для символов и всего, что это окно не охватывает.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaaВсе три дерева талантов рядом, с текущими рангами и изучением по щелчку. Символы остаются в окне Blizzard — в одной кнопке от вас.|r",
    ["Replace Blizzard's talent window"] = "Заменить окно талантов Blizzard",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "При открытии талантов показывается это окно. Отключите, чтобы вернуть окно Blizzard с одним деревом.",
    ["Open talent window"] = "Открыть окно талантов",
    ["See-through"] = "Прозрачность",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "Скрывает заливку и подписи рамок при редактировании, чтобы видеть интерфейс, который вы выравниваете. Тонкие рамки остаются.",
    -- Patch notes 1.46.0
    ["Options"] = "Параметры",
    ["Talents"] = "Таланты",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "Страница открывается с двумя режимами: Стандарт сохраняет панели Blizzard со строками оформления, Современный использует собственные панели аддона с живым предпросмотром, фоном для каждой панели, подсветкой нажатия и наведения и текстурой полосы опыта",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "Современный – Третий стиль полосы произнесения игрока: плоский вид с именем и временем на полосе, плюс текстура полосы, рамка, окрашенный последний тик и индикатор задержки",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "На странице настроек есть живой предпросмотр; щелчок по его значку или полосе переходит к нужному разделу",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "Отображение чар и самоцветов больше не вытесняют друг друга на неанглийских клиентах, а китайский текст чар больше не обрезается посреди символа",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "Отслеживаемые записи стоят по две в строке, у каждой своя шестерёнка: убрать запись на скамейку без удаления, передвинуть или удалить, задать условия и переопределить Только то, что наложил я сам для одной этой записи",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "Прозрачность – Скрывает заливку и подписи рамок при редактировании, чтобы видеть интерфейс, который вы выравниваете",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "При перетаскивании и подгонке координаты показываются на самой рамке, а окно, к которому идёт привязка, пульсирует белым",
    ["The loot window can be moved on Wrath clients"] = "Окно добычи можно перемещать на клиентах Wrath",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "Расширить окно – Дополнительная ширина, чтобы длинные имена, заметки и зоны помещались в одну строку",
    ["The close glyph of every window is larger now"] = "Значок закрытия всех окон стал крупнее",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "Три вкладки с закреплённым предпросмотром, вариант имени внутри полосы и разделители тысяч у чисел здоровья",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "Строки с шестерёнкой раскрываются в своей колонке, строки аур выравниваются построчно, вспомогательные инструменты делят одну вкладку, а закреплённая шапка последней открытой вкладки убирается при переключении",
    ["Only the last five versions build at once; a button loads the older ones"] = "За раз строятся только последние пять версий; кнопка подгружает более старые",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "Ориентация, прозрачность заливки, слой рамки и живой предпросмотр на странице настроек",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "Строка профиля может нести выборку: выбранные модули, расположение окон, переопределения талантов и общеаккаунтные шрифты и цвета",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "Переключатели для каждого правила с именами в цветах классов, проверка группы на отсутствующие положительные эффекты, предпочтительная еда, фляга и масло для оружия, пороги для рейда и подземелья, стили свечения, масштаб и живой предпросмотр; средний щелчок скрывает напоминание до следующего экрана загрузки",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "Повреждённые числовые значения удаляются перед сохранением, и о них сообщается при следующем входе. Одно такое значение раньше сбрасывало все настройки учётной записи к значениям по умолчанию",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "Возврат тотемов стоит отдельной кнопкой после стихий на клиентах Wrath",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "Окно талантов – Все три дерева талантов рядом, с живыми рангами и изучением по щелчку на клиентах Wrath; символы остаются в одной кнопке",
    ["The string is selected - press Ctrl+C to copy it."] = "Строка выделена — нажмите Ctrl+C, чтобы скопировать.",
    ["%d characters"] = "Символов: %d",
    ["Paste the string here with Ctrl+V."] = "Вставьте строку сюда с помощью Ctrl+V.",
    ["String captured - %d characters."] = "Строка получена — символов: %d.",
    ["Partial string: anything missing is taken from your active profile."] = "Частичная строка: недостающее берётся из активного профиля.",
    ["Unticked parts keep your current settings."] = "Неотмеченные части сохраняют текущие настройки.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "Профиль '%s' импортирован. Переключиться на него и перезагрузить интерфейс?",
    ["Switch and reload"] = "Переключить и перезагрузить",
    ["Save a backup copy"] = "Создать резервную копию",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "Создаёт датированную копию активного профиля как точку восстановления. Ничего не переключается — копия просто появляется в списке профилей.",
    ["Backup '%s' created."] = "Резервная копия '%s' создана.",
    ["Go back"] = "Назад",
    ["Pixel-true plate size"] = "Точный размер табличек в пикселях",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "Задаёт размер табличек в пикселях экрана, а не в единицах интерфейса: высота 27 — это 27 пикселей на любом мониторе и при любом масштабе.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "Рамки теперь точно накрывают своё окно, в том же тёмном стиле, что и остальной интерфейс; имя стоит по центру и становится оранжевым, когда окно пристыковано к другому",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "Вне редактора остаётся маленькая ручка, поэтому разблокированная полоса восстановления по-прежнему принимает перетащенные заклинания, а тестовые предпросмотры остаются видимыми",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "Ячейка экипировки плаща в шести языках была переведена навигационным словом назад, теперь везде написано правильно",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "Точный размер табличек в пикселях – Задаёт размер табличек в пикселях экрана: высота 27 — это 27 пикселей на любом мониторе и при любом масштабе интерфейса",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "Размеры табличек теперь означают ровно то, что стоит на ползунках: игра больше не увеличивает тайком табличку цели и не уменьшает дальние, а предпросмотр совпадает с игрой — увеличение цели теперь целиком дело настройки масштаба таблички цели",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "Создать резервную копию – Один щелчок сохраняет датированную копию активного профиля как точку восстановления",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "Экспорт открывает полноценное окно с уже выделенной строкой, а импорт сначала показывает предпросмотр: переименуйте профиль и снимите отметки с ненужного, прежде чем что-либо будет записано",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "Строки экспорта сжимаются до доли прежней длины и помещаются в сообщение чата; строки из старых версий по-прежнему импортируются",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "На клиенте Wrath подсказка таланта показывала заглушку вместо описания, а клавиша талантов открывала окно, но не закрывала его — исправлено и то и другое",
    ["%s Locked"] = "%s заблокирована",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffПОТЕРЯ КОНТРОЛЯ|r\n|cffaaaaaaПеретащите или стрелки|r",
    ["%.1f seconds"] = "%.1f сек.",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Перемещение потери контроля включено. |cff9b6cffПеретащите фиолетовую рамку|r или используйте |cff9b6cffстрелки|r (SHIFT = 5 пикселей). Нажмите кнопку ещё раз, чтобы закончить.",
    ["Preview"] = "Предпросмотр",
    ["Loss of Control"] = "Потеря контроля",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "Показывает, что контролирует вас прямо сейчас — оглушение, страх, обездвиживание, немота, разоружение или заблокированная школа магии — со значком эффекта, его названием и оставшимся временем. Если действуют два эффекта сразу, более важный показан крупно, а следующий — маленьким значком рядом.",
    ["Show loss of control alert"] = "Показывать оповещение о потере контроля",
    ["Show in"] = "Показывать в",
    ["Arena and battlegrounds"] = "Арены и поля боя",
    ["Arena only"] = "Только на аренах",
    ["Name font size"] = "Размер шрифта названия",
    ["Timer font size"] = "Размер шрифта времени",
    ["Background and red lines"] = "Фон и красные линии",
    ["Show the next effect"] = "Показывать следующий эффект",
    ["Profile changed. Use /reload when you are out of combat."] = "Профиль изменён. Используйте /reload, когда выйдете из боя.",
    ["Profile keybind"] = "Горячая клавиша профиля",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "Переключает на этот профиль вне боя, затем предлагает перезагрузить интерфейс. Привязки восстанавливаются при входе в игру.",
    ["Use the global font"] = "Использовать общий шрифт",
    ["Name color"] = "Цвет названия",
    ["Timer color"] = "Цвет времени",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffПРЕРЫВАНИЯ|r\n|cffaaaaaaПеретащите или стрелки|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Перемещение панели прерываний включено. |cff9b6cffПеретащите фиолетовую рамку|r или используйте |cff9b6cffстрелки|r (SHIFT = 5 пикселей). Нажмите кнопку ещё раз, чтобы закончить.",
    ["Interrupts"] = "Прерывания",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "Следит в боевом журнале за прерываниями противников и запускает восстановление для каждого, отдельно по заклинателю: два врага одного класса получат по значку. Рамка окрашена в цвет класса заклинателя.",
    ["Show interrupt bar"] = "Показывать панель прерываний",
    ["Show interrupts that are still ready"] = "Показывать и готовые прерывания",
    ["Timer text on the icons"] = "Время на значках",
    ["Cooldown swipe on the icons"] = "Заливка восстановления на значках",
    ["Only take over the key while a fishing pole is worn"] = "Занимать клавишу только с удочкой в руках",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "Без удочки клавиша сохраняет то, что вы на неё назначили, и остаётся полезной вне рыбалки. Уже заброшенная леска клавишу удерживает. Это отключает автоматическое надевание удочки, ведь оно требует клавишу именно тогда, когда удочки нет.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "Заглушка рамки противника: боковая полоса размещается настройками ниже.",
    -- Patch notes 1.48.0
    ["Options Window"] = "Окно настроек",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "Потеря контроля – Показывает оглушение, страх, обездвиживание, немоту или блокировку школы, которая вас держит, со значком, названием и оставшимся временем",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "Прерывания – Отслеживает прерывания противников по боевому журналу, по значку на каждого заклинателя, с рамкой цвета его класса",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "Время на значках – Оставшиеся секунды на значках прерываний, со своим шрифтом, обводкой и цветом",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "Заливка восстановления на значках – Убирает вращающуюся тень и оставляет только число",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "У полосы значков рядом с рамками противников появился живой предпросмотр на вкладке Общее. Эти рамки существуют только на арене, поэтому её ползунки двигали то, чего не было видно.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "Разблокированная рамка перемещения больше не исчезает через мгновение после того, как кнопка её показала. Рамка и запущенный предпросмотр теперь игнорируют фильтр зоны: панель размещают там, где стоят, а это редко арена.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "Закреплённая полоса значков теперь появляется и на вкладке Расположение, где размер, отступ, форма и приближение считываются с неё прямо во время движения ползунка.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "Перемещение окон Blizzard больше не помечает каждое окно режима редактирования как затронутое этим дополнением, из-за чего игра отказывалась показывать рамку питомца в бою. Причиной был выбор макета, и он происходил при каждом входе в редактор, даже если ничего не размещали.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "У выбора значка есть кнопка закрытия, и он больше не висит поверх игры после закрытия окна персонажа.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "Занимать клавишу только с удочкой в руках – Без удочки клавиша сохраняет назначенное вами действие",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "Колесо мыши прокручивает боковой список и страницу. Окно также уменьшается под экран меньше себя — именно это не давало его перетаскивать при высоком масштабе интерфейса.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "Горячая клавиша профиля – Назначьте профиль на клавишу и переключайтесь на него вне боя",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "Обход сумок за напоминаниями о еде, фиале и масле для оружия сохраняется до изменения сумок вместо трёх проходов по всем сумкам дважды в секунду.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "Современный стиль рамки игрока больше не трогает рамки питомца и тотемов.",
    ["Fine tuning for this slot"] = "Тонкая настройка этого места",
    ["Slot settings"] = "Настройки места",
    ["Border settings"] = "Настройки рамки",
    ["Border size"] = "Толщина рамки",
    ["How solid the empty part of the bar is."] = "Насколько плотная пустая часть полосы.",
    ["Absorb settings"] = "Настройки поглощения",
    ["Border around the cast bar"] = "Рамка вокруг полосы заклинания",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "Выключено оставляет полосу заклинания без собственного контура; у полосы здоровья он сохраняется.",
    ["Top text"] = "Текст сверху",
    ["Left text"] = "Текст слева",
    ["Right text"] = "Текст справа",
    ["Centred text"] = "Текст по центру",
    ["Unit name"] = "Имя существа",
    ["Main text positions"] = "Основные позиции текста",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaaПо одному на место. Уровень стоит у левого края имени и следует за ним.|r",
    ["Health and cast bar"] = "Полоса здоровья и заклинания",
    ["Health bar width"] = "Ширина полосы здоровья",
    ["Health bar height"] = "Высота полосы здоровья",
    ["Cast icon"] = "Значок заклинания",
    ["Cast icon settings"] = "Настройки значка заклинания",
    ["Cast background"] = "Фон заклинания",
    ["Cast bar border"] = "Рамка полосы заклинания",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "Толщина собственной рамки полосы заклинания. 0 убирает её; у полосы здоровья рамка сохраняется.",
    ["Cast bar border colour"] = "Цвет рамки полосы заклинания",
    ["Cast timer"] = "Таймер заклинания",
    ["Cast timer settings"] = "Настройки таймера",
    ["Cast bar Y offset"] = "Смещение полосы заклинания по Y",
    ["Cast colours and effects"] = "Цвета и эффекты заклинаний",
    ["The bar's colour while a spell is being cast."] = "Цвет полосы во время произнесения заклинания.",
    ["More cast colours"] = "Другие цвета заклинаний",
    ["Interrupt ready"] = "Прерывание готово",
    ["Interrupt flash"] = "Вспышка прерывания",
    ["Interrupt-ready hint"] = "Подсказка: прерывание готово",
    ["Show cast bars in front of nameplates"] = "Показывать полосы заклинаний поверх индикаторов",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "Заклинания рисуются поверх всех индикаторов, чтобы важное заклинание не скрылось за полосой другого существа.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "Полоса заклинания противника вспыхивает и на мгновение показывает «Прервано», когда его заклинание остановлено.",
    ["Interrupt flash settings"] = "Настройки вспышки прерывания",
    ["Target, focus and hover effects"] = "Эффекты цели, фокуса и наведения",
    ["Target effect"] = "Эффект цели",
    ["A coloured edge around the plate you have targeted."] = "Цветная рамка вокруг индикатора, который выбран целью.",
    ["Target arrows"] = "Стрелки у цели",
    ["Arrow settings"] = "Настройки стрелок",
    ["Target bar colour on"] = "Включить цвет цели",
    ["Focus bar colour on"] = "Включить цвет фокуса",
    ["A coloured edge around the plate you have set as your focus."] = "Цветная рамка вокруг индикатора, назначенного фокусом.",
    ["Mouseover effect"] = "Эффект наведения",
    ["Mouseover effect settings"] = "Настройки эффекта наведения",
    ["General text"] = "Общий текст",
    ["Debuff duration"] = "Длительность отрицательных эффектов",
    ["Buff duration"] = "Длительность положительных эффектов",
    ["Crowd control duration"] = "Длительность контроля",
    ["Aura stacks"] = "Стаки эффектов",
    ["Timer text colour"] = "Цвет таймера",
    ["Stack text colour"] = "Цвет стаков",
    ["Text settings"] = "Настройки текста",
    ["Spell target"] = "Цель заклинания",
    ["Background settings"] = "Настройки фона",
    ["Hide the gryphons"] = "Скрыть грифонов",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "Убирает двух зверей по краям стандартной панели команд. Сама панель остаётся.",
    ["Extra indicators"] = "Дополнительные индикаторы",
    ["Enemy colours"] = "Цвета противников",
    ["Enemy types"] = "Типы противников",
    ["The health bar colour a unit takes from its reaction to you."] = "Цвет полосы, который существо получает по своему отношению к вам.",
    ["Neutral enemies"] = "Нейтральные существа",
    ["Units that are not hostile until you make them so."] = "Существа, которые становятся враждебными только если их задеть.",
    ["Other nameplates"] = "Другие индикаторы имён",
    ["Nameplate spacing"] = "Расстояние между индикаторами",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaaСобственные настройки игры, применяются сразу и не входят в профиль — кроме области нажатия. В бою не меняются.|r",
    ["Stackable nameplates"] = "Складывать индикаторы",
    ["Extra aura options"] = "Дополнительные настройки эффектов",
    ["Target and focus effects"] = "Эффекты цели и фокуса",
    ["Plate scale while casting"] = "Размер индикатора при произнесении",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "Индикатор существа, читающего заклинание, вырастает до этого размера, чтобы важное было заметно. 100 = выключено.",
    ["Opacity while casting"] = "Непрозрачность при произнесении",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "Индикатор читающего заклинание существа остаётся хотя бы настолько плотным, даже если выбрана другая цель.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "Имя существа уступает место названию заклинания на всё время произнесения.",
    ["Active talent group"] = "Активный набор талантов",
    ["Left-click: show this talent group"] = "Левая кнопка: показать этот набор талантов",
    ["Right-click: activate this talent group"] = "Правая кнопка: включить этот набор талантов",
    ["Talent group %d (not active)"] = "Набор талантов %d (не активен)",
    ["Talents can only be learned in the active talent group."] = "Таланты можно изучать только в активном наборе талантов.",
    ["Talent groups cannot be switched in combat."] = "Нельзя сменить набор талантов в бою.",
    ["This client refused to switch the talent group."] = "Клиент отклонил смену набора талантов.",
    ["Input line above the chat"] = "Строка ввода над чатом",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "Помещает строку ввода над областью сообщений, а не под ней. Панель и полоса вкладок следуют за ней.",
    ["Own background for the input line"] = "Собственный фон для строки ввода",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "Рисует строку ввода на собственном тёмном фоне вместо фона Blizzard. Тёмная фоновая панель уже закрывает строку ввода, поэтому это видно, когда панель выключена.",
    ["Addon buttons"] = "Кнопки аддонов",
    ["Click to show or hide the collected buttons."] = "Щелчок показывает или скрывает собранные кнопки.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "Где находятся кнопки миникарты других аддонов: вокруг карты, скрыты до наведения мыши или собраны в одну коробку под картой.",
    ["Around the minimap"] = "Вокруг миникарты",
    ["Only on mouseover"] = "Только при наведении",
    ["Collected in a box"] = "Собраны в одну коробку",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "Скрыть грифонов – Убирает двух зверей с торцов основной панели Blizzard, ничего больше не затемняя",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "Выключение модуля теперь действительно выключает его. Его обработчики регистрируются при загрузке, поэтому модуль, уже выключенный при входе, ни разу не проходил через своё отключение: оглушение на поле боя всё равно вызывало индикатор потери контроля, а панель прерываний заполнялась и больше не пустела, потому что таймер, убирающий её значки, запускается только при включении.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "Панель прерываний больше не читает боевой журнал всего мира. Она регистрировалась при загрузке и никогда не отписывалась, так что каждая строка боя где угодно — в рейде несколько тысяч в секунду — разбиралась ради панели, у которой в настройках по умолчанию стоят только арена и поля боя. Теперь она использует тот же фильтр зоны, что и индикатор рядом.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "Включение модуля прямо на арене считается прибытием. Решение о зоне жило только в экране загрузки, поэтому тот, кто включал его уже внутри, не получал таймера убывающей отдачи до следующей арены.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "Ползунок размера текста уровня предмета снова работает. Он искал числа в двух местах, где надеялся их найти, а там, где клиент подвешивает кнопки экипировки в другом месте, не находил ни одного и молча ничего не делал — снаружи это не отличить от того, что текст просто слишком мелкий.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "Строка ввода над чатом – Помещает строку ввода над областью сообщений, а не под ней, панель и полоса вкладок следуют за ней; только на клиенте Wrath",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "Собственный фон для строки ввода – Рисует строку ввода на собственном тёмном фоне вместо фона Blizzard, который вы видели, как только выключали тёмную панель; только на клиенте Wrath",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "Приближение значка теперь называется обрезкой значка и читается в процентах. Это тот же вопрос, который задают ползунки индикаторов имени, и он отвечал в сотых, пока те отвечали в процентах.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "Дополнительная ширина теперь принадлежит только вкладке друзей. Тексты строк там растягиваются вместе с окном, но заголовки столбцов на вкладках поиска, гильдии и рейда стоят на фиксированных отступах и не двигаются, поэтому каждый добавленный пункт ширины уходил в пустую правую половину. Эти три вкладки возвращаются к собственным пропорциям Blizzard, под которые их столбцы и вымерялись.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "Список наборов и выбор значка перенимают стиль окна персонажа. В классическом стиле это была плоская тёмная поверхность с сиреневым краем, а внутри — красные кнопки Blizzard: два материала на ширину ладони. Теперь там используется рамка диалога Blizzard, и они стоят в том же материале, что и окно, к которому примыкают, а современный стиль сохраняет плоский вид.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "Окно персонажа больше не ломается, когда боковая панель строит свою первую строку набора. Полоса-маркер строки всё ещё обращалась к акцентному цвету, который был убран, из-за чего список оставался пустым, а окно открывалось голым.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "Кнопки аддонов – Выберите, где находятся кнопки других аддонов: вокруг карты, скрыты до наведения мыши или собраны в одну коробку под ней; только на клиенте Wrath",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "Обрезка значка (%) – Сколько отрезается от рамки, которую игра запекает в свои значки, настраивается для каждого ряда эффектов и для значка полосы заклинания",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "Стиль скруглённой полосы больше не оставляет мёртвого места по краям. Круглая форма не заполняет собственное изображение — по всему её периметру идёт прозрачная кайма, — и растягивание этой каймы на широкой и низкой полосе оставляло около одиннадцати пунктов пустой полосы с каждого конца и едва один сверху и снизу, поэтому это бросалось в глаза по горизонтали, а не по вертикали.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "Страница настроек разрезана по вопросам, а не по механике. В шестнадцати разделах связанные настройки лежали далеко друг от друга: текстура полосы под одним заголовком, текстура полосы заклинания под другим; восемь настроек были доступны сразу из двух разделов.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "Каждый текст на индикаторе имени теперь занимает место, как это уже делали ряды эффектов: сверху, слева, справа или по центру, с именем цели или текстом здоровья. Четыре переключателя стали выбором положения, каждый начинает с того места, которое его текст уже занимал.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "В выпадающем списке наложения не было ни одного читаемого значения. Он читал настройку, которой у этого клиента нет; та, что есть, теперь читается и записывается, измеренная в работающей игре.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "Шестерёнка на строке половинной ширины открывает небольшое плавающее окно вместо того, чтобы раскрываться внутри ячейки. В половине ячейки нет места для ползунка, и шесть из них были сжаты там в огрызки.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "Образцы цвета, глаза, шестерёнки и стрелки стоят прямо рядом с элементом, которому принадлежат, а не в полосе значков справа, которая остаётся за шестерёнкой и точкой со справкой.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "На клиенте Wrath модуль полностью отступает, и клиент сохраняет собственное окно. Наше оформление обращается к элементам Blizzard по имени и по номеру области, а за этими именами у того клиента другая анатомия: чёрные дыры там, где были скрытые области, растянутая полоса заголовка, выпадающие списки поверх списка рецептов — и никакой ошибки, потому что ничего не падает, оно просто попадает не на те элементы.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "Вдоль правого края идут кнопки наборов талантов, по одной на каждый купленный набор. Левый щелчок показывает набор, правый включает его — то же разделение, что и в собственном окне Blizzard. Таланты можно изучать только в активном наборе, поэтому щелчок в предпросмотре ничего не делает, а подсказка предупреждает об этом заранее.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "На вкладке теперь книга вместо вопросительного знака. Этот знак — заглушка Blizzard для отсутствующего значка, и он читался как неисправность.",
    ["Glyphs"] = "Символы",
    ["CHARACTER"] = "Персонаж",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "Упаковывает выбранную раскладку панелей в строку, которую можно передать. Слоты, макросы и привязки клавиш идут вместе с ней.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "Читает строку раскладки панелей в вашу библиотеку. Применение к панелям остаётся отдельным шагом.",
    ["The bar setup string is damaged."] = "Строка раскладки панелей повреждена.",
    ["This is not a bar setup string."] = "Это не строка раскладки панелей.",
    ["Bar setup '%s' imported."] = "Раскладка панелей '%s' импортирована.",
    ["Macros left alone: the switch above is off."] = "Макросы не тронуты: переключатель выше выключен.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "Макросы: %d восстановлено, |cffff8800%d не удалось|r — список макросов, возможно, заполнен.",
    ["Macros: %d restored."] = "Макросы: %d восстановлено.",
    ["Key bindings left alone: the switch above is off."] = "Привязки клавиш не тронуты: переключатель выше выключен.",
    ["Key bindings: %d applied."] = "Привязки клавиш: %d назначено.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "Раскладка панелей '%s' сохранена: ячеек %d, макросов %d, привязок клавиш %d.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800Ни одной привязки клавиш не собрано.|r Возможно, этот клиент их не сообщает.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "Экспорт в строку – Упаковывает выбранную раскладку в строку, которую можно передать, вместе с ячейками, макросами и привязками клавиш",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "Импорт из строки – Читает чужую раскладку в вашу библиотеку; уже занятое имя получает номер, а не затирается",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "Импортированная раскладка пересобирается запись за записью, прежде чем попасть в библиотеку. Восстановление обходит каждую запись, поэтому испорченная прервала бы его на середине, когда часть панелей уже изменена. Сломанные записи отбрасываются, остальное всё равно доходит.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "Сохранение и загрузка говорят, что сделали. Оба всё это время считали свою работу и выбрасывали числа: раскладка, у которой не удался ни один макрос, выглядела так же, как раскладка без макросов, а сохранение без единой собранной привязки не говорило ничего.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "Окно персонажа можно разместить вручную на клиенте Wrath. Редактор Blizzard этим окном не владеет, поэтому оно идёт тем же прямым путём, что и окно добычи; одна рамка двигает вкладки персонажа, репутации и умений вместе, а панель характеристик и список наборов едут с ней.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "На клиенте Wrath окно сразу открывается широким. Ползунок всегда доходил до 400 — он просто начинался с нуля, так что лишнее место доставалось лишь тому, кто шёл его искать.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "Страница символов открывается кнопкой под кнопками наборов талантов и теперь тёмная. Рунный круг притушен, а не убран: именно по нему эта страница и узнаётся; гнёзда берут акцентный цвет, а рисунок символа и подсветка при взятии остаются как были.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "Кнопка набора талантов показывает значок своей ветки вместо вопросительного знака. Она спрашивала его через интерфейс, который отвечает не на каждом клиенте, и откатывалась к заглушке; теперь ответ выводится из самих рангов, а их прочесть неверно нельзя.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "Число уровня на рамке игрока стоит там, куда его ставит клиент, на клиенте Wrath. Наши две привязки вымерены под один лист рамки, и там, где поставляется другой, число оказывалось рядом с портретом — к тому же клиент сам поддерживает эту привязку и двигает её по мере появления значков отдыха и PvP.",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "Полоса гнёзд под окном",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "Помещает под окно персонажа полосу со всеми гнёздами вашей экипировки. Щелчок по гнезду вставляет в него самоцвет из сумок. Остаётся пустой на клиентах, в игре которых нет самоцветов.",
    ["Choose a gem"] = "Выберите самоцвет",
    ["No gems in your bags."] = "В сумках нет самоцветов.",
    ["Empty socket"] = "Пустое гнездо",
    ["Click to pick a gem from your bags."] = "Щёлкните, чтобы выбрать самоцвет из сумок.",
    ["Cannot socket gems in combat."] = "В бою нельзя вставлять самоцветы.",
    ["Close the socketing window first."] = "Сначала закройте окно вставки самоцветов.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "Полоса гнёзд под окном – Ряд со всеми гнёздами вашей экипировки под окном персонажа; щелчок по гнезду вставляет в него самоцвет из сумок",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "Текст чар на ячейках брони снова показывает чары, а не метку сложности предмета. Фильтр брал первую зелёную строку подсказки, а там, где у предмета есть метка, она стоит выше чар — поэтому каждая такая ячейка показывала метку, тогда как оружие двумя строками ниже показывало свои чары верно, потому что перед ними ничего не стояло. Метка и подсказки клиента в угловых скобках теперь распознаются обе, причём на любом языке, а не только на английском и немецком.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "Список наборов больше не отбрасывает тень за собственную рамку. То, что выглядело как фон, выходящий за границу, было тенью: не контуром, а четырьмя залитыми прямоугольниками, выступавшими до семи пикселей за рамку с каждой стороны, а за диалоговой рамкой Blizzard ей было не на что падать. Она убрана в обоих видах.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "В стиле Classic+ тёмный фон заканчивался перед узорной линией, а не на ней, и потому выступал за рамку со всех сторон.",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "Применить это расположение",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "Помещает имя цели и значение здоровья внутрь полосы, эффекты контроля слева от неё, входящие отрицательные эффекты над ними и положительные справа, а полосе заклинания даёт значок, остаток времени и цель. Ваше нынешнее расположение сначала сохраняется, и соседняя кнопка вернёт его.",
    ["Restore my arrangement"] = "Вернуть моё расположение",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "Возвращает каждое положение текста и аур к тому, каким оно было до применения расположения, и удаляет сохранённую копию. Всё, что вы с тех пор переставили вручную, тоже вернётся.",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "Расположение индикаторов применено. Соседняя кнопка вернёт прежнее.",
    ["Nameplate layout restored."] = "Расположение индикаторов восстановлено.",
    ["Shows"] = "Показывает",
    ["Current health"] = "Текущее здоровье",
    ["Current and maximum"] = "Текущее и максимальное",
    ["Current and percent"] = "Текущее и проценты",
    ["Separator"] = "Разделитель",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "То, что стоит между двумя числами, когда строка выше выставлена на текущее и проценты.",
    ["Brackets"] = "Скобки",
    ["Vertical bar"] = "Вертикальная черта",
    ["Dash"] = "Тире",
    ["Space"] = "Пробел",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "Собственный фон строки ввода предлагается на всех клиентах. Он был ограничен одним поколением клиента, а в коде уже было записано, что он работал бы везде.",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "Рамки значков стали точными до пикселя. Рамка там не отдельная текстура, а кромка пластины позади значка, поэтому обе должны лежать на одной пиксельной сетке, толщину надо считать в пикселях, а не в единицах кадра, и размер со шагом должны начинаться на целых пикселях. Ни одно из трёх не выполнялось, оттого кромка выходила в два пикселя с одной стороны и ни в один с противоположной.",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "Применить это расположение – Помещает имя цели и значение здоровья внутрь полосы, эффекты контроля слева, входящие отрицательные эффекты над ними и положительные справа, а полоса заклинания несёт значок, остаток времени и цель",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "Имя цели пряталось за заливкой полосы здоровья, как только текстовое место помещало его внутрь полосы. Имя и значение здоровья висят на разных родителях: значение создаётся на полосе, имя на индикаторе, а полоса — потомок индикатора, поэтому рисует поверх всего, что рисует индикатор. Пока имя стояло только над полосой, это не бросалось в глаза. Теперь у него собственный слой над полосой, но не привязанный к ней: режим одного имени прячет эту полосу, и текст, привязанный к скрытой рамке, ушёл бы вместе с ней.",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "К тексту здоровья вернулось управление: что он показывает и какой знак стоит между двумя числами. Оба по-прежнему считывались и были недостижимы с тех пор, как страницу перестроили.",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "Активный набор талантов на клиентах без более нового интерфейса для этого всегда сообщался как первый. Всё, что стоит за этим, считало, что работает набор один: заголовок называл неактивным тот набор, в котором вы стояли, кнопка активации предлагала переключиться на уже включённый, а переключение сообщало об успехе, ничего не меняя. Тот же вопрос задают пять файлов, так что переопределения профиля и наборы панелей читали оттуда же.",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "Страница символов постоянно стоит рядом с окном. Её вынимают из окна талантов Blizzard, где она живёт внутри области прокрутки того самого окна, которое мы заменяем, и возвращают при закрытии нашего.",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "Отдельная кнопка символов исчезла вместе с этим. Её единственной задачей было отправить вас на страницу, которая теперь стоит перед вами.",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "Полоса под заголовком несёт кнопку активации и название показанного набора талантов. До сих пор переключение существовало только как щелчок правой кнопкой по маленьким боковым значкам, и об этом ничто не сообщало.",
    ["Form paging"] = "Смена страниц по облику",
    ["Keep the main bar on its page in every form"] = "Оставлять основную панель на своей странице в любом облике",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaaКошка, медведь, скрытность, стойки и облик Тьмы обычно переключают основную панель на свою страницу. Отключите это, чтобы собранная вами панель оставалась на месте в любом облике.|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "Оставлять основную панель на своей странице в любом облике – Кошка, медведь, скрытность, стойки и облик Тьмы больше не переключают панель команд 1 на собственную страницу",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "Тикер, рисующий затемнение по восстановлению и окраску по дальности, больше не обходит выключенные панели. Он читал и перерисовывал каждую панель команд пять раз в секунду, включая те, чьих кнопок никто не видит, поэтому две панели обходились так же дорого, как все сразу.",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "Уход курсора с кнопки больше не создаёт новую проверку каждый раз. Проверка читает только панель, а не кнопку, поэтому она создаётся один раз на панель и используется всеми её кнопками.",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "Рамки противников остаются нетронутыми, пока вы действительно не попросили другое расположение. Это защищённые рамки: закрепить такую вне боя разрешено, но это помечает рамку до конца сеанса, и в следующий раз, когда стандартный интерфейс сам переместит её посреди раунда, его собственный вызов будет отклонён, а блокировка записана на нас. Закрепить защищённую рамку, не оставив этой пометки, невозможно, поэтому нетронутая настройка теперь сохраняет стандартное расположение. Порядок, отступ, направление роста и смещения ячеек по-прежнему работают: сообщение становится ценой функции, о которой вы попросили, а не тем, что каждая арена раздаёт даром.",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "Вверх и вниз снова работают для категории, которую вы выключили и включили обратно. Список порядка заполнялся один раз, пока был ещё пуст, поэтому то, чего в тот момент не существовало, так и не получало записи, а его стрелки затем до конца сеанса не делали ничего и молчали об этом.",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "Выключение модуля снова освобождает его обработчики событий. Пометка о том, какому модулю принадлежит обработчик, оставалась после снятия регистрации, и эта пометка удерживала жёсткую ссылку на каждый обработчик, который модуль когда-либо регистрировал.",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "Заклинания из книги заклинаний снова применяются даже после того, как книга была открыта из микроменю. Наши кнопки микроменю — дублёры: они передают щелчок стандартной кнопке позади себя, и всё дальнейшее выполняется внутри нашего собственного вызова — а для книги заклинаний это заканчивается тем, что книга записывает, какую свою половину она показывает. Эта запись считалась нашей, книга читает её при каждом щелчке по заклинанию, и потому любое применение из книги отклонялось как вызов от аддона. Вне боя тоже, до конца сеанса, пока интерфейс не перезагрузят. Открытие книги её клавишей никогда не страдало. Теперь микроменю несёт саму стандартную кнопку с нашим значком, так что через нас больше ничего не проходит.",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "При наведении на ячейку сумки появляется подсказка самой сумки — цвет качества, вместимость, всё, что несёт предмет, — а под ней подсказки по щелчкам, вместо одного лишь названия. И в окне инвентаря, и в банке: они разошлись, хотя обе панели — одно и то же.",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "Панель в окне инвентаря теперь принимает сумки так же, как это давно умеет банковская: перетащите сумку на ячейку, чтобы вставить её туда, или щёлкните по ячейке левой кнопкой, держа сумку на курсоре. Щелчок правой кнопкой пустой рукой снимает сумку обратно, а левой — по-прежнему показывает и скрывает её. Рюкзак и связка ключей не являются надетыми сумками: они ничего не принимают, и строка про правый щелчок им даже не предлагается.",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "Текст чар в ячейке запястий стоит ближе к соседним строкам, а текст чар на оружии — на шесть пикселей ниже.",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "Вкладка учителя теперь собственная кнопка. Раньше это была свободная вкладка книги заклинаний, которую мы переписывали при каждом обновлении, а книга перечитывает эти вкладки посреди собственного прохода. Кроме того, она исчезает вместе с книгой питомца, где раньше оставалась.",
    -- Nameplates: aura border + CC size
    ["Match the health bar height"] = "Подогнать под высоту полосы здоровья",
    ["The icon becomes a square exactly as tall as the health bar. The three size sliders below step aside while this is on."] = "Значок становится квадратным и ровно такой же высоты, как полоса здоровья. Три ползунка размера ниже отступают, пока это включено.",
    ["Border around aura icons"] = "Рамка вокруг значков эффектов",
    ["The thin rim around debuff, damage-over-time, buff and crowd-control icons. Its thickness follows the border size of the plate."] = "Тонкий кант вокруг значков отрицательных эффектов, периодического урона, положительных эффектов и контроля. Его толщина следует толщине рамки индикатора.",
    ["Aura border colour"] = "Цвет рамки эффектов",
    ["Border in the aura's own school colour"] = "Рамка цветом школы эффекта",
    ["Magic blue, curse purple, disease orange, poison green — instead of the one colour beside it."] = "Магия синим, проклятье фиолетовым, болезнь оранжевым, яд зелёным — вместо одного цвета рядом.",
    -- Global settings: settings window scale
    ["Settings Window Scale"] = "Размер окна настроек",
    ["Scales this settings window on its own. The game's interface keeps the size it has."] = "Масштабирует только это окно настроек. Игровой интерфейс сохраняет свой размер.",
    -- Patch notes 1.52.3
    ["Match the health bar height – Makes the crowd-control icon a square exactly as tall as the health bar, in place of its own size sliders"] = "Подогнать под высоту полосы здоровья – Делает значок контроля квадратным и ровно такой же высоты, как полоса здоровья, вместо его собственных ползунков размера",
    ["Border around aura icons – Switches the rim around debuff, damage-over-time, buff and crowd-control icons on or off, with its colour beside it"] = "Рамка вокруг значков эффектов – Включает и выключает кант вокруг значков отрицательных эффектов, периодического урона, положительных эффектов и контроля, цвет находится рядом",
    ["Text size – Sets how large the unit name and the health value are drawn, in the panel behind each of those two rows"] = "Размер текста – Задаёт, насколько крупно отрисовываются имя цели и значение здоровья, в панели за каждой из этих двух строк",
    ["A long unit name is trimmed with three dots instead of running through the health value. The two share the bar as soon as both sit inside it, so the name now gets the width that is actually free — and only a health value at the other end takes room away, because sharing one slot is something you did on purpose. Only a name that would overflow is capped at all, which is what keeps the level number glued to the name instead of hanging off an oversized box."] = "Длинное имя обрезается тремя точками вместо того, чтобы проходить сквозь значение здоровья. Как только оба стоят внутри полосы, они делят её, и имя теперь получает действительно свободную ширину — место у него отнимает только значение здоровья на другом конце, ведь делить одну позицию вы решили сами. Ограничивается лишь имя, которое иначе вышло бы за край, и именно это держит номер уровня вплотную к имени, а не на краю слишком широкого поля.",
    ["The aura border can also take the colour of the aura's own school. That switch was read from the start and had no control anywhere."] = "Рамка эффектов может также принимать цвет школы эффекта. Этот переключатель читался с самого начала, а управления для него нигде не было.",
    ["Settings Window Scale – Scales this settings window on its own, from 70 to 130 per cent, while the game's interface keeps the size it has"] = "Размер окна настроек – Масштабирует только это окно настроек, от 70 до 130 процентов, а игровой интерфейс сохраняет свой размер",
    ["Making the window smaller now gives it back its full size on a screen that was cutting it off. The fitting measured the room in the game's units and the window in its own, so scaling it down changed nothing about what it was allowed to be."] = "Уменьшение окна теперь возвращает ему полный размер на экране, который раньше его обрезал. Подгонка мерила место в единицах игры, а окно — в его собственных, поэтому уменьшение ничего не меняло в том, каким окну разрешено быть.",
    -- Nameplates: reverse aura swipe
    ["Reverse the swipe"] = "Обратить затемнение",
    ["The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone."] = "Тень нарастает по мере того, как эффект заканчивается: почти чистый значок означает, что он почти прошёл.",
    -- Character panel: socket overwrite confirmation
    ["Replace %s with %s? The gem that comes out is destroyed."] = "Заменить %s на %s? Извлечённый самоцвет будет уничтожен.",
    ["That socket has changed — nothing was socketed."] = "Это гнездо изменилось — ничего не вставлено.",
    ["Click to replace the gem — the old one is destroyed."] = "Щёлкните, чтобы заменить самоцвет — старый будет уничтожен.",
    ["Ask before overwriting a gem"] = "Спрашивать перед заменой самоцвета",
    ["A click on a socket that already holds a gem asks first — putting a gem in destroys the one that comes out."] = "Щелчок по гнезду, в котором уже есть самоцвет, сначала спросит — вставка самоцвета уничтожает тот, что извлекается.",
    -- Loadouts: equipping straight out of the bank
    ["%d of them came out of the bank."] = "Из них %d взято из банка.",
    ["in the bank — open the bank window to equip it"] = "в банке — откройте окно банка, чтобы надеть",
    -- Patch notes 1.52.4
    ["Ask before overwriting a gem – A click on a socket that already holds a gem asks first, because putting a gem in destroys the one that comes out"] = "Спрашивать перед заменой самоцвета – Щелчок по гнезду, в котором уже есть самоцвет, сначала спросит, ведь вставка самоцвета уничтожает тот, что извлекается",
    ["Pointing at an occupied socket says what a click on it costs. Clicking one was always allowed, nothing ever said so, and the gem that comes out is destroyed. The question names both gems in their quality colours, and it drops the action when the gear moved while it was standing — otherwise a swap under the open dialog would answer for a socket you never looked at."] = "Наведение на занятое гнездо теперь говорит, чего стоит щелчок по нему. Щёлкнуть по нему можно было всегда, об этом никто не говорил, а извлечённый самоцвет уничтожается. Вопрос называет оба самоцвета в цветах их качества и отменяет действие, если снаряжение изменилось, пока он стоял — иначе смена под открытым окном ответила бы за гнездо, на которое вы даже не смотрели.",
    ["Equipping a set at the bank takes the pieces that are lying in the bank, as long as the bank window is open. Until now they counted as missing, so you could stand at the bank and be told the set was not equippable. The message says how many of them came out of the bank, and the piece that comes off goes into the bank slot the new one came from. With the bank closed, a missing piece in there no longer only names its place, it says to open the bank window."] = "Надеть набор у банка теперь можно вместе с предметами, лежащими в банке, пока окно банка открыто. До сих пор они считались отсутствующими, так что можно было стоять у банка и слышать, что набор надеть нельзя. Сообщение говорит, сколько из них взято из банка, а снятый предмет попадает в ту ячейку банка, откуда пришёл новый. При закрытом банке отсутствующий предмет там больше не только называет своё место, он предлагает открыть окно банка.",
    ["The line that tells you which sets an item belongs to appears in item tooltips. It was built and hooked up from the start, but it went in through the one tooltip mechanism this client offers and never uses, so no line was ever drawn and nothing complained."] = "Строка, которая сообщает, в какие наборы входит предмет, появляется в подсказках предметов. Она была построена и подключена с самого начала, но шла через единственный механизм подсказок, который этот клиент предлагает и никогда не использует, поэтому строка ни разу не была нарисована и ничего не жаловалось.",
    ["Reverse the swipe – The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone"] = "Обратить затемнение – Тень нарастает по мере того, как эффект заканчивается: почти чистый значок означает, что он почти прошёл",
    ["The cooldown swipe on the aura icons has a control of its own. It was read from the start and could not be changed anywhere."] = "У заливки восстановления на значках эффектов появился собственный переключатель. Она читалась с самого начала, а изменить её было негде.",
    ["The raid target marker is visible at all. The eight marks live on one sheet, and the call that picks a tile out of it was working on a frame that never got the sheet — a cut-out of nothing, on every plate and in the preview, since the module was built."] = "Метка рейда вообще видна. Восемь знаков лежат на одном листе, и вызов, выбирающий из него плитку, работал на поверхности, которая этот лист никогда не получала — вырезка из ничего, на каждой полоске имени и в предпросмотре, с самой постройки модуля.",
    ["The raid target marker takes one of the six named slots, like the four aura rows. It had three positions of its own and could land on top of a row, which is the very collision the slots exist for. The old choice moves into the matching slot once and then goes, so there is no second control for the same question. Its room is reserved as soon as it is switched on, not only once a unit really carries a mark, so the rows do not jump every time somebody sets a skull."] = "Метка рейда занимает одно из шести названных мест, как и четыре ряда эффектов. У неё были три собственные позиции, и она могла лечь поверх ряда — именно то столкновение, ради которого эти места и появились. Старый выбор один раз переезжает в соответствующее место и затем исчезает, чтобы на один вопрос не было двух настроек. Место занимается сразу после включения, а не только когда цель действительно несёт знак, чтобы ряды не подпрыгивали каждый раз, когда кто-то ставит череп.",
    ["The marker's own offset and spacing sliders take effect again. They were writing two fields of their own while the plate read the slot, so the visible control was the one without an effect. The old values move across once."] = "Собственные ползунки смещения и отступа метки снова работают. Они писали в два своих поля, пока полоска имени читала место, так что видимая настройка была той, что ничего не делала. Старые значения переезжают один раз.",
    ["A mark set between two aura passes lands where it belongs. Where the marker goes is worked out in the aura pass, because only that knows how far the rows on its side reach, and the plate now remembers that point for the event that shows the marker on its own."] = "Знак, поставленный между двумя проходами по эффектам, оказывается там, где нужно. Место метки рассчитывается в проходе по эффектам, потому что только он знает, насколько далеко тянутся ряды его стороны, и полоска имени теперь запоминает эту точку для события, которое показывает метку отдельно.",
    ["The cast time and the cast target show something in the preview. Both only exist for a cast that is really running on a real unit, so both stayed empty while their switches, colours and side settings stood next to them with nothing to show."] = "Время произнесения и цель произнесения показывают что-то в предпросмотре. И то, и другое существует только для действительно идущего произнесения по настоящей цели, поэтому оба оставались пустыми, пока их переключатели, цвета и настройки стороны стояли рядом и показать им было нечего.",
    -- Slot picker: the bags moved under an open picker
    ["Your bags moved — pick the item again."] = "Содержимое сумок изменилось — выберите предмет заново.",
    -- Bar setups: load confirmation, imported macros left alone
    ["Load '%s'? Every button on your bars is overwritten or cleared."] = "Загрузить '%s'? Каждая кнопка на панелях будет перезаписана или очищена.",
    ["Macros: %d restored, %d of your own kept (an import does not rewrite them)."] = "Макросы: %d восстановлено, %d ваших сохранено (импорт их не перезаписывает).",
    -- Patch notes 1.52.5
    ["The enchant text of the wrist slot sits under its slot instead of beside it. The wrist is the last slot of the left column, and to the right of it lies the weapon row, which is where the line was writing."] = "Текст чар для наручей стоит под своей ячейкой, а не сбоку. Наручи занимают последнюю ячейку левого столбца, а справа от неё расположен ряд оружия, куда эта строка и заезжала.",
    ["Search field in the enchanting window – Leaves only the recipes whose name or reagents match what you type"] = "Поле поиска в окне наложения чар – Оставляет только рецепты, чьё название или реагенты совпадают с введённым текстом",
    ["The enchanting window is the one profession window that never had a search box. The field sits between the title and the slot dropdown: type into it and only the recipes whose name or one of their reagents matches stay, with the scroll bar shortening along with the list instead of leaving empty rows under the last hit. Recipes you starred still float to the top of what is left, and closing the window clears the text — otherwise the next visit would open on a list with most of the recipes missing and nothing on screen to explain it."] = "Окно наложения чар остаётся единственным окном профессии, у которого никогда не было поля поиска. Оно расположено между заголовком и списком слотов: введите текст, и останутся только рецепты, чьё название или один из реагентов совпадает, а полоса прокрутки укоротится вместе со списком, не оставляя пустых строк под последним совпадением. Рецепты со звёздочкой по-прежнему поднимаются наверх того, что осталось, а при закрытии окна текст очищается: иначе в следующий раз список открылся бы почти без рецептов и без единого объяснения на экране.",
    -- Patch notes 1.52.5
    ["Diminishing returns and interrupts recognise every rank of a spell. Both lists carried one identifier per spell, usually the one for rank one, so what is really cast at level seventy fell through: no icon for the polymorph, no bar for the kick. All ranks share their name, and the client knows the name behind every identifier already in the list, so one pass builds a name index that covers every rank at once, in the client's own language, which is the one the combat log speaks."] = "Убывающая отдача и прерывания распознают любой ранг заклинания. В обоих списках хранился лишь один идентификатор на заклинание, обычно от первого ранга, поэтому мимо проходило то, что действительно применяется на семидесятом уровне: ни значка для превращения, ни полосы для пинка. Все ранги делят одно название, а название для каждого идентификатора, уже стоящего в списке, клиент знает, поэтому один проход строит из них указатель по названиям, охватывающий все ранги сразу, на языке самого клиента, то есть на том, на котором говорит боевой журнал.",
    ["Loading a setup asks first. It sets a hundred and twenty slots and empties the ones the setup has nothing for, and a single click in the dropdown was enough. The only warning, for a setup belonging to another class, was a chat line that arrived after the damage was done."] = "Загрузка набора сначала спрашивает. Она занимает сто двадцать ячеек и очищает те, для которых у набора ничего нет, а хватало одного щелчка в выпадающем списке. Единственным предупреждением о наборе другого класса была строка в чате, приходившая уже после потери.",
    ["Importing a setup leaves your own macros and keybindings alone. Macros are matched by name, and a name like Pull belongs to everyone, so a foreign setup replaced the contents of your own macro of that name with the switch on by default and without a word about it. Imported setups are marked as foreign now and keep what is already there, and the message says how many were kept. A backup entry carrying no keys at all no longer gets restored either, which used to clear the keys of that command and save the result."] = "Импорт набора не трогает ваши собственные макросы и назначения клавиш. Макросы сопоставляются по названию, а название вроде Pull принадлежит всем, поэтому чужой набор заменял содержимое вашего одноимённого макроса, с включённым по умолчанию переключателем и без единого слова об этом. Импортированные наборы теперь помечены как чужие и оставляют существующее на месте, а сообщение говорит, сколько было сохранено. Запись резервной копии вовсе без клавиш тоже больше не восстанавливается: раньше это стирало клавиши такой команды и сохраняло результат.",
    ["The enchant text of a weapon sits above its slot. Beside a weapon there is the next weapon, and to the left the whole text column, so the line had nowhere to go; above the weapon row the paper doll is empty. It is centred over its own slot and wraps upward, so two enchanted weapons no longer write across each other."] = "Текст чар оружия стоит над его ячейкой. Рядом с оружием стоит следующее оружие, а слева весь столбец текста, так что строке было некуда деться, тогда как над рядом оружия кукла пуста. Она отцентрована над собственной ячейкой и переносится вверх, поэтому два зачарованных оружия больше не пишут друг поверх друга.",
    ["The question before overwriting a gem is only armed once the dialog is really standing. If one was already open the client reuses it, and rebuilding it cleared the note that had just been made, so the second question answered nothing at all and said nothing about it. The recheck now compares the item as well, and an open window on its own no longer counts as proof that it is the right one."] = "Вопрос перед заменой самоцвета взводится только тогда, когда окно действительно открыто. Если одно уже было открыто, клиент использует его заново, а пересборка стирала только что сделанную пометку, поэтому второй вопрос не отвечал ни на что и молчал об этом. Повторная проверка сравнивает теперь и сам предмет, а открытое окно само по себе больше не считается доказательством того, что оно нужное.",
    ["The item level of a piece the client has not cached yet appears once it arrives. The retry ran into the very gate that had excluded it and drew nothing, ever. It is capped at twenty attempts per item so it cannot turn into a loop that runs every tenth of a second."] = "Уровень предмета для вещи, которую клиент ещё не сохранил, появляется, как только приходит. Повторная попытка упиралась ровно в те ворота, что её и отсекли, и не рисовала ничего. Теперь она ограничена двадцатью попытками на предмет, чтобы не превратиться в цикл каждую десятую долю секунды.",
    ["Deleting an entry removes the one you clicked. It went by the position the row was built with, and the list is rewritten behind the open page whenever the trinket matching adds or removes entries after an equipment change, so the neighbour disappeared instead."] = "Удаление записи убирает именно ту, по которой вы щёлкнули. Оно шло по позиции, с которой строка была построена, а список переписывается за открытой страницей, как только подбор аксессуаров добавляет или убирает записи после смены снаряжения, поэтому исчезала соседняя.",
    ["Logging in no longer opens the edit mode behind your back. Restoring frame positions used to apply the layout by showing the client's own edit mode manager, and that rebuilds every system the editor owns out of our call stack, which hands them to the addon for the rest of the session. Measured in game: one such call three seconds after login, and twenty seconds later 1593 refused actions in combat, party and raid frames among them. The layout is still written, and the client applies it the next time it does so itself. A frame you drag by hand still settles immediately."] = "Вход в игру больше не открывает режим редактирования у вас за спиной. Восстановление позиций окон применяло раскладку через показ собственного управляющего режима редактирования, а тот пересобирает каждую подсистему редактора из нашего стека вызовов, из-за чего они до конца сеанса принадлежат аддону. Измерено в игре: такой вызов через три секунды после входа и ещё через двадцать секунд 1593 отклонённых действия в бою, включая рамки группы и рейда. Раскладка по-прежнему сохраняется, и клиент применяет её в следующий раз, когда делает это сам. Окно, которое вы перетаскиваете рукой, по-прежнему встаёт сразу.",
    ["A frame dropped after a fight has started keeps the spot you dropped it at. A drag can only begin out of combat but it can end in one, and letting go wrote the anchor onto a protected frame without asking. The position was already saved by then, so the saved value and the frame on screen would have disagreed for the rest of the session. The write now waits for the fight to end and is made good afterwards."] = "Окно, отпущенное после начала боя, остаётся там, где вы его отпустили. Перетаскивание может начаться только вне боя, но закончиться посреди него, и отпускание без спроса записывало привязку в защищённое окно. Позиция к этому моменту уже была сохранена, поэтому сохранённое значение и окно на экране противоречили бы друг другу до конца сеанса. Запись теперь дожидается конца боя и выполняется после него.",
    ["The client settings the fishing mode borrows survive a crash. The backup of your own values lived in memory only, so a reload, a disconnect or a crash while fishing mode was running took it along, and music, ambience, auto loot and soft targeting stayed on the fishing values for good with nothing left anywhere to say what they had been."] = "Настройки клиента, которые одалживает режим рыбалки, переживают вылет. Копия ваших собственных значений жила только в памяти, поэтому перезагрузка, обрыв связи или вылет при включённом режиме рыбалки уносили её с собой, и музыка, окружение, автоподбор и мягкое наведение навсегда оставались на рыбацких значениях, а нигде не оставалось записи о том, что было раньше.",
    ["Switching the camera zoom option off returns the zoom to the client's default. The comment promised as much and the code did nothing of the sort, so with the option already on from an earlier session there was no value of ours to fall back to and the maximum stayed for every session after. It is only reset while the value still is our maximum, so anything you have set yourself since then stays."] = "Выключение параметра приближения камеры возвращает приближение к значению клиента по умолчанию. Комментарий это обещал, код не делал ничего подобного, а если параметр был включён ещё с прошлого сеанса, то и возвращаться было не к чему: максимум оставался и во всех последующих сеансах. Сброс происходит только пока значение всё ещё равно нашему максимуму, поэтому всё, что вы настроили сами, остаётся на месте.",
    ["Unit tooltips no longer throw a Lua error on a unit without an identifier. The fallback one line above did the arithmetic on the missing identifier itself and handed the result to the very call that cannot take it."] = "Подсказки существ больше не выдают ошибку Lua на существе без идентификатора. Запасной вариант строкой выше сам считал по отсутствующему идентификатору и передавал результат ровно в тот вызов, который его принять не может.",
    ["A set finds its own piece when two items share an identifier, the way the owl's ring and the bear's ring do. Sets store the full reference but searched by the bare identifier; the search goes by identifier and suffix now, while enchants and gems stay out of it because those change during an item's life and would make a set report its own piece as missing."] = "Комплект находит собственную вещь и тогда, когда два предмета делят один идентификатор, как кольцо совы и кольцо медведя. Комплекты хранят полную ссылку, но искали по голому идентификатору; теперь поиск идёт по идентификатору и суффиксу, а чары и самоцветы намеренно остаются в стороне, потому что они меняются за жизнь предмета и заставили бы комплект счесть собственную вещь недостающей.",
    ["The name comes back after a cast the same way the interrupt flash already decides it. A retired field was still being asked, although the options page says it is read nowhere any more."] = "Имя возвращается после произнесения так же, как это давно решает вспышка прерывания. Выведенное из обращения поле всё ещё опрашивалось, хотя страница настроек говорит, что оно нигде больше не читается.",
    ["The click area of a plate returns to its measured size. The value that means the client's own size was only right as long as the setter had never run, so afterwards the old area stood until a reload and the sliders went up without ever coming back."] = "Область щелчка индикатора возвращается к своему измеренному размеру. Значение, означающее собственный размер клиента, было верным лишь пока задающая функция ни разу не выполнялась; после этого старая область держалась до перезагрузки, а ползунки шли вверх и никогда не возвращались.",
    ["An installation from before the schema stamp runs its migrations instead of skipping them. No stamp meant two opposite things, a fresh installation with nothing to migrate or one older than the stamp with everything still pending, and both were stamped current and skipped, so the older one silently lost every migration, its bar setups in their old storage place among them. The two are told apart now by whether there is any module data at all."] = "Установка, сделанная до появления отметки схемы, выполняет свои переносы вместо того, чтобы их пропускать. Отсутствие отметки означало две противоположные вещи: свежую установку, где переносить нечего, или установку старше отметки, где не сделано ничего, и обе помечались как актуальные и пропускались, из-за чего более старая молча теряла все переносы, включая наборы панелей в их прежнем месте хранения. Теперь их различают по тому, есть ли вообще данные модулей.",
    ["The strip for the weapon slots opens downward instead of sideways. The three weapons are the only slots standing in a row rather than a column, at the bottom of the paper doll, where sideways always runs into their own neighbour. It grows away from the middle of the screen so it cannot pass the near edge, and it tips upward when the window sits at the bottom of the screen."] = "Полоса ячеек оружия раскрывается вниз, а не вбок. Три ячейки оружия единственные стоят в ряд, а не в столбце, внизу куклы, где вбок всегда попадаешь в собственного соседа. Полоса растёт прочь от центра экрана, чтобы не выйти за ближний край, и опрокидывается вверх, когда окно стоит у нижнего края экрана.",
    ["A click in the picker can no longer hit whatever has moved into that bag slot in the meantime. It remembered bag and slot from the moment it was filled and listened to no bag event, so after a sort run a click hit what was lying there by then, which with a merchant window open would have been a sale. It follows bag changes now, and every click checks the item in place against the one the button was built for."] = "Щелчок в выборе больше не может попасть по тому, что тем временем переехало в эту ячейку сумки. Он запоминал сумку и ячейку с момента заполнения и не слушал ни одного события сумок, поэтому после сортировки щелчок попадал по тому, что лежало там теперь, а при открытом окне торговца это была бы продажа. Теперь он следит за изменениями в сумках, и каждый щелчок сверяет предмет на месте с тем, для которого кнопка была построена.",
    ["The merchant lock covers both trinket slots. A mixed-up condition left it applying to the lower one only."] = "Запрет продажи действует для обеих ячеек аксессуаров. Перепутанное условие оставляло его только для нижней.",
    ["The addon no longer stamps the client's own health text and target classification with its taint. Both called the client's updaters from our call stack, the very thing the same file forbids two hundred lines further down in writing and with a reason, which makes the client's next pass over those frames unsafe. Both write what they need themselves now. The standard border returns the moment the client next classifies your target."] = "Аддон больше не клеймит своим загрязнением ни текст здоровья, ни классификацию цели самого клиента. Оба вызывали обновляющие функции клиента из нашего стека вызовов, то есть ровно то, что двумястами строками ниже тот же файл запрещает прямым текстом и с обоснованием и что делает следующий проход клиента по этим рамкам небезопасным. Теперь каждый пишет нужное сам. Стандартная рамка возвращается, как только клиент в следующий раз определит вашу цель.",
    ["|cffff7777What it costs, and why this is off unless you switch it on: the answer has to sit on a name the client's own protected code reads, which hands the party and raid frames to this addon for the rest of the session. In combat they then refuse to resize and name this addon while doing it. Switching it back off stops it happening again but does not undo the session it already happened in - that takes a reload.|r"] = "|cffff7777Чего это стоит и почему оно выключено, пока вы сами не включите: ответ должен лежать на имени, которое читает защищённый код самого клиента, а это отдаёт рамки группы и рейда этому аддону до конца сеанса. В бою они начинают отказываться менять размер и называют при этом данный аддон. Обратное выключение лишь не даёт этому повториться, но не отменяет сеанс, в котором это уже случилось: для этого нужна перезагрузка интерфейса.|r",
    ["not applied - this client does reject the call, so the error is firing"] = "не применено: этот клиент действительно отклоняет вызов, поэтому ошибка возникает",
    -- Patch notes 1.52.6
    ["X Offset / Y Offset – Nudge the stack and reagent numbers away from their chosen corner; both sit behind the gear of the position row"] = "Смещение по X / Смещение по Y – Сдвигает числа стопок и реагентов от выбранного угла; оба ползунка лежат за шестерёнкой строки положения",
    ["Opening Edit Mode no longer hands the party and raid frames to the addon for the rest of the session. Merely opening it drove the client's frame editor through the addon, and in combat the client then refused to update those frames, naming the addon in the message. Only really moving one of Blizzard's frames still writes to the editor, and a frame that is hidden, like the focus frame while nothing is focused, never does."] = "Открытие режима редактирования больше не отдаёт рамки группы и рейда аддону до конца сеанса. Само открытие прогоняло редактор рамок клиента через аддон, и в бою клиент затем отказывался обновлять эти рамки, называя аддон в сообщении. В редактор теперь пишет только действительное перемещение рамки Blizzard, а скрытая рамка, как рамка фокуса без цели фокуса, не пишет никогда.",
    ["Opening Edit Mode closes the options window. It sat exactly on top of the boxes it had just unlocked."] = "Открытие режима редактирования закрывает окно настроек. Оно стояло ровно поверх квадратиков, которые само же только что разблокировало.",
    ["The equipment list steps aside for the rune engraving panel. That panel opens on the right side of the character sheet, exactly where the list docks, so the two stood on top of each other. The list now follows the panel's edge, and where the screen is too narrow for sheet, panel and list together, it moves to the left side of the sheet."] = "Список экипировки уступает место панели рунической гравировки. Эта панель открывается справа от окна персонажа, ровно там, где пристыкован список, и они стояли друг на друге. Теперь список следует за краем панели, а где экран слишком узок для окна, панели и списка вместе, он переходит на левую сторону окна персонажа.",
    ["The role fix ships switched off. What it fixes is a silent error that truncates one update when a nameplate appears; what it costs is that the party and raid frames count as touched by the addon for the whole session and refuse to resize in combat, with the addon named in the message. That price was reaching players who never chose it, so now only whoever switches the fix on pays it."] = "Исправление роли поставляется выключенным. Оно чинит тихую ошибку, обрезающую одно обновление при появлении таблички с именем; платой же служит то, что рамки группы и рейда весь сеанс считаются тронутыми аддоном и в бою отказываются менять размер, с именем аддона в сообщении. Эту цену платили и те, кто такого не выбирал, поэтому теперь её платит лишь тот, кто включает исправление.",
    ["The status line of the role fix tells the whole truth. With the fix off it used to claim it was not needed on this client, even for players who do have the error; it now says whether the fix is applied, not needed, or simply not switched on while the error is firing."] = "Строка состояния исправления роли говорит всю правду. Пока исправление выключено, она утверждала, что на этом клиенте оно не нужно, даже у игроков, у которых ошибка есть; теперь она говорит, применено ли исправление, не нужно ли оно, или оно просто не включено, пока ошибка происходит.",
    ["The bar ships switched off. A second resource bar is a strong opinion to hand someone who never asked for one, and the client already draws its own. Installations that already exist keep the bar exactly as it was."] = "Полоса поставляется выключенной. Навязывать вторую полосу ресурса тому, кто о ней не просил, слишком смело, а клиент и так рисует свою. Уже существующие установки сохраняют полосу ровно такой, какой она была.",
    ["The dark skin keeps Blizzard's rim off the stance buttons for good. Their updates write the button art back directly, past the hook that guards the action bars, so the rim used to return the first time you switched."] = "Тёмное оформление насовсем убирает рамку Blizzard с кнопок стоек. Их обновления пишут рисунок кнопки напрямую, мимо перехвата, который защищает панели команд, и рамка возвращалась при первой же смене стойки.",
    ["Bonus"] = "Бонус",
    ["Rating"] = "Рейтинг",
    ["Base"] = "База",
