    ["Spell Haste"] = "Скорость заклинаний",
    ["Increases your melee attack power."] = "Увеличивает силу атаки в ближнем бою.",
    ["Increases your armor, critical strike chance, and chance to dodge."] = "Увеличивает броню, вероятность критического удара и уклонения.",
    ["Increases your maximum health."] = "Увеличивает максимальный запас здоровья.",
    ["Increases your maximum mana and spell critical strike chance."] = "Увеличивает максимальный запас маны и вероятность критического удара заклинаниями.",
    ["Increases your health and mana regeneration."] = "Увеличивает скорость восстановления здоровья и маны.",
    ["Chance for your melee attacks to critically hit."] = "Вероятность нанести критический удар в ближнем бою.",
    ["Increases your melee attack speed."] = "Увеличивает скорость атаки в ближнем бою.",
    ["Reduces the chance that your melee attacks miss."] = "Уменьшает вероятность промаха в ближнем бою.",
    ["Increases the damage of your spells."] = "Увеличивает урон от ваших заклинаний.",
    ["Increases the healing done by your spells."] = "Увеличивает объем исцеления от ваших заклинаний.",
    ["Chance for your spells to critically hit."] = "Вероятность критического эффекта заклинаний.",
    ["Reduces the cast time of your spells."] = "Уменьшает время произнесения заклинаний.",
    ["Reduces the chance that your spells miss."] = "Уменьшает вероятность промаха заклинаний.",
    ["Increases your damage with melee weapons by %.1f damage per second."] = "Увеличивает урон оружием ближнего боя на %.1f ед. урона в секунду.",
    ["Reduces physical damage taken by %.2f%% against enemies of your level."] = "Уменьшает получаемый физический урон на %.2f%% против врагов вашего уровня.",
    ["Reduces your chance to be hit and to be critically hit."] = "Уменьшает вероятность получить удар, в том числе критический.",
    ["Chance to dodge enemy melee attacks."] = "Вероятность уклониться от атак ближнего боя.",
    ["Chance to parry enemy melee attacks."] = "Вероятность парировать атаки ближнего боя.",
    ["Chance to block enemy melee attacks with your shield."] = "Вероятность заблокировать щитом атаки ближнего боя.",
    ["Shadow (darkened Blizzard border)"] = "Тень (затемненная кайма Blizzard)",
    ["Standard (Blizzard's own look)"] = "Стандарт (родной вид Blizzard)",
    ["Pick how the action buttons look: Blizzard's own untouched button, the dark Shadow skin, or a masked shape (circle, square, hexagon)."] = "Выбор внешнего вида кнопок команд: родная кнопка Blizzard, темный стиль «Тень» или форма с маской (круг, квадрат, шестиугольник).",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): Blizzard's own look, the dark Shadow skin, or masked shapes.|r"] = "|cff9b6cffСтиль каймы кнопок и значков находится в модуле Dark Skin (Action Bars → Bar style): родной вид Blizzard, темный стиль «Тень» или формы с маской.|r",
    ["Circle (masked shape)"] = "Круг (форма с маской)",
    ["Square (masked shape)"] = "Квадрат (форма с маской)",
    ["Hexagon (masked shape)"] = "Шестиугольник (форма с маской)",
    ["WeakAuras style"] = "Стиль WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Стиль значков WeakAuras, независимо от панелей команд.",
    ["Shadow 1"] = "Shadow 1",
    ["Shadow 2"] = "Shadow 2",
    ["Shadow 3"] = "Shadow 3",
    ["Shadow 4"] = "Shadow 4",
    ["Shadow 5"] = "Shadow 5",
    ["Border color"] = "Цвет каймы",
    ["Tints the frame of the Shadow and shape styles. Reset it to get each style's built-in coloring back."] = "Подкрашивает рамку стилей «Тень» и форм. Сброс возвращает встроенный цвет стиля.",
    ["Tints the border layer of the aura sets. Reset it to get each set's built-in coloring back."] = "Подкрашивает слой каймы наборов аур. Сброс возвращает встроенный цвет набора.",
    ["Spell lists"] = "Списки заклинаний",
    ["Edit spell lists"] = "Изменить списки заклинаний",
    ["Always-show and never-show spell IDs for this row."] = "ID заклинаний, которые всегда или никогда не показываются в этом ряду.",
    ["Always show"] = "Всегда показывать",
    ["Never show"] = "Никогда не показывать",
    ["Auras on this list always appear in this row, even when its own rules would hide them."] = "Ауры из этого списка всегда видны в этом ряду, даже если его правила скрыли бы их.",
    ["Auras on this list never appear in this row."] = "Ауры из этого списка никогда не показываются в этом ряду.",
    ["No entries yet."] = "Записей пока нет.",
    ["Unknown spell"] = "Неизвестное заклинание",
    ["Click to switch this entry on or off without deleting it."] = "Щелкните, чтобы включить или выключить запись, не удаляя её.",
    ["Mine"] = "Мои",
    ["Any"] = "Все",
    ["Counts only your own casts - click to count any caster."] = "Считаются только ваши заклинания - щелкните, чтобы считать любого заклинателя.",
    ["Counts any caster - click to count only your own casts."] = "Считается любой заклинатель - щелкните, чтобы считать только ваши заклинания.",
    ["Low-health glow"] = "Свечение при низком здоровье",
    ["Lights the plate up once the unit drops below the chosen health percentage."] = "Подсвечивает индикатор, когда здоровье цели падает ниже выбранного процента.",
    ["Thin ring"] = "Тонкая рамка",
    ["Pulsing glow"] = "Пульсирующее свечение",
    ["Low-health percent"] = "Процент низкого здоровья",
    -- Patch notes 1.53.0
    ["Every row of the stats sheet now explains itself when you point at it, and spell haste has joined the sheet."] = "Каждая строка листа характеристик теперь объясняет себя при наведении, а скорость заклинаний добавилась на лист.",
    ["Custom class colours moved into the addon's own colour book. Writing them into the client's shared tables marked the party and raid frames as touched by the addon at every login, and the client then refused to resize them in combat. The clean-up has a price: the client's own windows and other addons show the standard class colours again, while the custom ones colour everything this addon draws."] = "Пользовательские цвета классов переехали в собственную книгу цветов аддона. Запись их в общие таблицы клиента помечала окна группы и рейда как затронутые аддоном при каждом входе, и клиент затем отказывался изменять их в бою. У наведения порядка есть цена: окна самого клиента и другие аддоны снова показывают стандартные цвета классов, а пользовательские окрашивают всё, что рисует этот аддон.",
    ["Edit spell lists – Every aura row carries an always-show and a never-show spell ID list, kept in its own editing window behind the slot's fine tuning"] = "Изменить списки заклинаний – Каждый ряд аур несёт список всегда показывать и список никогда не показывать по ID заклинаний, управляемые в отдельном окне редактирования за тонкой настройкой позиции",
    ["Low-health glow – Marks plates below a chosen health percentage, as a thin ring or a soft pulsing glow, in a colour of your choice"] = "Свечение при низком здоровье – Отмечает индикаторы ниже выбранного процента здоровья тонкой рамкой или мягким пульсирующим свечением, цветом на ваш выбор",
    ["The pulsing glow ships as a new texture file, so it takes one full client restart to appear; a reload is not enough."] = "Пульсирующее свечение поставляется новым файлом текстуры, поэтому появляется только после полного перезапуска клиента; перезагрузки интерфейса недостаточно.",
    ["The seal-twist helper no longer counts a swing ahead on parries or when attacking starts; its window used to point at a swing that never came."] = "Помощник смены печатей больше не засчитывает удар заранее при парированиях и в начале атаки; его окно указывало на удар, который так и не приходил.",
    ["The import preview no longer sits on top of the paste step of the import dialog."] = "Предпросмотр импорта больше не ложится поверх шага вставки в диалоге импорта.",
    ["The clock keeps ticking through abilities that replace the swing, Heroic Strike and Cleave among them: they write their own combat log line instead of a swing line, so the bar used to stand still exactly for the classes that queue such an ability on every swing."] = "Часы продолжают идти при способностях, заменяющих удар, среди них Героический удар и Рассекающий удар: они пишут в журнал боя собственную строку вместо строки удара, поэтому полоса застывала как раз у классов, которые ставят такую способность на каждый удар.",
    ["Swing-resetting spells that deal no damage, parried special attacks and extra attacks now reach the clock too."] = "Заклинания, сбрасывающие удар без урона, парированные особые атаки и дополнительные атаки теперь тоже доходят до часов.",
    ["WeakAuras style – A separate icon style for WeakAuras, independent of the action bars, with five Shadow aura sets"] = "Стиль WeakAuras – Отдельный стиль значков для WeakAuras, независимый от панелей команд, с пятью наборами аур Shadow",
    ["Border color – Tints the frame of the Shadow and shape styles; resetting it restores each style's built-in colouring"] = "Цвет каймы – Подкрашивает рамку стилей Shadow и фигур; сброс возвращает каждому стилю встроенную окраску",
    ["The bar style now starts at Blizzard's own untouched look, and the masked shapes circle, square and hexagon bring their own frames."] = "Стиль панелей теперь начинается с нетронутого облика Blizzard, а маскированные фигуры круг, квадрат и шестиугольник приносят собственные рамки.",
    -- Action Ring
    ["%d of %d entries"] = "%d из %d элементов",
    ["360 is a full circle; anything less opens a fan of that width."] = "360 — полный круг; меньшее значение открывает веер такой ширины.",
    ["Action Ring"] = "Кольцо действий",
    ["Action Ring %d"] = "Кольцо действий %d",
    ["Add an entry that runs a slash command or macro text."] = "Добавить элемент, который выполняет команду чата или текст макроса.",
    ["Add entry"] = "Добавить элемент",
    ["Add new ring"] = "Добавить новое кольцо",
    ["All %d rings are in use."] = "Все %d колец уже используются.",
    ["An extra key that closes the ring without using anything. ESCAPE always works."] = "Дополнительная клавиша, закрывающая кольцо без использования чего-либо. ESCAPE работает всегда.",
    ["Arc width"] = "Ширина дуги",
    ["At the cursor"] = "У курсора",
    ["Bind or change the key that opens this ring."] = "Назначить или изменить клавишу, открывающую это кольцо.",
    ["Cancel key: %s"] = "Клавиша отмены: %s",
    ["Clear cancel key"] = "Сбросить клавишу отмены",
    ["Clear select key"] = "Сбросить клавишу выбора",
    ["Click an entry to add it to the ring."] = "Щелкните по элементу, чтобы добавить его в кольцо.",
    ["Custom command"] = "Своя команда",
    ["Custom command..."] = "Своя команда...",
    ["Delete ring"] = "Удалить кольцо",
    ["Distance from centre"] = "Расстояние от центра",
    ["Edit ring"] = "Редактировать кольцо",
    ["Enable action ring"] = "Включить кольцо действий",
    ["Entries"] = "Элементы",
    ["Fixed screen position"] = "Фиксированная позиция на экране",
    ["Grey out unusable entries"] = "Затемнять недоступные элементы",
    ["Hold a keybind to open a ring of actions around the cursor; aim at an entry and release to use it."] = "Удерживайте клавишу, чтобы открыть кольцо действий вокруг курсора; наведите на элемент и отпустите, чтобы использовать его.",
    ["Horizontal offset"] = "Смещение по горизонтали",
    ["Keep the ring open"] = "Не закрывать кольцо",
    ["Key %s was bound to '%s' - now opens %s."] = "Клавиша %s была назначена на '%s' - теперь открывает %s.",
    ["Keybind: %s"] = "Клавиша: %s",
    ["Macros"] = "Макросы",
    ["Markers"] = "Метки",
    ["Not bound"] = "Не назначено",
    ["Open position"] = "Место открытия",
    ["Opens this ring without a key press. It closes by itself after a while, or press the button again."] = "Открывает это кольцо без нажатия клавиши. Оно закрывается само через некоторое время, либо нажмите кнопку еще раз.",
    ["Press a key... (ESC to cancel)"] = "Нажмите клавишу... (ESC — отмена)",
    ["Raid marker"] = "Рейдовая метка",
    ["Release to cancel"] = "Отпустите, чтобы отменить",
    ["Remove marker"] = "Убрать метку",
    ["Ring name"] = "Название кольца",
    ["Ring setup"] = "Настройка кольца",
    ["Select key: %s"] = "Клавиша выбора: %s",
    ["Show cooldowns"] = "Показывать восстановление",
    ["Show ring name in the middle"] = "Показывать название кольца в центре",
    ["Shown in the middle of the ring and in the keybinding list."] = "Отображается в центре кольца и в списке назначения клавиш.",
    ["Spells"] = "Заклинания",
    ["The key that uses the aimed entry while the ring is kept open. Without it the ring falls back to hold-and-release."] = "Клавиша, использующая выбранный элемент, пока кольцо остается открытым. Без нее кольцо работает по схеме «удерживать и отпустить».",
    ["The ring grows on its own when entries would overlap; this is the smallest size."] = "Кольцо само увеличивается, когда элементы перекрываются; это минимальный размер.",
    ["The ring stays open after the key is released. Aim and press the select key to use an entry; ESCAPE or the ring's key closes it."] = "Кольцо остается открытым после отпускания клавиши. Наведите и нажмите клавишу выбора, чтобы использовать элемент; ESCAPE или клавиша кольца закрывает его.",
    ["This ring is empty - add entries below."] = "Это кольцо пустое - добавьте элементы ниже.",
    ["This ring is empty - add entries in the options."] = "Это кольцо пустое - добавьте элементы в настройках.",
    ["This ring is full (%d entries)."] = "Это кольцо заполнено (элементов: %d).",
    ["Unbind"] = "Сбросить назначение",
    ["|cffaaaaaaHold a keybind to open a ring of actions. Aim at an entry and release the key to use it; release over the middle to cancel. Each ring has its own keybind and its own entries.|r"] = "|cffaaaaaaУдерживайте клавишу, чтобы открыть кольцо действий. Наведите на элемент и отпустите клавишу, чтобы использовать его; отпустите над центром, чтобы отменить. У каждого кольца своя клавиша и свои элементы.|r",
    -- Action Ring
    ["A dotted line from the centre toward the cursor. Ring layout only."] = "Пунктирная линия от центра к курсору. Только для раскладки «Кольцо».",
    ["A near-square grid keeps the worst pointer travel short."] = "Почти квадратная сетка сокращает наибольший путь указателя.",
    ["Apply this look to all rings"] = "Применить этот вид ко всем кольцам",
    ["Cancel form"] = "Отменить облик",
    ["Choose columns automatically"] = "Выбирать число столбцов автоматически",
    ["Clear all markers"] = "Убрать все метки",
    ["Columns"] = "Столбцы",
    ["Custom"] = "Особый",
    ["Custom selection colour"] = "Особый цвет выделения",
    ["Cycle raid markers"] = "Перебор рейдовых меток",
    ["Empty ring"] = "Пустое кольцо",
    ["Entries each side"] = "Элементов с каждой стороны",
    ["Hide entries this character cannot use"] = "Скрывать элементы, недоступные этому персонажу",
    ["Invert scroll direction"] = "Инвертировать направление прокрутки",
    ["New ring - empty or template"] = "Новое кольцо — пустое или по шаблону",
    ["Override the look for this ring"] = "Переопределить вид этого кольца",
    ["Ring"] = "Кольцо",
    ["Select with the mouse"] = "Выбирать мышью",
    ["Selection colour"] = "Цвет выделения",
    ["Show entry names"] = "Показывать названия элементов",
    ["Show pointer needle"] = "Показывать стрелку указателя",
    ["Strip (mouse wheel)"] = "Полоса (колесо мыши)",
    ["Strip direction"] = "Направление полосы",
    ["Templates are built from what this character has right now."] = "Шаблоны составляются из того, что есть у этого персонажа прямо сейчас.",
    ["The release fires the entry under the pointer; with this off, the wheel's entry fires."] = "При отпускании срабатывает элемент под указателем; если выключено, срабатывает элемент, выбранный колесом.",
    ["The shared settings take this ring's values and every ring's own override is removed."] = "Общие настройки получают значения этого кольца, а собственные переопределения всех колец удаляются.",
    ["Theme colour"] = "Цвет темы",
    ["This ring keeps its own layout and display settings; every other ring follows the shared ones above."] = "Это кольцо сохраняет собственные настройки раскладки и отображения; все остальные кольца следуют общим настройкам выше.",
    ["This ring's own look"] = "Собственный вид этого кольца",
    ["Unknown spells and missing macros are left out of the ring entirely. The stored entries stay for characters that can use them."] = "Неизвестные заклинания и отсутствующие макросы полностью исключаются из кольца. Сохранённые элементы остаются для персонажей, которые могут ими пользоваться.",
    ["|cffaaaaaaTurn the override on to give this ring its own settings.|r"] = "|cffaaaaaaВключите переопределение, чтобы задать этому кольцу собственные настройки.|r",
    ["Target markers"] = "Метки цели",
    ["Hearthstone"] = "Камень возвращения",
    ["Teleports"] = "Телепорты",
    ["Potions"] = "Зелья",
    ["Druid forms"] = "Облики друида",
    ["Stances and auras"] = "Стойки и ауры",
    ["Quest items"] = "Предметы заданий",
    -- Action Ring
    ["Not in combat - keybinds can't be changed while fighting."] = "Не в бою: назначения клавиш нельзя менять во время боя.",
    -- Action Ring
    ["Colour while a swing attack is queued"] = "Окрашивать, пока удар в очереди",
    ["While an on-next-swing attack (Heroic Strike, Cleave, Raptor Strike, Maul) is queued, the bar takes this colour - the resource it will eat is already spoken for."] = "Пока атака следующего удара (Героический удар, Рассекающий удар, Удар ящера, Трепка) находится в очереди, полоса принимает этот цвет: ресурс, который она потратит, уже занят.",
    ["Queued colour"] = "Цвет очереди",
    -- Patch notes 1.54.0
    ["Action Ring – Hold a keybind to open a ring of actions, aim at an entry and release to use it, spells, items and macros alike, in and out of combat"] = "Кольцо действий – Удерживайте назначенную клавишу, чтобы открыть кольцо действий; наведите на ячейку и отпустите, чтобы использовать её, заклинания, предметы и макросы одинаково, в бою и вне его",
    ["Choose between a ring, a grid and a mouse-wheel strip, run up to 16 rings with their own keys, entries and look, and start from ready-made templates such as raid marks, teleports, potions or shapeshifts."] = "На выбор кольцо, сетка и лента под колесо мыши, до 16 колец со своими клавишами, ячейками и обликом, а начать можно с готовых заготовок: метки рейда, телепорты, зелья, смена облика.",
    ["The options page shows a live preview of the selected ring that redraws while you drag a slider, and a plus button right in the picture adds entries."] = "Страница настроек показывает живой предпросмотр выбранного кольца, который перерисовывается прямо во время перетаскивания ползунка, а кнопка с плюсом прямо в картинке добавляет ячейки.",
    ["Colour while a swing attack is queued – The resource bar shows a colour of your choice while an on-next-swing attack waits for the hit, so you can see that the resource is already spoken for"] = "Окрашивать, пока удар в очереди – Полоса ресурса принимает выбранный вами цвет, пока атака следующего удара ждёт своего часа, чтобы было видно, что этот ресурс уже занят",
    ["The low-health glow now reaches further past the plate and rounds its corners more generously; before, it hugged the frame so tightly that it read as a border instead of a glow."] = "Свечение низкого здоровья теперь выходит дальше за края таблички и сильнее скругляет углы; раньше оно прилегало к рамке так плотно, что выглядело каймой, а не свечением.",
    ["The glow texture changed on disk, so it takes one full client restart to show its new shape; a reload is not enough."] = "Текстура свечения изменилась на диске, поэтому её новая форма появится только после полного перезапуска клиента; перезагрузки интерфейса недостаточно.",
    ["The bar colour opens a full colour picker instead of a short list of presets; existing profiles keep the colour they had."] = "Цвет полосы открывает полноценный выбор цвета вместо короткого списка заготовок; существующие профили сохраняют прежний цвет.",
    ["Bar default"] = "Как у панели",
    ["Edit glows..."] = "Изменить свечение...",
    ["Sound when ready"] = "Звук при готовности",
    ["Custom icon..."] = "Свой значок...",
    ["Park this icon (kept, never shown)"] = "Убрать значок в запас (настройки сохраняются, не отображается)",
    ["Drag to reorder. Right-click opens this icon's settings."] = "Перетащите, чтобы изменить порядок. Правый щелчок открывает настройки значка.",
    ["Drag to reorder. Right-click an icon for its settings."] = "Перетащите, чтобы изменить порядок. Правый щелчок по значку — его настройки.",
    ["Custom icon: enter a spell or item ID, or a texture path. Empty returns the real icon."] = "Свой значок: введите ID заклинания или предмета либо путь к текстуре. Пустое поле возвращает исходный значок.",
    ["Switching the module off now hands the micro buttons and the bag buttons back to their exact Blizzard positions, and a dialog offers the reload right away; the addon's row layout used to survive into the default bars until the next reload."] = "При отключении модуля микрокнопки и кнопки сумок возвращаются точно на свои места Blizzard, а диалог сразу предлагает перезагрузить интерфейс; раньше рядная компоновка аддона оставалась на стандартных панелях до следующей перезагрузки.",
    ["Sound when ready – Every icon can announce the end of its cooldown with a sound from the shared media list, auditioned right in the menu with every click"] = "Звук при готовности – Каждый значок может объявлять об окончании восстановления звуком из списка общих медиа, который прослушивается прямо в меню при каждом щелчке",
    ["Custom icon... – Any entry can wear an icon of your choice, named by spell or item ID or a texture path"] = "Свой значок... – Любая запись может носить значок на ваш выбор, заданный ID заклинания или предмета либо путём к текстуре",
    ["Right-clicking an icon in the preview strip opens a settings menu for that one entry: glow while ready with its own colour, the ready flash, the dimming, the cooldown swipe and the countdown text can each override the bar's setting, and the glow editor, parking and removing live in the same place. Removing is no longer the bare right-click itself, so a stray click cannot shorten the bar."] = "Правый щелчок по значку в полосе предпросмотра открывает меню настроек именно этой записи: свечение при готовности со своим цветом, вспышку, затемнение, развертку восстановления и текст отсчёта можно по отдельности переопределить относительно настроек панели, а редактор свечения, запас и удаление живут там же. Удаление больше не выполняется голым правым щелчком, так что случайный щелчок не укоротит панель.",
    ["Long popup menus, the module list on the minimap button among them, now show a window that scrolls with the mouse wheel instead of growing past the screen edge."] = "Длинные всплывающие меню, в том числе список модулей на кнопке у миникарты, теперь показывают окно, прокручиваемое колесом мыши, вместо того чтобы вырастать за край экрана.",
    ["Helm"] = "Шлем",
    ["Cloak"] = "Плащ",
    ["Don't change"] = "Не менять",
    ["shown"] = "показан",
    ["hidden"] = "скрыт",
    ["Resilience"] = "Устойчивость",
    ["Reduces the chance to be critically hit and the damage taken from critical strikes."] = "Снижает вероятность получения критического удара и урон от критических ударов.",
    -- Patch notes 1.56.0
    ["Keeping the main bar on its page in every form now also holds the standard main bar, even while the whole module is off. The keys fire exactly what the buttons show, and switching to bars 2 to 6 by hand still works."] = "Удержание основной панели на её странице в любом облике теперь действует и на стандартную основную панель, даже когда весь модуль выключен. Клавиши запускают ровно то, что показывают кнопки, а ручное переключение на панели со 2 по 6 по-прежнему работает.",
    ["The stats sheet shows resilience under Defense, with the rating and its percent effect in the tooltip."] = "Лист характеристик показывает устойчивость в разделе защиты, с рейтингом и его процентным эффектом в подсказке.",
    ["The enchant text on the equipment slots no longer falls onto the green armor line of pieces with built-in bonus armor; that line only stands in when no real enchant follows."] = "Текст чар у ячеек экипировки больше не падает на зелёную строку брони вещей со встроенной дополнительной бронёй; эта строка подставляется только тогда, когда настоящих чар нет.",
    ["Helm / Cloak – Each set can show, hide or leave untouched the helm and the cloak as it is equipped, chosen in the row's right-click menu, and the row tooltip names the choice"] = "Шлем / Плащ – Каждый комплект может показывать, скрывать или не трогать шлем и плащ при надевании, выбор делается в меню правой кнопки строки, а подсказка строки называет выбранное",
    ["The set rows can be reordered with the left mouse button held down: a translucent ghost follows the pointer, a line in the accent colour marks where the row will land, and letting go outside the list cancels. Existing sets keep their alphabetical order as the starting point, new ones join at the end."] = "Строки комплектов можно переставлять, удерживая левую кнопку мыши: полупрозрачный призрак следует за указателем, линия акцентного цвета показывает, куда встанет строка, а отпускание за пределами списка отменяет перенос. Существующие комплекты начинают со своего алфавитного порядка, новые встают в конец.",
    ["The red auto-attack blink sits exactly on the icon in the skinned button styles and is cut to the same shape; it used to be drawn for the standard button art and blinked beside the icon."] = "Красное мигание автоатаки в оформленных стилях кнопок сидит точно на значке и обрезается по той же форме; оно было нарисовано под стандартную графику кнопки и мигало рядом со значком.",
    ["Popup dialogs measure their frame with the font that is really drawn; with long texts the buttons used to hang below the border."] = "Диалоговые окна измеряют свою рамку тем шрифтом, который действительно рисуется; при длинных текстах кнопки свисали ниже рамки.",
    ["In your bags: %d"] = "В сумках: %d",
    ["In the bank: %d"] = "В банке: %d",
    ["Item counts in tooltips"] = "Количество в подсказках",
    ["Item tooltips show how many you carry in your bags and how many sit in the bank, as last seen at a banker."] = "Подсказки предметов показывают, сколько их у вас в сумках и сколько лежит в банке по данным последнего визита к банкиру.",
    ["Fonts"] = "Шрифты",
    ["Colors"] = "Цвета",
    ["Module Fonts"] = "Шрифты модулей",
    ["|cffaaaaaaGive single modules their own font; everything else follows the global font. Changes need a /reload.|r"] = "|cffaaaaaaОтдельным модулям можно задать собственный шрифт; всё остальное следует глобальному шрифту. Изменения требуют /reload.|r",
    ["Button texts (keybind, macro name, count) and the XP bar text."] = "Тексты кнопок (клавиша, имя макроса, количество) и текст полосы опыта.",
    ["Name, level, health, cast and aura text on nameplates."] = "Имя, уровень, здоровье, текст заклинаний и аур на именных планках.",
    ["Duration, stacks and keybind text on the icons, the strip and the resource bar."] = "Текст длительности, зарядов и клавиш на значках, ленте и полосе ресурса.",
    ["Chat messages, the input box and the tab labels, while the chat module uses the addon font."] = "Сообщения чата, поле ввода и подписи вкладок, пока модуль чата использует шрифт аддона.",
    ["The stats sheet of the modern character panel."] = "Лист характеристик современного окна персонажа.",
    ["Requires /reload."] = "Требуется /reload.",
    ["Reduces the chance that your attacks are dodged or parried."] = "Снижает вероятность того, что противник уклонится от вашей атаки или парирует её.",
    ["Dodge and parry reduction"] = "Снижение уклонения и парирования",
    -- Patch notes 1.57.0
    ["Bags & Bank"] = "Сумки и банк",
    ["Item counts in tooltips – Item tooltips show how many you carry in your bags and how many sit in the bank, as last seen at a banker"] = "Количество в подсказках – Подсказки предметов показывают, сколько их у вас в сумках и сколько лежит в банке по данным последнего визита к банкиру",
    ["The bank mirror is taken on every banker visit now, with the default bank window and with the bags module switched off alike; it used to fill only while the replacement window was on."] = "Зеркало банка теперь снимается при каждом визите к банкиру, в том числе со стандартным окном банка и при выключенном модуле сумок; раньше оно заполнялось только при включённом заменяющем окне.",
    ["The melee section shows expertise the way the game's own sheet does, with both weapons when dual wielding; the tooltip names the dodge and parry reduction in percent along with the rating. Only on clients whose game has the stat."] = "Раздел ближнего боя показывает мастерство так же, как собственный лист игры, при двух оружиях — для обеих рук; подсказка называет снижение уклонения и парирования в процентах вместе с рейтингом. Только на клиентах, где игра знает эту характеристику.",
    ["Module Fonts – Give single modules their own font: action bars, nameplates, cooldown manager, chat and the stats sheet each take a face of their own, everything else follows the global font"] = "Шрифты модулей – Отдельным модулям можно задать собственный шрифт: панели команд, именные планки, менеджер восстановления, чат и лист характеристик получают каждый свой, всё остальное следует глобальному шрифту",
    ["Fonts and colors live on two separate tabs now; the class and resource colors moved to their own Colors tab unchanged."] = "Шрифты и цвета теперь на двух отдельных вкладках; цвета классов и ресурсов без изменений переехали на собственную вкладку цветов.",
    ["An imported look string carries the module fonts along, and the action bar buttons keep the game's own lettering until a module font is chosen for them."] = "Импортированная строка оформления переносит и шрифты модулей, а кнопки панелей команд сохраняют игровой шрифт, пока для них не выбран шрифт модуля.",
    -- Patch notes 1.57.1
    ["The form-paging section shows up in Standard mode too. The switch itself already reached the standard main bar; the row that flips it was only drawn in Modern mode, so nobody running the standard bars could find it."] = "Раздел против перелистывания страниц при смене облика теперь виден и в стандартном режиме. Сам переключатель давно действовал на стандартную основную панель; его строка рисовалась только в современном режиме, и со стандартными панелями её было не найти.",
    ["Seven hot paths allocate less memory: unit-frame health text, nameplate number formatting and health smoothing, cooldown-manager scan keys, combat-text throttling, bag refreshes, the arena bar-text hook and the reminder pass all reuse what they used to rebuild, so the garbage collector has less to clean up in combat."] = "Семь горячих путей выделяют меньше памяти: текст здоровья рамок юнитов, формат чисел и сглаживание здоровья именных планок, ключи сканирования менеджера восстановления, ограничитель боевого текста, обновление сумок, текст полос арены и проход напоминаний используют повторно то, что раньше строили заново; сборщику мусора в бою достаётся меньше работы.",
    ["The red auto-attack blink sits on the icon in every button style now, the untouched standard button included. The game defines that blink with retail-sized frame art and a single corner anchor, so on the classic button art it hung past the button to the right and bottom."] = "Красное мигание автоатаки теперь сидит на значке в любом стиле кнопок, включая нетронутую стандартную кнопку. Игра задаёт это мигание рамкой в размере Retail с единственным угловым якорем, поэтому на классической графике кнопок оно свисало вправо и вниз.",
-- Trackbars
["Clock"] = "Часы",
["Start empty"] = "Начать с пустого",
["An empty bar to build from scratch."] = "Пустая панель, чтобы собрать её с нуля.",
["Top/Bottom info bar"] = "Инфопанель сверху/снизу",
["Full-width bar with the classic info blocks."] = "Панель на всю ширину с классическими информационными блоками.",
["Minimap companion"] = "Спутник миникарты",
["Compact clock and FPS readout."] = "Компактные часы и показатель FPS.",
["Micro menu strip"] = "Полоса микроменю",
["Just the micro menu buttons."] = "Только кнопки микроменю.",
["Bar %d"] = "Панель %d",
["User-built info bars: clock, gold, XP, micro menu and more."] = "Собственные инфопанели: часы, золото, опыт, микроменю и многое другое.",
["Server time"] = "Время сервера",
["Local time"] = "Локальное время",
["fps"] = "fps",
["ms"] = "ms",
["Dur"] = "Длит.",
["Session earned"] = "Заработано за сеанс",
["Session spent"] = "Потрачено за сеанс",
["Session profit"] = "Прибыль за сеанс",
["+%d more"] = "+%d ещё",
["Total"] = "Итого",
["Left-Click: bags -- Ctrl+Right-Click: reset session"] = "Левая кнопка: сумки -- Ctrl+правая кнопка: сбросить сеанс",
["free"] = "свободно",
["Max level (Right-Click: reputation)"] = "Макс. уровень (Правая кнопка: репутация)",
["XP"] = "Опыт",
["No reputation tracked"] = "Репутация не отслеживается",
["Current"] = "Текущий",
["Rested"] = "Отдых",
["Right-Click: toggle XP / reputation"] = "Правая кнопка: переключить опыт / репутацию",
["Gap"] = "Отступ",
["Use accent color"] = "Использовать акцентный цвет",
["Paints this block in the interface accent color instead of the color above."] = "Окрашивает этот блок в акцентный цвет интерфейса вместо цвета, указанного выше.",
["24-hour clock"] = "24-часовой формат",
["Show world latency"] = "Показывать мировую задержку",
["Show free bag slots"] = "Показывать свободные ячейки сумок",
["Short format (gold only)"] = "Короткий формат (только золото)",
["Show coordinates"] = "Показывать координаты",
["|cffaaaaaaBuild your own info bars from blocks: clock, gold, XP, latency, micro menu and more. Create a bar from a template, then stack and order its blocks below.|r"] = "|cffaaaaaaСоберите собственные инфопанели из блоков: часы, золото, опыт, задержка, микроменю и многое другое. Создайте панель из шаблона, а затем расположите и упорядочьте её блоки ниже.|r",
["Enable Trackbars"] = "Включить Trackbars",
["Create your first bar"] = "Создайте свою первую панель",
["|cffaaaaaaPick a template to start with. Every bar stays fully editable afterwards.|r"] = "|cffaaaaaaВыберите шаблон для начала. Панель остаётся полностью редактируемой в дальнейшем.|r",
["Bar"] = "Панель",
["New bar..."] = "Новая панель...",
["Click again to delete"] = "Нажмите ещё раз, чтобы удалить",
["Removes the selected bar and all of its blocks."] = "Удаляет выбранную панель и все её блоки.",
["Bar Settings"] = "Настройки панели",
["Length"] = "Длина",
["Edge"] = "Край",
["Edge offset"] = "Смещение от края",
["Stop moving"] = "Остановить перемещение",
["Shows the movers so free-standing bars can be dragged into place."] = "Показывает рамки перемещения, чтобы отдельно стоящие панели можно было перетащить на место.",
["Distribution"] = "Распределение",
["Auto sizes each block by its content; even split gives every block the same share of the bar."] = "Автоматически подбирает размер каждого блока по содержимому; равномерное распределение даёт каждому блоку одинаковую долю панели.",
["Font scale"] = "Масштаб шрифта",
["Hide border"] = "Скрыть обрамление",
["Blocks"] = "Блоки",
["|cffaaaaaaThis bar has no blocks yet -- add one below.|r"] = "|cffaaaaaaУ этой панели пока нет блоков -- добавьте один ниже.|r",
["Add block..."] = "Добавить блок...",
["Full width"] = "Во всю ширину",
["Custom length"] = "Своя длина",
["Even split"] = "Равномерное распределение",

    -- Patch notes 1.58.0
    ["Trackbars"] = "Trackbars",
    ["Trackbars – Build your own info bars from blocks: clock, gold, XP, latency, micro menu and more"] = "Trackbars – Собирайте собственные информационные панели из блоков: часы, золото, опыт, задержка, микроменю и не только",
    ["Bars are created from templates: start empty, a full-width info bar pinned to the top or bottom edge, a compact minimap companion, or a micro menu strip. Every bar stays fully editable afterwards."] = "Панели создаются по шаблонам: начать с пустой, панель во всю ширину у верхнего или нижнего края экрана, компактный спутник миникарты или полоса микроменю. Любая панель после этого остаётся полностью настраиваемой.",
    ["Ten blocks to stack and order: clock, gold, XP and reputation, FPS, latency, durability, free bag slots, zone with coordinates, micro menu, and a spacer."] = "Десять блоков, которые можно складывать и упорядочивать: часы, золото, опыт и репутация, FPS, задержка, прочность, свободные ячейки сумок, зона с координатами, микроменю и разделитель.",
    ["The gold block tracks what the current session earned and spent, and its tooltip lists the gold of every character on the account, richest first."] = "Блок золота ведёт учёт доходов и расходов текущей сессии, а его подсказка перечисляет золото всех персонажей учётной записи, начиная с самых богатых.",
    ["The XP block renders a real progress bar with the rested bonus overlaid, and a right-click switches it to the tracked reputation."] = "Блок опыта рисует настоящую полосу прогресса с наложенным бонусом отдыха, а щелчок правой кнопкой переключает его на отслеживаемую репутацию.",
    ["The micro menu opens the spellbook, talents and friends through the game's own buttons, so it works safely in combat and never blocks spell casting."] = "Микроменю открывает книгу заклинаний, таланты и список друзей через собственные кнопки игры, поэтому безопасно работает в бою и никогда не мешает произнесению заклинаний.",
    ["The module ships disabled: switch it on under HUD in the options window."] = "Модуль поставляется выключенным: включите его в разделе HUD окна настроек.",
-- Resistance verdict
["Resists on average %d%% of matching spell damage against boss enemies."] = "В среднем сопротивляется %d%% урона от заклинаний этой школы против боссов.",
["Decent"] = "Неплохо",
["Good"] = "Хорошо",
["Very good"] = "Очень хорошо",
["Maximum"] = "Максимум",
    -- Patch notes 1.58.1
    ["The resistance tooltips now rate the value: how much matching spell damage you resist on average against boss enemies, by the game's own formula, plus a colored verdict from Low to Maximum."] = "Подсказки сопротивлений теперь оценивают значение: какая доля соответствующего урона от заклинаний в среднем поглощается против боссов по формуле самой игры, плюс цветная оценка от «Низко» до «Максимум».",
    ["Two copies of the same item that differ only in their gems or enchants now swap correctly when switching sets. A regemmed single copy still counts as equipped and is never reported missing. If a set was saved before the gems went in, save it once more while wearing the right copy."] = "Две копии одного предмета, различающиеся только камнями или зачарованием, теперь корректно меняются при смене комплекта. Единственный экземпляр с новыми камнями по-прежнему считается надетым и никогда не помечается отсутствующим. Если комплект был сохранён до установки камней, сохраните его ещё раз, надев правильную копию.",
    ["A sweep over thirteen files cuts memory churn and idle work in hot paths: timer texts only rebuild when their value changes, the trinket queue checks once per second instead of every frame, the arena binds its aura events per zone, and the dark skin, bags, tooltips and class trackers reuse what they already computed."] = "Проход по тринадцати файлам сокращает работу с памятью и вхолостую на горячих путях: тексты времени перестраиваются только при смене значения, очередь аксессуаров проверяется раз в секунду вместо каждого кадра, арена привязывает события аур к зоне, а тёмное оформление, сумки, подсказки и отслеживание классов повторно используют уже вычисленное.",
["Not enough free bag space to unequip everything."] = "Недостаточно свободного места в сумках, чтобы снять всё.",
    -- Patch notes 1.58.2
    ["Empty slots are now part of a set: saving records deliberately bare slots, and equipping strips those pieces into the bags, with a single notice when the bags are too full. Sets saved before this change keep their old behavior, so save a set once more to pick up its empty slots."] = "Пустые ячейки теперь часть комплекта: при сохранении отмечаются намеренно свободные ячейки, а при надевании находящиеся там предметы убираются в сумки, с одним уведомлением, если сумки переполнены. Комплекты, сохранённые до этого изменения, ведут себя по-старому; сохраните комплект ещё раз, чтобы он перенял свои пустые ячейки.",
    ["The unit's level at the name's left edge, coloured by how dangerous it is to you."] = "Уровень существа у левого края имени, окрашенный по тому, насколько оно опасно для вас.",
    ["Elite and rare tag"] = "Метка элитных и редких",
    ["Adds + for elite, R for rare, R+ for rare elite and B for world bosses. A tagged level turns gold."] = "Добавляет + для элитных, R для редких, R+ для редких элитных и B для мировых боссов. Уровень с меткой становится золотым.",
    ["Level text size"] = "Размер текста уровня",
    ["0 = uses the name's text size."] = "0 = использует размер текста имени.",
    ["Where the row extends as more icons arrive. Left and right apply to a horizontal row above or below the plate. Up and down give a vertical column beside the plate a fixed starting end instead of staying centred."] = "Куда расширяется ряд, когда появляются новые значки. Влево и вправо действуют для горизонтального ряда над или под полосой. Вверх и вниз дают вертикальной колонке рядом с полосой фиксированное начало вместо выравнивания по центру.",
    ["The icon picker offers the client's complete icon library in a mouse-wheel scrollable grid; the automatic choice and the set's own pieces stay in front."] = "Окно выбора значка предлагает полную библиотеку значков игры в сетке с прокруткой колесом мыши; автоматический выбор и предметы комплекта остаются впереди.",
    ["Stripping pieces into the bags claims an empty slot for every piece before anything moves, so switching to a set with bare slots no longer fails with red bag-is-full errors from stale free-space counts or special bags that cannot hold armor."] = "При снятии предметов в сумки для каждого предмета заранее резервируется пустая ячейка: переключение на комплект со свободными ячейками больше не срывается красными ошибками о переполненной сумке из-за устаревшего подсчёта свободного места или особых сумок, не вмещающих броню.",
    ["Show level – The unit's level at the name's left edge, colored by difficulty, with an elite and rare tag, text size and offsets behind its gear"] = "Показывать уровень – Уровень существа у левого края имени, окрашенный по сложности, с меткой элитных и редких, размером текста и смещениями за шестерёнкой",
    ["Growth direction – Decide where an aura row extends as more icons arrive: left or right for a horizontal row, up or down for a column beside the plate"] = "Направление роста – Решайте, куда расширяется ряд аур, когда появляются новые значки: влево или вправо для горизонтального ряда, вверх или вниз для колонки рядом с полосой",
    ["Broker plugin"] = "Плагин Broker",
    ["Plugin"] = "Плагин",
    ["No broker plugins found"] = "Плагины Broker не найдены",
    ["Strip colors"] = "Убирать цвета",
    ["Max width"] = "Максимальная ширина",
    ["Removes the plugin's own color codes so the text takes the block color."] = "Убирает собственные цветовые коды плагина, чтобы текст принимал цвет блока.",
    ["0 = automatic width. Above 0 the text is cut off at this width."] = "0 = автоматическая ширина. Больше 0 — текст обрезается на этой ширине.",
} end)
